import type { Prompt } from "../prompt-types";

export const WRITING_PROMPTS: Prompt[] = [
  // ---- Writing (1025) ----
  { id: "writing-1", title: "Formal email to my manager", category: "writing", text: "Write a formal email to my manager about [topic, e.g. requesting leave / a work-from-home day]. Keep it polite, under 100 words, with a clear subject line." },
  { id: "writing-2", title: "Leave application for school", category: "writing", text: "Write a leave application to my child's school principal for [number] days because [reason]. Keep it formal, short, and include the dates clearly. Add my phone number for questions." },
  { id: "writing-3", title: "Apology email that sounds sincere", category: "writing", text: "Write a sincere apology email to [a customer / my boss / a friend] for [mistake]. Own the mistake, say what I will do differently, and keep it under 120 words without making excuses." },
  { id: "writing-4", title: "Thank-you email after an interview", category: "writing", text: "Write a thank-you email to send after a job interview for [role] at [company]. Thank the interviewer, mention one thing I enjoyed discussing, and say I look forward to hearing from them. Under 100 words." },
  { id: "writing-5", title: "Cover letter for a job", category: "writing", text: "Write a cover letter for a [role] job at [company]. I have [years] of experience in [field]. Keep it to 3 short paragraphs: why I want the job, what I bring, and a polite closing." },
  { id: "writing-6", title: "Resume summary that stands out", category: "writing", text: "Write a 3-line professional summary for my resume. I am a [role] with [years] of experience in [field], and my biggest strengths are [list 2-3]. Make it confident but honest." },
  { id: "writing-7", title: "Story starter for kids", category: "writing", text: "Give me 10 story starters for a children's story, one line each, about [animals / magic / school / space]. Each one should make a child want to hear what happens next." },
  { id: "writing-8", title: "Poem for a special occasion", category: "writing", text: "Write a short, simple poem for [a birthday / Mother's Day / a farewell] in easy English. 8-12 lines, warm and heartfelt, with simple rhymes a beginner can read aloud." },
  { id: "writing-9", title: "Wedding speech draft", category: "writing", text: "Help me write a 2-minute wedding speech as [the bride's brother / the best friend]. Include one sweet memory, one funny moment, and warm wishes for the couple. Keep it heartfelt and simple." },
  { id: "writing-10", title: "Birthday speech for a friend", category: "writing", text: "Write a 1-minute birthday speech for my best friend [name]. Include one funny memory, one thing I admire about them, and a warm wish. Keep it light and under 150 words." },
  { id: "writing-11", title: "School essay on a topic", category: "writing", text: "Write a school essay on [topic, e.g. my favourite festival / save water] for a Class [6/7/8] student. About 200 words, simple English, with an introduction, 3 main points, and a conclusion." },
  { id: "writing-12", title: "Notice for a housing society", category: "writing", text: "Write a notice for our housing society about [water timings / lift repair / a meeting on date]. Keep it clear, polite, and under 80 words, with the date, time and contact person." },
  { id: "writing-13", title: "Complaint email to a company", category: "writing", text: "Write a complaint email to [company] about [problem]. State the facts in order, mention my order/bill number, and say clearly what I want them to do. Polite but firm, under 150 words." },
  { id: "writing-14", title: "Invitation message for a function", category: "writing", text: "Write a warm invitation message for [a housewarming / a baby shower / a birthday party] on [date] at [place]. Include the time, the address, and a line that makes guests feel welcome." },
  { id: "writing-15", title: "Condolence message", category: "writing", text: "Write a short, respectful condolence message for [a colleague / a neighbour] who lost [a family member]. Keep it gentle, sincere, and under 50 words." },
  { id: "writing-16", title: "Announcement for a community event", category: "writing", text: "Write an announcement for a [blood donation camp / free health checkup / clean-up drive] in our area on [date]. Include the purpose, time, place, and who can join. Keep it under 100 words." },
  { id: "writing-17", title: "Product description for a shop", category: "writing", text: "Write a product description for [product] sold by my shop. Mention what it is made of, who it is for, and why it is good value at ₹[price]. Keep it under 80 words and make it sound appealing." },
  { id: "writing-18", title: "Blog intro that hooks readers", category: "writing", text: "Write 5 different opening paragraphs for a blog post titled [title]. Each should hook the reader in the first 2 lines: one with a question, one with a story, one with a surprising fact, one with a problem, and one with a promise." },
  { id: "writing-19", title: "Newsletter intro for the week", category: "writing", text: "Write a short, friendly introduction for this week's newsletter about [topic]. Welcome readers, say what is inside in 2 lines, and end with a question. Keep it under 80 words." },
  { id: "writing-20", title: "Dialogue between two friends", category: "writing", text: "Write a short dialogue between two friends discussing [topic, e.g. starting a small business / planning a trip]. 10 exchanges, natural spoken English, with one funny line." },
  { id: "writing-21", title: "Book blurb for my story", category: "writing", text: "Write a back-cover blurb for my short story about [one-line plot]. Make it exciting in under 100 words, end with a question that makes a reader want to open the book, and do not give away the ending." },
  { id: "writing-22", title: "LinkedIn summary for my profile", category: "writing", text: "Write a LinkedIn 'About' section for me. I am a [role] with [years] of experience in [field], based in [city]. Keep it to 5 short lines: what I do, what I am good at, and what I am looking for." },
  { id: "writing-23", title: "Polite WhatsApp message", category: "writing", text: "Write a polite WhatsApp message to [a shopkeeper / a teacher / a relative] asking about [something]. Keep it respectful, under 40 words, with a proper greeting and thank-you." },
  { id: "writing-24", title: "Meeting notes summary", category: "writing", text: "Here are my rough meeting notes: [paste them]. Turn them into a clean summary: what was decided, who will do what by when, and what is still open. Keep it to one page in simple English." },
  { id: "writing-25", title: "Speech for school assembly", category: "writing", text: "Write a 2-minute speech for a school morning assembly on [topic, e.g. the importance of reading / saving water]. Start with a greeting, give 3 simple points with one example each, and end with a thought for the day." },
  { id: "writing-26", title: "Email to my bank about a wrong charge", category: "writing", text: "Write a polite email to my bank about a wrong charge of ₹[amount] on [date] in my account [account number]. State the facts clearly, attach the statement as proof, and ask them to reverse the charge and confirm by email." },
  { id: "writing-27", title: "Email to my landlord about a leaking tap", category: "writing", text: "Write a polite email to my landlord about a leaking tap in the [kitchen / bathroom] of my flat at [address]. Explain the problem, say when it started, and ask them to send a plumber this week and confirm the visit time." },
  { id: "writing-28", title: "Email to my child's teacher about homework", category: "writing", text: "Write a polite email to my child's class teacher about homework for [subject]. My child [name] of Class [number] is finding [topic] difficult. Ask for one extra worksheet and a short meeting time to discuss how I can help at home." },
  { id: "writing-29", title: "Email to college office about my marksheet", category: "writing", text: "Write a polite email to my college office asking for my marksheet for [semester / year]. Give my name, roll number, course, and the date I need it by, and ask what documents I should bring when I collect it." },
  { id: "writing-30", title: "Email to HR about my salary slip", category: "writing", text: "Write a polite email to HR asking for my salary slip for [month]. Give my name, employee ID, and department, say why I need it, and ask them to send it by email and confirm once it is sent." },
  { id: "writing-31", title: "Email to a courier company about a late parcel", category: "writing", text: "Write a polite email to a courier company about my parcel [tracking number] that was due on [date] but has not arrived. Ask for the current status, the new delivery date, and a reply by email today." },
  { id: "writing-32", title: "Email to electricity board about a wrong bill", category: "writing", text: "Write a polite email to the electricity board about a wrong bill for [month]. My consumer number is [number], the bill shows ₹[amount] but my usual bill is about ₹[amount]. Ask them to check the meter reading and send a corrected bill." },
  { id: "writing-33", title: "Email to internet provider about slow connection", category: "writing", text: "Write a polite email to my internet provider about very slow internet for the last [number] days. Give my customer ID, my plan speed, and the speed I am actually getting, and ask them to fix it or send a technician." },
  { id: "writing-34", title: "Email to insurance company about a claim", category: "writing", text: "Write a polite email to my insurance company about a claim for [health / vehicle / home] under policy number [number]. Describe what happened on [date], list the documents I have attached, and ask for the claim status and the next step." },
  { id: "writing-35", title: "Email to a doctor's clinic for an appointment", category: "writing", text: "Write a polite email to a doctor's clinic asking for an appointment with Dr [name] for [reason]. Give my name, age, and phone number, say which days suit me, and ask them to confirm the date, time, and consultation fee." },
  { id: "writing-36", title: "Letter to housing society secretary about parking", category: "writing", text: "Write a polite letter to the housing society secretary about a parking problem in [building / block]. Explain that [describe the problem], give my flat number, and ask for a fair rule that works for all residents." },
  { id: "writing-37", title: "Letter to municipal office about garbage collection", category: "writing", text: "Write a polite letter to the municipal office about irregular garbage collection in [area / street] for the last [number] weeks. Give the street name, describe the problem, and ask them to restore daily collection and confirm the schedule." },
  { id: "writing-38", title: "Email to train helpdesk about a refund", category: "writing", text: "Write a polite email to the train helpdesk about a refund for my cancelled ticket, PNR [number], train [number] on [date]. Give my name and bank details for the refund, and ask them to confirm the refund amount and date." },
  { id: "writing-39", title: "Email to airline helpdesk about a missed flight", category: "writing", text: "Write a polite email to the airline helpdesk about my missed flight [flight number] on [date] from [city] to [city]. Explain briefly why I missed it, give my booking reference, and ask what options I have to rebook." },
  { id: "writing-40", title: "Email to online shopping support about a damaged product", category: "writing", text: "Write a polite email to online shopping support about a damaged [product] I received on [date], order number [number]. Describe the damage, say I have photos attached, and ask for a replacement or a full refund." },
  { id: "writing-41", title: "Email to a restaurant for a bulk order", category: "writing", text: "Write a polite email to a restaurant asking for a bulk order of [dish] for [number] people on [date] at [time]. Ask for the per-plate price, the total cost, the advance amount, and the delivery time to [address]." },
  { id: "writing-42", title: "Email to a coaching centre about batch timings", category: "writing", text: "Write a polite email to a coaching centre asking about batch timings for [subject / exam]. My child is in Class [number] and is free after [time]. Ask for the available batches, the fees, and the date the next batch starts." },
  { id: "writing-43", title: "Email to a library about membership renewal", category: "writing", text: "Write a polite email to a library asking how to renew my membership. Give my name and membership number, say my membership ends on [date], and ask for the renewal fee, the documents needed, and the library timings." },
  { id: "writing-44", title: "Letter to a newspaper editor about road safety", category: "writing", text: "Write a letter to a newspaper editor about road safety near [school / area]. Describe the danger in 3 lines, suggest 2 practical fixes, and ask the paper to highlight the issue so the authorities take action. Keep it under 150 words." },
  { id: "writing-45", title: "Job application follow-up email", category: "writing", text: "Write a polite follow-up email after applying for the [role] job at [company] on [date]. Remind them of my application, mention one strength that fits the role, and ask politely about the next step in the hiring process." },
  { id: "writing-46", title: "Request for experience certificate", category: "writing", text: "Write a polite email to HR asking for my experience certificate. I worked as [role] at [company] from [date] to [date]. Ask them to mention my role and tenure, and say when I can collect the certificate." },
  { id: "writing-47", title: "Request for fee receipt from school", category: "writing", text: "Write a polite email to my child's school office asking for a fee receipt for [term / year]. Give my child's name, class, and admission number, say I paid ₹[amount] on [date], and ask them to send the receipt by email." },
  { id: "writing-48", title: "Request for transfer certificate", category: "writing", text: "Write a polite letter to the school principal asking for a transfer certificate for my child [name] of Class [number]. Say we are moving to [city] on [date], and ask what forms to fill and when the certificate will be ready." },
  { id: "writing-49", title: "Permission letter for a school trip", category: "writing", text: "Write a permission letter to my child's school for the school trip to [place] on [date]. Give my child's name and class, say I allow them to join, give my phone number for emergencies, and note any health point the teacher should know." },
  { id: "writing-50", title: "Request for a no-objection letter", category: "writing", text: "Write a polite letter asking for a no-objection letter from [office / society / employer] for [purpose, e.g. a passport / a visa / a new job]. Give my name and details, explain why I need it, and ask when it will be ready." },
  { id: "writing-51", title: "Address change letter to my bank", category: "writing", text: "Write a formal letter to my bank asking them to update my address. Give my name, account number, old address, and new address, list the proof I have attached, and ask them to confirm the change by email." },
  { id: "writing-52", title: "Name correction letter to my college", category: "writing", text: "Write a polite letter to my college office asking them to correct the spelling of my name from [wrong spelling] to [correct spelling]. Give my roll number and course, and list the ID proof I have attached." },
  { id: "writing-53", title: "Refund request to an online store", category: "writing", text: "Write a polite email to an online store asking for a refund for [product], order number [number], which I returned on [date]. Give the amount paid, my payment method, and ask them to confirm the refund date." },
  { id: "writing-54", title: "Complaint about a delivery delay", category: "writing", text: "Write a firm but polite complaint email to an online store about a delivery delay. My order [number] was due on [date] but has not arrived. Ask for a clear delivery date today and a reply by email." },
  { id: "writing-55", title: "Complaint about an overcharged mobile bill", category: "writing", text: "Write a polite complaint email to my mobile company about an overcharged bill for [month]. My number is [number], the bill shows ₹[amount] but my plan costs ₹[amount]. Ask them to check and send a corrected bill." },
  { id: "writing-56", title: "Request to cancel a subscription", category: "writing", text: "Write a polite email asking to cancel my subscription to [service] from [date]. Give my account ID and the reason in one line, and ask them to confirm the cancellation and that no further amount will be charged." },
  { id: "writing-57", title: "Phone script to book a dentist appointment", category: "writing", text: "Write out exactly what I should say on a phone call to book a dentist appointment for [tooth pain / cleaning / check-up]. Include how to introduce myself, what details to give, which days suit me, and what to ask about the fee and what to bring. Keep it in simple, polite spoken English." },
  { id: "writing-58", title: "Request to reschedule an interview", category: "writing", text: "Write a polite email asking to reschedule my job interview for [role] at [company] from [old date] to a later date. Explain the reason briefly, apologise for the change, and ask for 2 or 3 new time options." },
  { id: "writing-59", title: "Feedback letter to a hotel after a stay", category: "writing", text: "Write a polite feedback letter to a hotel where I stayed from [date] to [date], booking number [number]. Mention 2 things I liked, one thing that could improve, and thank the staff by name if I know it." },
  { id: "writing-60", title: "Suggestion letter to my school about a library", category: "writing", text: "Write a polite suggestion letter to my child's school principal asking them to improve the school library. Suggest 3 simple ideas, such as more story books and longer library hours, and explain why they would help students." },
  { id: "writing-61", title: "Enquiry letter to a travel agent about a package", category: "writing", text: "Write a polite enquiry email to a travel agent about a holiday package to [place] for [number] people for [number] days in [month]. Ask for the total price, what is included, and the booking and cancellation terms." },
  { id: "writing-62", title: "Introduction letter for my child to a new school", category: "writing", text: "Write a warm introduction letter to the principal of a new school for my child [name], who is joining Class [number]. Mention their interests and one strength, and ask for a short meeting to discuss the admission." },
  { id: "writing-63", title: "Request for a recommendation letter from a teacher", category: "writing", text: "Write a polite email to my teacher asking for a recommendation letter for [a college admission / a scholarship / a job]. Remind them of my class and year, say the last date for the letter, and thank them for their help." },
  { id: "writing-64", title: "Request for a character certificate", category: "writing", text: "Write a polite letter to my school principal asking for a character certificate for [name], who studied in Class [number] in [year]. Give the roll number, say why the certificate is needed, and ask when it will be ready." },
  { id: "writing-65", title: "Request for a bonafide certificate", category: "writing", text: "Write a polite letter to my college office asking for a bonafide certificate for [name], roll number [number], studying in [course / year]. Say why I need it, and ask for the fee and the date I can collect it." },
  { id: "writing-66", title: "Email to bank about a lost debit card", category: "writing", text: "Write an urgent email to my bank saying I have lost my debit card for account [account number]. Ask them to block the card at once, tell me the steps to get a new card, and confirm the blocking by email and SMS." },
  { id: "writing-67", title: "Email to landlord about rent receipt", category: "writing", text: "Write a polite email to my landlord asking for a rent receipt for [month]. I paid ₹[amount] on [date] by [cash / bank transfer / UPI]. Give my flat address and ask them to send the signed receipt this week." },
  { id: "writing-68", title: "Email to school about bus route change", category: "writing", text: "Write a polite email to my child's school transport office about a change in our bus stop. Give my child's name, class, and admission number, state the old stop and the new stop, and ask them to confirm the change." },
  { id: "writing-69", title: "Email to HR about updating my bank details", category: "writing", text: "Write a polite email to HR asking them to update my bank details for salary payment. Give my name and employee ID, state my new bank name and account number, and ask them to confirm the update before the next salary date." },
  { id: "writing-70", title: "Email to courier company about a wrong address", category: "writing", text: "Write a polite email to a courier company saying my parcel [tracking number] is going to a wrong address. Give the correct address clearly, ask them to redirect the parcel, and ask for a reply confirming the new delivery date." },
  { id: "writing-71", title: "Letter to electricity board about a power cut", category: "writing", text: "Write a polite letter to the electricity board about frequent power cuts in [area / street] for the last [number] days. Give the consumer number and street name, describe the timings, and ask them to fix the fault and inform residents." },
  { id: "writing-72", title: "Email to insurance company about renewing my policy", category: "writing", text: "Write a polite email to my insurance company asking how to renew my [health / vehicle] policy number [number] before it ends on [date]. Ask for the renewal amount, the payment link, and whether the terms have changed." },
  { id: "writing-73", title: "Email to municipal office about a street light", category: "writing", text: "Write a polite email to the municipal office about a street light that has not worked for [number] days on [street name] in [area]. Explain the safety problem at night, and ask them to repair it this week and confirm." },
  { id: "writing-74", title: "Email to online shopping support about a wrong item delivered", category: "writing", text: "Write a polite email to online shopping support about a wrong item delivered in order number [number] on [date]. I ordered [item] but received [different item]. Ask for a pickup and a replacement of the correct item." },
  { id: "writing-75", title: "Request to reschedule a doctor's appointment", category: "writing", text: "Write a polite email to a doctor's clinic asking to reschedule my appointment on [old date] to a later date. Give my name and appointment number, explain the reason briefly, and ask for 2 or 3 new time options." },
  { id: "writing-76", title: "Short story idea about a lost ticket", category: "writing", text: "Give me five short story ideas about a lost train ticket in India. For each idea, give the main character, the place, and one surprising twist. Keep each idea to two lines so I can pick one and write the full story." },
  { id: "writing-77", title: "Story ending rewrite for a twist", category: "writing", text: "Here is the ending of my story: [paste the ending]. Rewrite it with a surprising twist that still makes sense. Give me two versions, one happy and one thoughtful, each under 100 words, and say which one you think works better." },
  { id: "writing-78", title: "Moral story for children about honesty", category: "writing", text: "Write a short moral story for children about honesty, set in an Indian village. The main character is a [boy or girl] aged [age] who finds a lost purse. Keep it under 250 words, in simple English, and end with one clear moral line." },
  { id: "writing-79", title: "Funny story about a school bus", category: "writing", text: "Write a funny short story about a school bus that breaks down on the way to a picnic in India. Include three funny moments, a kind driver, and a happy ending. Keep it under 250 words in simple English for children aged eight to twelve." },
  { id: "writing-80", title: "Gentle ghost story for kids", category: "writing", text: "Write a gentle ghost story for children aged eight to ten, set in an old house in a small Indian town. The ghost should be friendly and funny, not scary. Keep it under 250 words, with a happy ending and one simple lesson about kindness." },
  { id: "writing-81", title: "Animal story about a clever crow", category: "writing", text: "Write a short animal story about a clever crow who helps a farmer in a dry village in India. Show how the crow solves a water problem in three clever steps. Keep it under 250 words, in simple English, with a clear moral at the end." },
  { id: "writing-82", title: "Village story about a harvest festival", category: "writing", text: "Write a short village story about a harvest festival in Tamil Nadu where a young girl saves the celebration. Include the festival food, the village people, and one problem she solves. Keep it under 250 words in simple, warm English." },
  { id: "writing-83", title: "Festival story about Diwali night", category: "writing", text: "Write a short festival story about a Diwali night in a small town in India, told by a child. Include diyas, sweets, family, and one small surprise that makes the night special. Keep it under 250 words in simple, joyful English." },
  { id: "writing-84", title: "Friendship story about two classmates", category: "writing", text: "Write a short friendship story about two classmates in India who fall out over a cricket match and make up again. Show what each one learns about saying sorry. Keep it under 250 words, in simple English, with a warm ending." },
  { id: "writing-85", title: "Poem about mother", category: "writing", text: "Write a short poem about my mother in simple English, 8 to 12 lines, with easy rhymes. Mention her morning cooking, her hard work, and her smile. Keep the words warm and heartfelt, so I can read it aloud at home." },
  { id: "writing-86", title: "Poem about rain in my town", category: "writing", text: "Write a short poem about rain falling on my town in India, 8 to 12 lines, in simple English. Describe the clouds, the wet streets, children playing, and the smell of wet earth. Use easy rhymes and a joyful, gentle mood." },
  { id: "writing-87", title: "Poem about my town", category: "writing", text: "Write a short poem about my town [town name] in India, 8 to 12 lines, in simple English. Mention the main street, the temple or market, the people, and one thing I love most about living here. Keep it warm and proud." },
  { id: "writing-88", title: "Poem about cricket", category: "writing", text: "Write a short poem about playing cricket with friends on a Sunday in India, 8 to 12 lines, in simple English. Mention the bat, the ball, the cheering friends, and the joy of winning or losing together. Use easy rhymes and a lively mood." },
  { id: "writing-89", title: "Acrostic poem with my name", category: "writing", text: "Write an acrostic poem using my name [name], where each line starts with one letter of my name. The poem should describe me in simple, kind words. Keep it to one line per letter, in easy English, so I can share it with my family." },
  { id: "writing-90", title: "Haiku for beginners about nature", category: "writing", text: "Teach me to write a haiku in simple words, then write five haikus about nature in India, about rain, a mango tree, the morning sun, a river, and a peacock. Each haiku should have three lines with five, seven and five syllables." },
  { id: "writing-91", title: "Limerick about a funny teacher", category: "writing", text: "Write a funny limerick about my teacher [name or subject] in simple English. It should have five lines, with a clear rhythm and a funny ending. Keep it kind and respectful, so I can read it aloud in class without embarrassing anyone." },
  { id: "writing-92", title: "Farewell poem for a teacher", category: "writing", text: "Write a farewell poem for my teacher [name] who is leaving our school, 8 to 12 lines, in simple English. Thank them for their patience and lessons, mention one happy class memory, and wish them well. Keep it warm and easy to read aloud." },
  { id: "writing-93", title: "Retirement speech for a teacher", category: "writing", text: "Help me write a two-minute retirement speech for my teacher [name] who taught at our school for [years] years. Mention their kindness, one story students remember, and our thanks. Keep it warm, simple and under 250 words." },
  { id: "writing-94", title: "Chief guest welcome speech", category: "writing", text: "Write a short welcome speech for the chief guest [name] at our school function on [date]. Introduce the guest in two lines, say why we invited them, and welcome them warmly on behalf of all students and teachers. Keep it under 200 words." },
  { id: "writing-95", title: "Vote of thanks for a school function", category: "writing", text: "Write a vote of thanks speech for our school function on [date]. Thank the chief guest, the principal, the teachers, the parents, and the student volunteers, each in one line. Keep it polite, warm and under 200 words, in simple English." },
  { id: "writing-96", title: "Anchoring script for school annual day", category: "writing", text: "Write an anchoring script for our school annual day function, with opening lines, introductions for five performances, and a closing line. Keep the language simple, cheerful and easy to speak on stage, with a short joke between two items." },
  { id: "writing-97", title: "Anchoring script for a wedding", category: "writing", text: "Write an anchoring script for a wedding reception in India, with a warm welcome, introductions for the bride and groom, and lines to invite family members on stage. Keep it joyful, respectful and simple, with one light joke that suits a family audience." },
  { id: "writing-98", title: "Debate speech for school uniforms", category: "writing", text: "Write a two-minute debate speech in favour of school uniforms in India. Give three clear points, one example for each point, and a strong closing line. Use simple English that a Class 8 student can speak confidently on stage." },
  { id: "writing-99", title: "Debate speech against junk food in canteens", category: "writing", text: "Write a two-minute debate speech against junk food in school canteens in India. Open with a question to the audience, give three clear points with one example each, and end with a call to action asking the school to serve healthier food. Use simple English a Class 8 student can speak confidently." },
  { id: "writing-100", title: "Elocution speech on saving water", category: "writing", text: "Write a two-minute elocution speech on saving water for a school competition. Start with a greeting, give three simple ways to save water at home, and end with a thought for the day. Use simple English and short sentences for a young speaker." },
  { id: "writing-101", title: "Essay on my favourite teacher", category: "writing", text: "Write a school essay on my favourite teacher [name] for a Class 7 student. About 200 words, in simple English, with an introduction, three reasons I admire them with one example each, and a short conclusion about what I learned from them." },
  { id: "writing-102", title: "Essay on my village", category: "writing", text: "Write a school essay on my village [village name] for a Class 6 student. About 200 words, in simple English, describing the houses, the fields, the people, and the festival we celebrate together. End with why I love my village." },
  { id: "writing-103", title: "Essay on a train journey", category: "writing", text: "Write a school essay on a train journey from [city] to [city] for a Class 7 student. About 200 words, in simple English, describing the stations, the food, the people I met, and what I saw from the window. End with my favourite memory." },
  { id: "writing-104", title: "Essay on my dream job", category: "writing", text: "Write a school essay on my dream job as a [job, for example doctor, teacher or pilot] for a Class 8 student. About 200 words, in simple English, explaining why I chose it, what the job does, and what I will study to reach it." },
  { id: "writing-105", title: "Paragraph writing practice on my pet", category: "writing", text: "Give me a paragraph writing practice exercise on my pet [pet type and name] for a Class 5 student. First give a model paragraph of about 80 words, then give five guiding questions, then leave space for me to write my own paragraph." },
  { id: "writing-106", title: "Diary entry about my first day at school", category: "writing", text: "Write a diary entry about my first day at a new school in India, in the voice of a Class 6 student. Include how I felt in the morning, one new friend I made, and one funny moment. Keep it under 200 words in simple, honest English." },
  { id: "writing-107", title: "Letter to a friend about my holidays", category: "writing", text: "Write a letter to my friend [name] telling them about my school holidays in [place]. Describe two fun things I did, one new thing I learned, and invite them to visit me next holidays. Keep it warm, simple and under 200 words." },
  { id: "writing-108", title: "Letter to grandmother", category: "writing", text: "Write a letter to my grandmother in [village or city] thanking her for the holidays I spent with her. Mention her cooking, one story she told me, and how much I miss her. Keep it warm, simple and under 200 words, in easy English." },
  { id: "writing-109", title: "Letter to my younger self", category: "writing", text: "Write a letter to my younger self at age [age], in simple English. Share three lessons I have learned since then, one mistake I would avoid, and one encouragement to keep going. Keep it honest, kind and under 250 words." },
  { id: "writing-110", title: "Letter to my future self", category: "writing", text: "Write a letter to my future self five years from now, in simple English. Describe my dreams today, three goals I hope to reach, and one question I want my future self to answer. Keep it hopeful, honest and under 250 words." },
  { id: "writing-111", title: "Postcard from a trip to the hills", category: "writing", text: "Write a postcard from a trip to the hills in [place], to send to my friend [name]. In under 60 words, describe the weather, one beautiful view, and the food I tasted. Keep it cheerful and simple, with a warm greeting and a short sign-off." },
  { id: "writing-112", title: "Short story about a kind stranger", category: "writing", text: "Write a short story about a kind stranger who helps a lost child find the way home in a busy Indian city. Include the market, a helpful shopkeeper, and a happy reunion with the family. Keep it under 250 words in simple English." },
  { id: "writing-113", title: "Story about a brave little girl", category: "writing", text: "Write a short story about a brave little girl in a village in India who saves her goat from a flood. Show her courage in three small steps, with help from her grandmother. Keep it under 250 words in simple, warm English." },
  { id: "writing-114", title: "Poem about the morning sun", category: "writing", text: "Write a short poem about the morning sun rising over my village in India, 8 to 12 lines, in simple English. Describe the golden light, the birds singing, and farmers starting work. Use easy rhymes and a hopeful, peaceful mood." },
  { id: "writing-115", title: "Poem about my best friend", category: "writing", text: "Write a short poem about my best friend [name] in simple English, 8 to 12 lines, with easy rhymes. Mention playing together, sharing lunch, and helping each other in school. Keep it warm, fun and easy to read aloud to my friend." },
  { id: "writing-116", title: "Speech for a prize distribution day", category: "writing", text: "Write a two-minute speech for a school prize distribution day, to be read by a student. Congratulate the prize winners, thank the teachers and parents, and encourage every student to keep trying. Keep it joyful, simple and under 250 words." },
  { id: "writing-117", title: "Essay on my favourite festival", category: "writing", text: "Write a school essay on my favourite festival [festival name] for a Class 6 student. About 200 words, in simple English, describing how my family celebrates it, the food we eat, and why this festival makes me happy every year." },
  { id: "writing-118", title: "Essay on a rainy day at home", category: "writing", text: "Write a school essay on a rainy day at home for a Class 6 student. About 200 words, in simple English, describing the rain outside, what I did indoors, and the hot food my mother made. End with why I enjoyed that quiet day." },
  { id: "writing-119", title: "Diary entry about a cricket match", category: "writing", text: "Write a diary entry about a cricket match I played with friends on Sunday in India. Describe the match in three parts, how I felt when we won or lost, and one lesson I learned. Keep it under 200 words in simple, honest English." },
  { id: "writing-120", title: "Letter to my brother about a new book", category: "writing", text: "Write a letter to my brother [name] telling him about a new book I read called [title]. Describe the story in three lines, say why I liked it, and ask him to read it too. Keep it warm, simple and under 200 words." },
  { id: "writing-121", title: "Story about a magic mango tree", category: "writing", text: "Write a short story for children about a magic mango tree in a village in India that gives fruit only to kind people. Include a greedy man, a kind girl, and a happy ending. Keep it under 250 words in simple English, with a clear moral." },
  { id: "writing-122", title: "Poem about the sea", category: "writing", text: "Write a short poem about the sea at [place, for example Marina Beach in Chennai], 8 to 12 lines, in simple English. Describe the waves, the sand, the fishermen, and the sunset. Use easy rhymes and a calm, happy mood that suits a school recitation." },
  { id: "writing-123", title: "Anchoring script for a cultural programme", category: "writing", text: "Write an anchoring script for a cultural programme at our college, with opening lines, introductions for a dance, a song and a drama, and a closing thank-you. Keep the language simple, lively and easy to speak on stage for a first-time anchor." },
  { id: "writing-124", title: "Debate speech for mobile phones in school", category: "writing", text: "Write a three-minute debate speech in favour of allowing mobile phones in school for learning in India. Open with a short real-life story, give three clear points with one example each, and end by asking the audience one question to think about. Use simple English a Class 9 student can speak confidently on stage." },
  { id: "writing-125", title: "Short story about a lost puppy", category: "writing", text: "Write a short story about a lost puppy that a schoolboy finds near his home in India and helps return to its owner. Include the search, one kind neighbour, and a joyful reunion. Keep it under 250 words in simple, warm English." },
  { id: "writing-126", title: "Product description for handmade soap", category: "writing", text: "Write a product description for my handmade soap made with [main ingredient]. Say what it is good for, who should use it, and how to use it. Mention the weight, the price, and that it is made in small batches. Keep it under 80 words and warm." },
  { id: "writing-127", title: "Product description for a saree", category: "writing", text: "Write a product description for a [cotton / silk] saree in [colour] from my shop. Describe the fabric, the border, and the blouse piece, and say which occasion it suits. Mention the price and washing care in simple words. Keep it under 80 words." },
  { id: "writing-128", title: "Product description for homemade pickles", category: "writing", text: "Write a product description for my homemade [mango / lemon] pickle. Say the main ingredients, how spicy it is, and what food it goes well with. Mention the jar size, the price, and that it has no added colour. Keep it under 80 words and honest." },
  { id: "writing-129", title: "Website homepage text for my shop", category: "writing", text: "Write homepage text for my shop website selling [products] in [city]. Include a warm welcome line, what I sell, why customers trust me, and a clear line telling visitors how to order. Keep it under 120 words in simple English." },
  { id: "writing-130", title: "Website about-us page for my shop", category: "writing", text: "Write an about-us page for my shop website. Say when I started, what I sell, who I serve, and what I care about most in my work. Keep it honest, warm, and under 150 words, in simple English that a first-time visitor can trust." },
  { id: "writing-131", title: "About section for my shop page", category: "writing", text: "Write a short about section for my shop page on social media. Say what I sell, where I am based, and how to order, in 3 short lines. Keep it under 50 words, clear and friendly, with one line inviting customers to message me." },
  { id: "writing-132", title: "Service description for tailoring", category: "writing", text: "Write a service description for my tailoring shop. List the services I offer, like stitching, alterations, and blouse making, with the starting price for each. Say how long each job takes and how customers can book. Keep it clear and under 120 words." },
  { id: "writing-133", title: "Service description for tuition classes", category: "writing", text: "Write a service description for my tuition classes for [subject] in [city]. Say which classes I teach, the timings, the fees, and how I teach in simple words. Add one line on a free trial class. Keep it under 120 words and warm." },
  { id: "writing-134", title: "Service description for home cleaning", category: "writing", text: "Write a service description for my home-cleaning service in [city]. List what is included, like kitchen, bathroom, and floor cleaning, the charges per visit, and the areas I cover. Keep it simple, honest, and under 120 words." },
  { id: "writing-135", title: "Rate card wording for my services", category: "writing", text: "Write clear wording for my rate card for [service, e.g. tailoring / tuition / cleaning]. List each service with its price in rupees, say what is included, and add one line on extra charges. Keep it neat, honest, and easy to read on one page." },
  { id: "writing-136", title: "Price list intro for my shop", category: "writing", text: "Write a short introduction for the price list of my shop selling [products]. Welcome customers, say prices may change with seasons, and invite them to ask about offers. Keep it under 60 words, warm and clear, in simple English." },
  { id: "writing-137", title: "Blog post outline for a topic", category: "writing", text: "Make a blog post outline for a post titled [title] for my shop blog. Give an introduction idea, 3 main points with one example each, and a conclusion idea. Keep the outline short, clear, and easy for a beginner to write from." },
  { id: "writing-138", title: "Blog conclusion that leaves a thought", category: "writing", text: "Write 3 different conclusions for my blog post about [topic]. Each should sum up the main point in 2 lines, leave the reader with one thought to remember, and end with a gentle question. Keep each conclusion under 50 words." },
  { id: "writing-139", title: "Blog title ideas for a topic", category: "writing", text: "Give me 10 blog title ideas for a blog post about [topic] for Indian readers. Mix question titles, how-to titles, and list titles. Each title should be under 10 words, clear, and honest about what the post will say." },
  { id: "writing-140", title: "How-to blog post on a topic", category: "writing", text: "Write a how-to blog post about [topic, e.g. starting a small shop / packing food for travel]. Use 5 clear steps in order, one tip after each step, and a short introduction and ending. Keep it under 300 words in simple English." },
  { id: "writing-141", title: "List blog post with 10 points", category: "writing", text: "Write a list blog post titled [title] with 10 points about [topic]. Give each point a short heading and 2 lines of simple explanation. Keep the whole post under 300 words and end with one line inviting readers to share their own point." },
  { id: "writing-142", title: "Comparison blog post on two options", category: "writing", text: "Write a comparison blog post comparing [option A] and [option B] for [use, e.g. daily use / a small shop]. Cover price, quality, ease of use, and who each one suits. End with a fair suggestion, not a pushy sale. Keep it under 300 words." },
  { id: "writing-143", title: "Newsletter welcome email for new readers", category: "writing", text: "Write a welcome email for new readers of my newsletter about [topic]. Thank them for joining, say what they will get each week, and how often I will write. Keep it warm, under 100 words, and end with a question about what they want to read." },
  { id: "writing-144", title: "Newsletter farewell email for readers who leave", category: "writing", text: "Write a kind farewell email for readers who leave my newsletter about [topic]. Thank them for reading so far, say they can join again any time, and ask one short question about why they left. Keep it gentle and under 80 words." },
  { id: "writing-145", title: "Newsletter festival edition intro", category: "writing", text: "Write an introduction for the festival edition of my newsletter about [festival]. Wish readers warmly, say what is inside this edition, and mention one special offer for readers. Keep it cheerful, under 80 words, and easy to read." },
  { id: "writing-146", title: "Email subject lines for a sale", category: "writing", text: "Write 10 email subject lines for a sale email from my shop selling [products]. Mix lines that mention the discount, the last date, and a new product. Each line should be under 8 words, clear, and honest, with no false urgency." },
  { id: "writing-147", title: "Email subject lines for a newsletter", category: "writing", text: "Write 10 email subject lines for my weekly newsletter about [topic]. Mix question lines, tip lines, and story lines. Each line should be under 8 words, friendly, and honest about what is inside the email." },
  { id: "writing-148", title: "Abandoned-cart reminder for my shop", category: "writing", text: "Write a gentle abandoned-cart reminder message for a customer who left [product] in their cart at my online shop. Remind them it is still saved, mention the price, and ask if they need help choosing. Keep it under 60 words and never pushy." },
  { id: "writing-149", title: "Order-confirmation message for a customer", category: "writing", text: "Write an order-confirmation message for a customer who ordered [product] from my shop. Say thank you, repeat the order details and total price, and say when the order will be packed and sent. Keep it clear and under 80 words." },
  { id: "writing-150", title: "Delivery message for a customer", category: "writing", text: "Write a delivery message for a customer whose order of [product] is on its way. Say it has been sent, give the expected delivery date, and explain that a tracking link will follow. Keep it friendly and under 60 words." },
  { id: "writing-151", title: "Appointment-confirmation message for a customer", category: "writing", text: "Write an appointment-confirmation message for a customer booked with me on [date] at [time] for [service]. Repeat the date, time, and place, say what they should bring, and ask them to reply to confirm. Keep it under 60 words." },
  { id: "writing-152", title: "Payment-received message for a customer", category: "writing", text: "Write a payment-received message for a customer who paid ₹[amount] for [product or service]. Thank them, confirm the amount and the date, and say their order or booking is now confirmed. Keep it polite and under 50 words." },
  { id: "writing-153", title: "Invoice note for a customer", category: "writing", text: "Write a short note to add at the bottom of an invoice for [product or service]. Thank the customer, say payment is due by [date], and give the payment options in simple words. Keep it polite, clear, and under 60 words." },
  { id: "writing-154", title: "Quotation letter for a client", category: "writing", text: "Write a quotation letter for a client who asked for the price of [service or product]. List each item with its price in rupees, say how long the quote is valid, and add one line on payment terms. Keep it professional and under 150 words." },
  { id: "writing-155", title: "Proposal for a client project", category: "writing", text: "Write a short proposal for a client for [project or service]. Say what I will do, how long it will take, what it will cost, and what the client gets at the end. Keep it clear, honest, and under 150 words in simple English." },
  { id: "writing-156", title: "Service agreement in simple words", category: "writing", text: "Write a simple service agreement for my [service] in plain English. Cover what I will do, the price, the timings, how payment works, and what happens if either side needs to cancel. Keep it under 200 words and easy to understand." },
  { id: "writing-157", title: "Terms for my home business", category: "writing", text: "Write simple terms for my home business selling [products]. Cover ordering, payment, delivery time, returns, and that prices may change. Keep it fair, clear, and under 150 words, in plain English with no legal jargon." },
  { id: "writing-158", title: "Privacy note for my shop", category: "writing", text: "Write a short privacy note for my shop website. Say what customer details I collect, like name and address, that I use them only for orders, and that I never share them with others. Keep it honest and under 100 words." },
  { id: "writing-159", title: "FAQ page writing for my website", category: "writing", text: "Write an FAQ page for my website selling [products]. Answer 8 questions about ordering, payment, delivery, returns, sizes, and contact. Keep each answer to 2 short lines in plain English and use a friendly tone throughout." },
  { id: "writing-160", title: "Google Business profile description", category: "writing", text: "Write a description for my Google Business profile for my shop selling [products] in [city]. Say what I sell, my timings, and that customers can call or message to order. Keep it under 750 characters and use simple, honest words." },
  { id: "writing-161", title: "WhatsApp catalogue intro for my shop", category: "writing", text: "Write a short introduction for my WhatsApp catalogue for my shop selling [products]. Welcome customers, say how to browse and order, and that they can ask questions any time. Keep it under 60 words and friendly." },
  { id: "writing-162", title: "Shop banner text for a festival", category: "writing", text: "Write shop banner text for a festival offer at my shop for [festival]. Give a short headline under 6 words, one line about the offer, and the dates. Keep it bold, clear, and honest, with no false claims." },
  { id: "writing-163", title: "Product label text for homemade food", category: "writing", text: "Write label text for my homemade [pickles / sweets / snacks] sold from home. Include the product name, ingredients, weight, price, and a best-before date line. Keep it clear, honest, and easy to read in small print." },
  { id: "writing-164", title: "Thank-you card message for a parcel", category: "writing", text: "Write a short thank-you card message to put inside a parcel of [product] for a customer. Thank them for the order, say I hope they enjoy it, and invite them to message me with feedback. Keep it warm and under 40 words." },
  { id: "writing-165", title: "Referral message for customers to share", category: "writing", text: "Write a short referral message customers can forward to friends about my shop selling [products]. Say what I sell, the referral reward, and how to order. Keep it under 50 words, friendly, and easy to copy and share." },
  { id: "writing-166", title: "Feedback-request message after delivery", category: "writing", text: "Write a feedback-request message to send after delivering [product] to a customer. Thank them, ask one short question about the product, and say their reply helps me improve. Keep it polite, under 50 words, and never pushy." },
  { id: "writing-167", title: "Apology message for a late delivery", category: "writing", text: "Write a polite apology message for a late delivery of [product] to a customer. Say sorry, give the new delivery date, and explain the delay in one honest line. Offer a small goodwill gesture if suitable. Keep it under 70 words." },
  { id: "writing-168", title: "Reorder reminder message for a customer", category: "writing", text: "Write a gentle reorder reminder message for a customer who bought [product] [number] weeks ago. Say it may be time to order again, mention the price, and ask if they want the same one. Keep it friendly and under 50 words." },
  { id: "writing-169", title: "New service announcement letter", category: "writing", text: "Write a letter to my old customers announcing a new service: [service] at my shop. Say what it is, the starting price, and when it starts. Keep it warm, under 100 words, and end with an invitation to try it first." },
  { id: "writing-170", title: "Price-change notice for customers", category: "writing", text: "Write a polite price-change notice for customers of my shop. Say the price of [product] is changing from ₹[old price] to ₹[new price] from [date], explain the reason in one honest line, and thank customers for understanding. Keep it under 80 words." },
  { id: "writing-171", title: "Holiday notice for my shop", category: "writing", text: "Write a holiday notice for my shop closed on [dates] for [festival or reason]. Say the last working day, when I reopen, and that orders placed during the break will be sent after reopening. Keep it clear and under 60 words." },
  { id: "writing-172", title: "Seasonal offer letter to old customers", category: "writing", text: "Write a seasonal offer letter to my old customers for [festival or season]. Thank them for buying before, share one offer on [product], and say the offer dates. Keep it warm, personal, and under 100 words." },
  { id: "writing-173", title: "Welcome message for a new customer", category: "writing", text: "Write a warm welcome message for a new customer who just bought [product] from my shop. Thank them, say what to expect next, and invite them to message me with any question. Keep it friendly and under 50 words." },
  { id: "writing-174", title: "Birthday message for a regular customer", category: "writing", text: "Write a short birthday message for a regular customer named [first name]. Wish them a happy birthday, thank them for shopping with me, and offer a small birthday discount on their next order. Keep it warm and under 40 words." },
  { id: "writing-175", title: "Out-of-office message for my shop", category: "writing", text: "Write a polite out-of-office message for my shop on WhatsApp. Say I am away until [date], that messages will be answered on my return, and give an urgent contact only if there is one. Keep it short, clear, and under 40 words." },
  { id: "writing-176", title: "Thank-you note to a teacher", category: "writing", text: "Write a warm thank-you note to my teacher [name] for helping me understand [subject]. Mention one lesson I will never forget, say how their patience helped me, and end with a simple wish for their health and happiness. Keep it under 100 words." },
  { id: "writing-177", title: "Thank-you note to a doctor", category: "writing", text: "Write a polite thank-you note to Dr [name] for treating [family member] with care during [illness or treatment]. Mention the kindness of the hospital staff, say how much better the patient feels now, and end with a sincere wish for the doctor." },
  { id: "writing-178", title: "Thank-you note to a neighbour", category: "writing", text: "Write a warm thank-you note to my neighbour [name] for helping us when [describe the help, e.g. during a power cut or a family emergency]. Mention what they did, say how much it meant to our family, and offer to help them in return." },
  { id: "writing-179", title: "Birthday card message for mother", category: "writing", text: "Write a warm birthday card message for my mother. Mention one sacrifice she made for our family, one quality I admire most in her, and a wish for her health and happiness. Keep it heartfelt, simple, and under 80 words." },
  { id: "writing-180", title: "Birthday card message for father", category: "writing", text: "Write a warm birthday card message for my father. Mention one lesson he taught me, one hard time he stood by our family, and a wish for his health and happiness. Keep it heartfelt, simple, and under 80 words." },
  { id: "writing-181", title: "Birthday card for a child", category: "writing", text: "Write a fun birthday card message for a child who is turning [age]. Mention their favourite game or hobby, wish them a day full of cake, games, and friends, and end with a sweet line from [your name]. Keep it playful and under 60 words." },
  { id: "writing-182", title: "Anniversary wishes", category: "writing", text: "Write a warm anniversary message for a couple celebrating [number] years together. Mention their love and patience, one happy wish for the years ahead, and a line about their family. Keep it under 60 words and suitable for a card or WhatsApp." },
  { id: "writing-183", title: "Housewarming wishes", category: "writing", text: "Write a warm housewarming message for a family who just moved into their new home in [place]. Wish them happiness, health, and good memories in the new house, and mention one blessing for the family. Keep it under 60 words." },
  { id: "writing-184", title: "New-baby wishes", category: "writing", text: "Write a warm message to congratulate parents on the birth of their [baby boy or baby girl] named [name]. Wish the baby good health and a happy life, and wish the parents strength and joy. Keep it gentle, simple, and under 60 words." },
  { id: "writing-185", title: "Exam wishes", category: "writing", text: "Write a short, encouraging message to wish a student good luck for their [exam name] starting on [date]. Tell them to stay calm, trust their preparation, and do their best, and end with a warm wish from [your name]. Keep it under 60 words." },
  { id: "writing-186", title: "Get-well-soon message", category: "writing", text: "Write a gentle get-well-soon message for [name] who is recovering from [illness]. Wish them rest, strength, and a speedy recovery, say we are thinking of them, and offer one simple help. Keep it warm, short, and under 60 words." },
  { id: "writing-187", title: "New-job wishes", category: "writing", text: "Write a warm message to congratulate [name] on starting a new job as [role] at [company]. Wish them success, good colleagues, and happy learning in the new role, and say we are proud of them. Keep it under 60 words." },
  { id: "writing-188", title: "Farewell card for a teacher", category: "writing", text: "Write a warm farewell card message for our teacher [name] who is leaving our school after [years]. Mention one lesson we will remember, thank them for their patience, and wish them happiness in the next part of their life. Keep it under 80 words." },
  { id: "writing-189", title: "Farewell card for a colleague", category: "writing", text: "Write a warm farewell message for my colleague [name] who is leaving after [years] with us. Mention one good memory of working together, thank them for their help, and wish them success and happiness in their next job. Keep it under 80 words." },
  { id: "writing-190", title: "Retirement wishes", category: "writing", text: "Write a warm retirement message for [name] who is retiring after [years] of work as [role]. Thank them for their service, wish them good health, rest, and happy time with family, and mention one quality everyone will miss. Keep it under 80 words." },
  { id: "writing-191", title: "Wedding wishes", category: "writing", text: "Write a warm wedding message for [couple names] getting married on [date]. Wish them a happy married life, good health, and love that grows every year, and mention one blessing for their new family. Keep it under 60 words." },
  { id: "writing-192", title: "Engagement wishes", category: "writing", text: "Write a warm engagement message for [couple names] who just got engaged. Congratulate both families, wish the couple happiness and a smooth journey to the wedding, and end with a joyful line. Keep it under 60 words and suitable for WhatsApp." },
  { id: "writing-193", title: "Festival greeting for Diwali", category: "writing", text: "Write a warm Diwali greeting for [family or friends] that I can send on WhatsApp. Wish them light, health, happiness, and prosperity, mention sweets and family time, and end with a simple blessing. Keep it under 60 words and original." },
  { id: "writing-194", title: "Pongal greeting card for a neighbour", category: "writing", text: "Write a short Pongal greeting to write inside a card for my neighbour [name], to send with a small gift of jaggery and sugarcane. Wish their family a good harvest and a sweet year ahead, thank them for being kind neighbours, and keep it warm and simple in under 60 words." },
  { id: "writing-195", title: "Eid greeting for my housing society", category: "writing", text: "Write a warm Eid greeting for our housing-society WhatsApp group in India. Wish all the families peace, health and happiness, invite everyone to share sheer khurma at [place and time], and end with a simple blessing. Keep it friendly, short and under 80 words." },
  { id: "writing-196", title: "Christmas card message for a best friend", category: "writing", text: "Write a short Christmas message to put inside a handmade card for my best friend [name]. Mention one happy memory from this year, wish them joy, good health and a bright new year, and add one line about meeting soon. Keep it warm, simple and under 60 words." },
  { id: "writing-197", title: "New Year wishes", category: "writing", text: "Write a warm New Year message for [family or friends] for the year [year]. Wish them good health, happiness, and success, mention one hope for the year ahead, and end with a cheerful line. Keep it under 60 words and suitable for a card." },
  { id: "writing-198", title: "Raksha Bandhan message", category: "writing", text: "Write a warm Raksha Bandhan message for my [brother or sister]. Mention one childhood memory, say what their love means to me, and wish them health and happiness. Keep it heartfelt, simple, and under 60 words, suitable for a card or WhatsApp." },
  { id: "writing-199", title: "Teachers Day message", category: "writing", text: "Write a warm Teachers Day message for my teacher [name]. Thank them for their guidance in [subject], mention one lesson that changed how I learn, and wish them health and happiness. Keep it under 60 words and suitable for a card." },
  { id: "writing-200", title: "Mothers Day message", category: "writing", text: "Write a warm Mothers Day message for my mother. Thank her for her love, patience, and daily care, mention one small thing she does that I will always remember, and wish her health and happiness. Keep it under 60 words." },
  { id: "writing-201", title: "Fathers Day message", category: "writing", text: "Write a warm Fathers Day message for my father. Thank him for his hard work, guidance, and quiet support, mention one lesson he taught me, and wish him health and happiness. Keep it under 60 words and suitable for a card." },
  { id: "writing-202", title: "Childrens Day message", category: "writing", text: "Write a cheerful Childrens Day message for the children of our [school or family]. Wish them joy, learning, and good health, mention one fun activity for the day, and end with a line that makes every child feel special. Keep it under 60 words." },
  { id: "writing-203", title: "Independence Day message for school", category: "writing", text: "Write a short Independence Day message for our school assembly on 15 August. Mention the freedom fighters, one duty we have as citizens, and a wish for our country, in simple words that a student can read aloud. Keep it under 100 words." },
  { id: "writing-204", title: "Republic Day message", category: "writing", text: "Write a short Republic Day message for our school assembly on 26 January. Mention our Constitution, one value we should follow, and a wish for our country, in simple words that a student can read aloud. Keep it under 100 words." },
  { id: "writing-205", title: "Community notice about water", category: "writing", text: "Write a clear notice for our housing society about water supply timings changing to [timings] from [date]. Explain why the change is needed, what residents should do, and whom to contact with questions. Keep it polite and under 80 words." },
  { id: "writing-206", title: "Notice about power cut", category: "writing", text: "Write a clear notice for our housing society about a planned power cut on [date] from [time] to [time] for [reason]. Tell residents what to do before the cut, mention the lift and water pump, and give a contact number. Keep it under 80 words." },
  { id: "writing-207", title: "Notice about a meeting", category: "writing", text: "Write a clear notice for our housing society inviting all residents to a meeting on [date] at [time] in [place] to discuss [topic]. Mention the agenda in 3 short points and ask residents to attend on time. Keep it under 80 words." },
  { id: "writing-208", title: "Notice about a lost item", category: "writing", text: "Write a clear notice for our housing society about a lost [item] near [place] on [date]. Describe the item, say when and where it was lost, and ask anyone who finds it to contact [name and phone number]. Keep it under 60 words." },
  { id: "writing-209", title: "Notice about a found item", category: "writing", text: "Write a clear notice for our housing society about a found [item] near [place] on [date]. Describe the item in general terms, say where it is kept now, and ask the owner to contact [name] with proof. Keep it under 60 words." },
  { id: "writing-210", title: "Newspaper letter about bad roads", category: "writing", text: "Write a letter to the editor of a local newspaper about the bad condition of roads in [area]. Describe the potholes, the danger to school children and elders, and ask the municipality to repair them soon. Keep it polite, factual, and under 150 words." },
  { id: "writing-211", title: "Newspaper letter about garbage pile-up", category: "writing", text: "Write a letter to the editor of a local newspaper about garbage not being collected in [area]. Describe the smell, the mosquitoes, and the risk to health, and ask the municipality to clear it regularly. Keep it polite, factual, and under 150 words." },
  { id: "writing-212", title: "Newspaper letter about water shortage", category: "writing", text: "Write a letter to the editor of a local newspaper about irregular water supply in [area]. Describe how families struggle, especially in summer, and ask the authorities to fix the timings and supply. Keep it polite, factual, and under 150 words." },
  { id: "writing-213", title: "Newspaper letter about park maintenance", category: "writing", text: "Write a letter to the editor of a local newspaper about the poor condition of the park in [area]. Describe the broken swings, the dry grass, and the litter, and ask the municipality to repair and maintain it. Keep it polite and under 150 words." },
  { id: "writing-214", title: "Petition wording", category: "writing", text: "Write a short petition for residents of [area] asking the local authorities to [request, e.g. repair the street lights]. State the problem in 3 lines, the request in one line, and a closing line for signatures with name and address. Keep it clear and under 120 words." },
  { id: "writing-215", title: "Wedding anniversary message for parents", category: "writing", text: "Write a warm wedding anniversary message for my parents on their [number] anniversary. Thank them for their love and the home they built, mention one happy family memory, and wish them many more healthy years together. Keep it under 60 words." },
  { id: "writing-216", title: "Birthday wishes for a sister", category: "writing", text: "Write a warm birthday message for my sister [name]. Mention one childhood memory we share, one quality I admire in her, and a wish for her health, happiness, and success. Keep it heartfelt, simple, and under 60 words, suitable for WhatsApp." },
  { id: "writing-217", title: "Funny birthday message for my brother", category: "writing", text: "Write a funny birthday message for my brother [name] to send on WhatsApp. Tease him gently about one silly childhood fight, say one thing I secretly admire about him, and end with a warm wish and a promise of his favourite food. Keep it light and under 80 words." },
  { id: "writing-218", title: "Birthday wishes for a grandmother", category: "writing", text: "Write a warm birthday message for my grandmother. Thank her for her love, stories, and tasty food, mention one memory I will always cherish, and wish her good health and a long, happy life. Keep it under 60 words." },
  { id: "writing-219", title: "Birthday message for grandfather to read aloud", category: "writing", text: "Write a warm birthday message for my grandfather to read aloud at our family dinner. Thank him for his wisdom and stories, mention one memory I will always cherish and his favourite dish [dish name], and wish him good health and many happy years. Keep it under 100 words." },
  { id: "writing-220", title: "Get-well-soon note for a classmate", category: "writing", text: "Write a gentle get-well-soon note for my classmate [name] who is ill and missing school. Wish them rest and a quick recovery, say we miss them in class, and promise to share the notes. Keep it warm, simple, and under 60 words." },
  { id: "writing-221", title: "Farewell message for a school friend", category: "writing", text: "Write a warm farewell message for my school friend [name] who is moving to [place]. Mention one happy memory from school, wish them good luck in their new school, and promise to stay in touch. Keep it under 60 words." },
  { id: "writing-222", title: "Welcome message for a new neighbour", category: "writing", text: "Write a warm welcome message for a new neighbour who just moved into [flat or house number] in our area. Welcome them, offer one simple help such as showing them the shops, and invite them for tea. Keep it friendly and under 60 words." },
  { id: "writing-223", title: "Thank-you note for a wedding gift", category: "writing", text: "Write a warm thank-you note to [name] for the wedding gift of [gift]. Say how much we liked it, mention how we will use it in our new home, and thank them for coming to the wedding. Keep it under 60 words." },
  { id: "writing-224", title: "Invitation for a naming ceremony", category: "writing", text: "Write a warm invitation for the naming ceremony of our baby [name] on [date] at [place and time]. Invite family and friends, mention lunch after the ceremony, and add a line that makes guests feel welcome. Keep it under 80 words." },
  { id: "writing-225", title: "Newspaper letter about street lights", category: "writing", text: "Write a letter to the editor of a local newspaper about street lights not working in [area]. Describe the dark streets, the risk to women and elders at night, and ask the municipality to repair them soon. Keep it polite, factual, and under 150 words." },
  { id: "writing-226", title: "Rewrite my paragraph simply", category: "writing", text: "Rewrite this paragraph in much simpler English: [paste your paragraph]. Use short sentences, everyday words, and keep the same meaning, so a school student in India can understand it easily on the first reading." },
  { id: "writing-227", title: "Shorten my long email", category: "writing", text: "Shorten this long email to under 100 words: [paste your email]. Keep the main point, the key details and the polite tone, and cut repeated words and extra sentences that do not add new information." },
  { id: "writing-228", title: "Make my message more polite", category: "writing", text: "Rewrite this message to sound more polite and respectful: [paste your message]. Keep the same meaning and facts, add a gentle greeting and thank-you, and make sure it is suitable to send to a senior person." },
  { id: "writing-229", title: "Make my message more formal", category: "writing", text: "Rewrite this message in formal English suitable for an office or official letter: [paste your message]. Use proper greetings, clear sentences and polite words, and keep the same facts and request as the original message." },
  { id: "writing-230", title: "Make my message more friendly", category: "writing", text: "Rewrite this message to sound warm and friendly: [paste your message]. Keep the same facts and request, use simple everyday words, add a friendly greeting, and make it feel like a message between good friends." },
  { id: "writing-231", title: "Fix grammar in my paragraph", category: "writing", text: "Check this paragraph for grammar mistakes and correct them: [paste your paragraph]. Fix verb forms, articles and punctuation, keep my meaning and words as much as possible, and list the 3 biggest mistakes I made." },
  { id: "writing-232", title: "Improve my essay introduction", category: "writing", text: "Improve the introduction of my essay on [topic]: [paste your introduction]. Make the first line interesting, state the main idea clearly in one sentence, and keep it simple enough for a school student to understand." },
  { id: "writing-233", title: "Improve my essay conclusion", category: "writing", text: "Improve the conclusion of my essay on [topic]: [paste your conclusion]. Sum up the 3 main points in 3 short lines, end with a clear final thought, and keep the language simple and confident." },
  { id: "writing-234", title: "Add examples to my essay", category: "writing", text: "Add 3 good examples to my essay on [topic]: [paste your essay or main points]. Each example should be from everyday life in India, fit naturally into the essay, and make the main point easier to understand." },
  { id: "writing-235", title: "Turn bullet points into a paragraph", category: "writing", text: "Turn these bullet points into one smooth paragraph: [paste your bullet points]. Join the points with simple connecting words, keep the same facts in the same order, and make it read naturally in simple English." },
  { id: "writing-236", title: "Turn a paragraph into bullet points", category: "writing", text: "Turn this paragraph into clear bullet points: [paste your paragraph]. Break it into 5 to 7 short points, keep each point under 15 words, and make sure no important fact from the paragraph is left out." },
  { id: "writing-237", title: "School skit script", category: "writing", text: "Write a 5-minute script for a school skit about [topic, e.g. saving water / honesty]. Include 4 student characters, simple dialogues, one funny moment, and a clear moral at the end that the audience can remember." },
  { id: "writing-238", title: "Street-play script", category: "writing", text: "Write a 10-minute street play script about [a social issue, e.g. cleanliness / road safety] for 5 performers. Use loud, simple dialogues the crowd can hear, add one song or chant, and end with a clear message for the audience." },
  { id: "writing-239", title: "Puppet-show script for children", category: "writing", text: "Write a 10-minute puppet show script for children about [topic, e.g. a clever rabbit / the value of sharing]. Include 3 puppet characters, simple funny dialogues, one song, and a gentle moral at the end." },
  { id: "writing-240", title: "YouTube video script for beginners", category: "writing", text: "Write a 5-minute YouTube video script about [topic] for Indian beginners. Start with a hook in the first 10 seconds, cover 3 main points in order, and end with a simple call to action asking viewers to subscribe." },
  { id: "writing-241", title: "Podcast episode script", category: "writing", text: "Write a 15-minute podcast episode script about [topic]. Include a warm welcome, an introduction of the guest [guest name], 5 questions to ask them, and a closing summary with one takeaway for listeners." },
  { id: "writing-242", title: "Radio announcement script", category: "writing", text: "Write a 30-second radio announcement about [event or offer] happening on [date] at [place]. Say the key details clearly twice, keep the words simple enough to hear once, and end with the contact number." },
  { id: "writing-243", title: "Product demo video script", category: "writing", text: "Write a 2-minute script for a product demo video showing [product] for Indian customers. Show the 3 best features one by one, explain each in one simple line, and end by saying the price and where to buy it." },
  { id: "writing-244", title: "Interview script for a guest", category: "writing", text: "Write an interview script with 10 questions for a guest who is [a teacher / a shop owner / a sportsperson] talking about [topic]. Start with 2 easy warm-up questions, then go deeper, and end with one question about advice for beginners." },
  { id: "writing-245", title: "Survey questions for customers", category: "writing", text: "Write 10 short survey questions for customers of my [shop type] in India. Cover what they liked, what to improve, and whether they would recommend us, with simple yes-no and rating questions they can answer in 2 minutes." },
  { id: "writing-246", title: "Feedback form for an event", category: "writing", text: "Write a feedback form for a [school function / community event] held on [date]. Include 8 short questions about the event, the food, the timing and the organisation, plus one open box for suggestions, in simple words." },
  { id: "writing-247", title: "Registration form introduction", category: "writing", text: "Write a short introduction for a registration form for [a workshop / a class / an event] on [date]. Say who can join, what they will get, the last date to register, and that filling the form takes only 2 minutes." },
  { id: "writing-248", title: "Job application form note", category: "writing", text: "Write a short note to put at the top of a job application form for [role] at my business. Say what documents to attach, the last date to apply, and who to contact with questions, in clear and friendly words." },
  { id: "writing-249", title: "Simple rental agreement note", category: "writing", text: "Write a simple rental agreement note for a house in [area] rented at ₹[amount] per month. Include the tenant and owner names, the deposit, the monthly rent date, and that either side gives one month's notice to end it." },
  { id: "writing-250", title: "Simple receipt wording", category: "writing", text: "Write simple receipt wording for my shop [shop name] for a payment of ₹[amount] received from [customer name] for [product or service]. Include the date, the amount in words, and a thank-you line at the end." },
  { id: "writing-251", title: "Simple bill note for a shop", category: "writing", text: "Write a simple bill note for my shop [shop name] for [product or service] sold to [customer name]. List the item, quantity, rate, total amount, and payment mode, in a neat format that is easy to read and file." },
  { id: "writing-252", title: "Simple quotation for a service", category: "writing", text: "Write a simple quotation for my service [service name] for a customer in [area]. List each item of work, its price, the total amount, how long the offer is valid, and that taxes apply as per government rules." },
  { id: "writing-253", title: "Memo to staff about a change", category: "writing", text: "Write a short office memo to my staff about [a change, e.g. new timings / a new rule]. Say what is changing, from which date, why it is needed, and who to contact with questions, in clear and polite words." },
  { id: "writing-254", title: "Circular to parents from school", category: "writing", text: "Write a school circular to parents about [topic, e.g. a parent-teacher meeting / a holiday] on [date]. Give the date, time and place clearly, say what parents should bring or do, and end with the principal's name." },
  { id: "writing-255", title: "Circular to students from school", category: "writing", text: "Write a school circular to students about [topic, e.g. exam timings / a sports day] on [date]. Say what students must bring, what time to reach, and one important rule to follow, in simple words they can understand." },
  { id: "writing-256", title: "Press note for a local event", category: "writing", text: "Write a short press note for a local event [event name] happening on [date] at [place] in [town]. Say what the event is, who is organising it, why it matters to the area, and give one contact person for details." },
  { id: "writing-257", title: "Obituary notice for a newspaper", category: "writing", text: "Write a respectful obituary notice for [name], aged [age], from [area], who passed away on [date]. Include the family names, the funeral or prayer meeting details, and one gentle line about the person, in simple and dignified words." },
  { id: "writing-258", title: "Missing person notice", category: "writing", text: "Write a clear missing-person notice for [name], aged [age], last seen on [date] at [place]. Describe their height, clothes and one clear identifying mark, and give the contact number for anyone with information." },
  { id: "writing-259", title: "Found pet notice", category: "writing", text: "Write a friendly found-pet notice for a [dog / cat] found on [date] near [place]. Describe the pet's colour, size and one special mark, say where it is being kept safely, and give the contact number for the owner." },
  { id: "writing-260", title: "Lost document notice", category: "writing", text: "Write a short lost-document notice for a [passport / certificate / wallet] lost on [date] near [place]. Say what was lost, one identifying detail, the reward if any, and the contact number for anyone who finds it." },
  { id: "writing-261", title: "Public apology notice", category: "writing", text: "Write a short public apology notice for my [shop / organisation] about [what went wrong]. Say sorry clearly, explain what happened in one line, say what we are doing to fix it, and thank customers for their patience." },
  { id: "writing-262", title: "Disclaimer for a shop", category: "writing", text: "Write a simple disclaimer for my shop [shop name] selling [products]. Say clearly what the shop is and is not responsible for, in plain words a customer can understand, and keep it under 80 words on one notice board." },
  { id: "writing-263", title: "Simple loan note between friends", category: "writing", text: "Write a simple loan note between two friends for ₹[amount] borrowed on [date]. Include both names, the amount, the date it will be repaid, and a line saying there is no interest, in clear and friendly words." },
  { id: "writing-264", title: "Found-pet notice for my street", category: "writing", text: "Write a short notice about a pet [dog / cat] found near [place] on [date]. Describe the pet simply, say where it is safe now, and ask the owner to call [phone number] with proof. Keep it warm, clear and under 80 words." },
  { id: "writing-265", title: "Farewell note for a colleague", category: "writing", text: "Write a warm farewell note for a colleague [name] leaving our office after [years] of working together. Mention one good memory, thank them for their help, and wish them well in their next job in under 100 words." },
  { id: "writing-266", title: "Complaint letter to the municipality", category: "writing", text: "Write a polite complaint letter to the municipality about [a problem, e.g. garbage not collected / a broken road] in [area]. State the problem clearly, say how long it has continued, and ask for action within a reasonable time." },
  { id: "writing-267", title: "Request letter for a bank statement", category: "writing", text: "Write a polite request letter to my bank for a statement of my [savings / current] account for [months]. Include my account number, the period I need, and ask them to send it to my registered address or email." },
  { id: "writing-268", title: "Leave note for office work", category: "writing", text: "Write a short leave note to my office manager for [number] days from [date] because [reason]. Say who will handle my urgent work while I am away, and that I will be reachable on my phone." },
  { id: "writing-269", title: "Simple partnership note", category: "writing", text: "Write a simple partnership note for two people starting a small business together in [town]. Include both names, what each person will do, how profits will be shared, and that big decisions need both partners to agree." },
  { id: "writing-270", title: "Letter to the editor about stray dogs", category: "writing", text: "Write a letter to the editor of a local newspaper about stray dogs in [area]. Explain the problem in 3 short points, suggest one practical step like a vaccination drive by the municipality, and sign it with my name and area." },
  { id: "writing-271", title: "Request letter for a transfer certificate", category: "writing", text: "Write a request letter to my school principal for a transfer certificate for [student name] of Class [class]. Say why we need it, the date we need it by, and thank the school for its support." },
  { id: "writing-272", title: "Application for a duplicate certificate", category: "writing", text: "Write an application to my school for a duplicate [marksheet / certificate] that I lost. Say my name, class, year of passing, and roll number, and ask what fee I must pay for it." },
  { id: "writing-273", title: "Lost-document notice for the newspaper", category: "writing", text: "Write a short newspaper notice about a lost document: [document, e.g. a mark sheet / a passbook], lost near [place] on [date]. Ask the finder to contact [phone number], offer a small reward if found, and keep it under 80 words in simple English." },
  { id: "writing-274", title: "Report on a school trip", category: "writing", text: "Write a short report on our school trip to [place] on [date]. Say where we went, what we saw and learned, one funny moment, and what made the trip special, in simple English for the school notice board." },
  { id: "writing-275", title: "Diary entry about my first day at work", category: "writing", text: "Write a diary entry about my first day at a new job as [role] in [city]. Describe how I felt in the morning, 3 things that happened during the day, and one hope for tomorrow, in simple and honest words." },
  { id: "writing-276", title: "Email requesting a shift change at work", category: "writing", text: "Write a polite email to my manager asking to change my shift from [current shift] to [new shift] from [date] because [reason, e.g. evening classes]. Explain how I will finish my work, and ask for a reply." },
  { id: "writing-277", title: "Email requesting transfer to another office branch", category: "writing", text: "Write a formal email to HR asking for a transfer from [current branch] to [new branch] because [reason, e.g. family moved]. Mention my role, my years of service, and ask about the process and timeline." },
  { id: "writing-278", title: "Resignation email to my manager", category: "writing", text: "Write a short, respectful resignation email to my manager for the role of [role]. Give my last working day as [date], thank the team for the learning, and offer to hand over my work properly." },
  { id: "writing-279", title: "Job offer acceptance email", category: "writing", text: "Write a warm acceptance email for the job offer of [role] at [company]. Confirm my joining date as [date], thank the hiring team, and ask what documents I should bring on my first day." },
  { id: "writing-280", title: "Job offer decline email politely", category: "writing", text: "Write a polite email declining a job offer for [role] at [company]. Thank the interviewer for their time, give a short honest reason like [reason], and wish the team well without closing the door." },
  { id: "writing-281", title: "Email negotiating my salary before joining", category: "writing", text: "Write a polite email to HR asking for a higher salary for the role of [role] at [company]. Mention my experience in [field], the offered amount [amount], and the amount I hope for, [amount], with a calm, respectful tone." },
  { id: "writing-282", title: "Email asking to extend my joining date", category: "writing", text: "Write a polite email to HR asking to move my joining date for [role] at [company] from [old date] to [new date] because [reason]. Apologise for the change and confirm that I am keen to join." },
  { id: "writing-283", title: "Email requesting a promotion discussion meeting", category: "writing", text: "Write a confident but polite email to my manager asking for a meeting to discuss my promotion. Mention my role [role], my work on [project], and ask for a 30-minute slot next week." },
  { id: "writing-284", title: "Email requesting approval for a training course", category: "writing", text: "Write an email to my manager asking for approval to join a [course name] training costing [amount] on [dates]. Explain how it will help my work on [project], and ask who should approve the fee." },
  { id: "writing-285", title: "Email requesting a new laptop for work", category: "writing", text: "Write a polite email to my manager and IT team asking for a replacement laptop because my current one [problem, e.g. shuts down often]. Mention my work on [project] and how the delay affects it." },
  { id: "writing-286", title: "Email requesting a work-from-home extension", category: "writing", text: "Write a polite email to my manager asking to extend my work-from-home arrangement by [number] more weeks until [date] because [reason]. Promise daily updates and say I will come to office when needed." },
  { id: "writing-287", title: "Email to HR about my PF transfer", category: "writing", text: "Write a formal email to HR asking for help with transferring my PF from my old employer [company] to my new PF account. Give my UAN [number], my joining date, and ask what form I must fill." },
  { id: "writing-288", title: "Email to HR asking for my Form 16", category: "writing", text: "Write a short formal email to HR asking for my Form 16 for the financial year [year]. Mention my employee ID [number] and my department, and ask when I can collect it or receive it by email." },
  { id: "writing-289", title: "Email to HR about a tax declaration correction", category: "writing", text: "Write a polite email to HR asking to correct my tax declaration for this year. I wrongly declared [old detail] and the correct detail is [new detail]. Ask if I can update it before the next salary." },
  { id: "writing-290", title: "Email requesting a salary advance for a family emergency", category: "writing", text: "Write a respectful email to my manager and HR asking for a salary advance of [amount] because of a family emergency, [reason]. Explain how I will repay it over [number] months and ask for kind consideration." },
  { id: "writing-291", title: "Email requesting leave encashment", category: "writing", text: "Write a formal email to HR asking to encash [number] days of my unused leave as per company policy. Mention my employee ID [number], my department, and ask when the amount will be credited." },
  { id: "writing-292", title: "Email requesting a relieving letter after resigning", category: "writing", text: "Write a polite email to HR asking for my relieving letter after my last working day on [date]. Mention my role [role], my employee ID [number], and ask when I can collect it." },
  { id: "writing-293", title: "Email to HR about a lost ID card replacement", category: "writing", text: "Write a short email to HR saying I have lost my office ID card on [date] at [place]. Ask for a replacement card, mention my employee ID [number], and ask about the fee and the time it will take." },
  { id: "writing-294", title: "Email requesting flexible hours for evening classes", category: "writing", text: "Write a polite email to my manager asking for flexible working hours so I can attend evening classes in [subject] from [time] to [time]. Explain how I will complete my daily work and attend all meetings." },
  { id: "writing-295", title: "Email requesting permission to attend a conference", category: "writing", text: "Write an email to my manager asking for permission to attend the [conference name] in [city] on [dates]. Explain what I will learn, the cost [amount], and how my work will be covered while I am away." },
  { id: "writing-296", title: "Email informing manager about a late arrival due to train delay", category: "writing", text: "Write a short email to my manager saying I will reach office late today because my train from [station] is delayed by [time]. Mention my expected arrival time and say I will start work from the train." },
  { id: "writing-297", title: "Email informing office about a power cut at home during work-from-home", category: "writing", text: "Write a short email to my manager saying there is a power cut at my home in [area] today, so my internet may go off. Say I will stay reachable on my phone and finish urgent work once power returns." },
  { id: "writing-298", title: "Email to manager about a project delay with a new date", category: "writing", text: "Write an honest email to my manager saying the [project] will be delayed because [reason]. Give the new completion date as [date], explain what I have finished so far, and list the next steps." },
  { id: "writing-299", title: "Email to a client apologising for a missed deadline", category: "writing", text: "Write a polite email to my client [name] apologising for missing the deadline for [work] on [date]. Explain the reason briefly, give the new delivery date, and offer a small discount or extra support." },
  { id: "writing-300", title: "Email to a client confirming a meeting time", category: "writing", text: "Write a short professional email to my client [name] confirming our meeting on [date] at [time] at [place or video link]. Mention the agenda, [topic], and ask them to confirm or suggest another time." },
  { id: "writing-301", title: "Sick leave email to care for my mother", category: "writing", text: "Write a polite sick leave email to my manager saying I need [number] days off from [date] to care for my mother, who is unwell with [illness]. Say my colleague [name] will handle urgent work." },
  { id: "writing-302", title: "Leave email for my sister's wedding", category: "writing", text: "Write a warm leave email to my manager asking for [number] days off from [date] to [date] for my sister's wedding in [city]. Mention that I have finished my pending work and named [colleague] as my backup." },
  { id: "writing-303", title: "Leave email for a religious pilgrimage to Tirupati", category: "writing", text: "Write a respectful leave email to my manager asking for [number] days off from [date] for a family pilgrimage to Tirupati. Mention my darshan booking date and that I will return to work on [date]." },
  { id: "writing-304", title: "Leave email for shifting to a new house", category: "writing", text: "Write a polite leave email to my manager asking for [number] days off from [date] because I am shifting to a new house in [area]. Say I will be reachable on phone and will resume work on [date]." },
  { id: "writing-305", title: "Half-day leave email for a dentist appointment", category: "writing", text: "Write a short email to my manager asking for half-day leave on [date] from [time] for a dentist appointment at [clinic]. Say I will finish my morning work first and return after the appointment if possible." },
  { id: "writing-306", title: "Leave email for a visa interview at the consulate", category: "writing", text: "Write a formal leave email to my manager asking for one day off on [date] for a visa interview at the [country] consulate in [city]. Mention my appointment time and that I will share the outcome after." },
  { id: "writing-307", title: "Leave email for my final university exams", category: "writing", text: "Write a polite leave email to my manager asking for [number] days off from [date] to [date] for my final university exams in [subject]. Attach my exam timetable in the email and mention my backup colleague." },
  { id: "writing-308", title: "Permission email to leave office early for my child's school function", category: "writing", text: "Write a short email to my manager asking for permission to leave office early at [time] on [date] for my child's school annual day function. Say I will finish my urgent tasks before leaving." },
  { id: "writing-309", title: "Permission letter to principal for my child to leave school early", category: "writing", text: "Write a formal permission letter to the school principal asking that my child [name], class [class], be allowed to leave early at [time] on [date] because [reason]. Say I will collect my child personally." },
  { id: "writing-310", title: "Leave application for my child due to chickenpox", category: "writing", text: "Write a leave application to my child's class teacher saying my child [name], class [class], has chickenpox and needs rest for [number] days from [date]. Say I will send a medical certificate when my child returns." },
  { id: "writing-311", title: "Leave email for a blood donation camp at my office", category: "writing", text: "Write a short email to my manager asking for half-day leave on [date] to donate blood at a camp organised by [organisation] in our office. Say I will return to my desk after the donation and rest." },
  { id: "writing-312", title: "Permission email to use the office cab for a late shift", category: "writing", text: "Write a polite email to the admin team asking for the office cab on [date] because my shift ends late at [time]. Give my pickup point [place], my drop point [place], and my phone number." },
  { id: "writing-313", title: "Leave email for a family function in my native village", category: "writing", text: "Write a warm leave email to my manager asking for [number] days off from [date] for a family function in my native village [village name]. Say I will be back on [date] and my work is handed over." },
  { id: "writing-314", title: "Maternity leave request email to HR", category: "writing", text: "Write a respectful email to HR requesting maternity leave from [start date] to [end date] as per company policy. Mention my expected delivery date, my employee ID [number], and ask what documents I must submit." },
  { id: "writing-315", title: "Paternity leave request email to HR", category: "writing", text: "Write a polite email to HR requesting paternity leave for [number] days from [date] after the birth of my child. Mention my employee ID [number] and ask about the documents needed to apply." },
  { id: "writing-316", title: "Leave email after a minor surgery with a medical certificate", category: "writing", text: "Write a polite leave email to my manager saying I had a minor surgery on [date] and my doctor has advised rest for [number] days. Say I have attached the medical certificate and will update my manager." },
  { id: "writing-317", title: "Permission letter for my child to attend a sports tournament", category: "writing", text: "Write a formal permission letter to the school principal allowing my child [name], class [class], to attend a sports tournament in [city] on [dates]. Say I take responsibility for travel and give my phone number." },
  { id: "writing-318", title: "Leave note for a family bereavement", category: "writing", text: "Write a short, respectful leave note to my manager saying there has been a bereavement in my family, so I need [number] days off from [date]. Say I will inform my manager when I return to work." },
  { id: "writing-319", title: "Email requesting a sabbatical for higher studies", category: "writing", text: "Write a formal email to my manager and HR asking for a sabbatical of [number] months from [date] to study [course] at [college]. Explain how the course will help my work and ask about the terms." },
  { id: "writing-320", title: "Email requesting unpaid leave for a month", category: "writing", text: "Write a polite email to my manager and HR asking for one month of unpaid leave from [date] to [date] because [reason]. Say I understand it is unpaid and ask what approval or form is needed." },
  { id: "writing-321", title: "Complaint email to bank about a failed ATM transaction", category: "writing", text: "Write a formal complaint email to my bank saying [amount] was debited from my account on [date] but the ATM at [place] gave no cash. Give my account number, the transaction reference, and ask for a refund." },
  { id: "writing-322", title: "Complaint email to bank about a wrong EMI deduction", category: "writing", text: "Write a firm but polite complaint email to my bank saying an EMI of [amount] was wrongly deducted on [date] for my loan [loan number]. Ask the bank to reverse it and send a corrected statement." },
  { id: "writing-323", title: "Complaint email about credit card fraud", category: "writing", text: "Write an urgent complaint email to my bank about a fraud transaction of [amount] on my credit card on [date] at [merchant]. Say I did not make it, ask the bank to block the card, and request an investigation." },
  { id: "writing-324", title: "Complaint email to post office about a lost speed post parcel", category: "writing", text: "Write a formal complaint letter to the post office saying my speed post parcel with tracking number [number], sent on [date] to [city], has not arrived. Ask them to trace it and update me." },
  { id: "writing-325", title: "Complaint letter to gas agency about a delayed cylinder delivery", category: "writing", text: "Write a polite complaint letter to my gas agency saying I booked a cylinder on [date] with booking number [number] and it still has not arrived after [number] days. Ask for delivery within two days." },
  { id: "writing-326", title: "Complaint letter to water board about dirty tap water", category: "writing", text: "Write a formal complaint letter to the water board saying the tap water in our street [street name] has been muddy and smelly for [number] days. Ask them to check the pipeline and restore clean water soon." },
  { id: "writing-327", title: "Complaint email to telecom company about no network in my area", category: "writing", text: "Write a complaint email to my telecom company saying there has been no mobile network in [area] for [number] days. Mention my number, the calls I am missing, and ask for a quick fix." },
  { id: "writing-328", title: "Complaint letter to builder about a delayed flat handover", category: "writing", text: "Write a firm complaint letter to the builder of [project name] saying my flat was promised by [date] but is still not ready. Ask for a new handover date in writing and compensation for the delay." },
  { id: "writing-329", title: "Complaint letter to school about bullying of my child", category: "writing", text: "Write a serious but calm complaint letter to the school principal saying my child [name], class [class], is being bullied by [details]. Ask the school to look into it and keep my child safe." },
  { id: "writing-330", title: "Complaint email to hospital about a wrong bill", category: "writing", text: "Write a polite complaint email to the hospital billing department saying my bill for [treatment] on [date] wrongly includes [item] costing [amount]. Ask them to correct the bill and send a revised one." },
  { id: "writing-331", title: "Complaint letter to railway about a dirty train coach", category: "writing", text: "Write a complaint letter to the railway helpdesk saying the coach of train [train number] on [date] from [station] was dirty, with overflowing toilets. Ask them to improve cleaning on this route." },
  { id: "writing-332", title: "Complaint letter to bus depot about a cancelled bus route", category: "writing", text: "Write a complaint letter to the bus depot manager saying the [route] bus at [time] is cancelled almost every day, so students and workers miss their timings. Ask for a regular bus on this route." },
  { id: "writing-333", title: "Complaint email about a refund not received after a return", category: "writing", text: "Write a firm complaint email to [shop or website] saying I returned [product] on [date] with return ID [number], but the refund of [amount] has not come after [number] days. Ask for the refund this week." },
  { id: "writing-334", title: "Complaint letter to a restaurant about stale food", category: "writing", text: "Write a polite complaint letter to the restaurant manager saying the [dish] I ordered on [date] at [branch] tasted stale and made my family unwell. Ask for a refund and better food checks." },
  { id: "writing-335", title: "Complaint letter to my society about late-night noise", category: "writing", text: "Write a polite complaint letter to my housing society secretary saying loud music from flat [number] goes on past midnight almost every weekend. Ask the society to remind the resident about quiet hours." },
  { id: "writing-336", title: "Complaint letter to landlord about a broken lift in the building", category: "writing", text: "Write a polite complaint letter to my landlord saying the lift in our building has been broken for [number] days, which is hard for elderly residents. Ask for urgent repair and a date for it." },
  { id: "writing-337", title: "Letter to police station about a lost mobile phone", category: "writing", text: "Write a formal letter to the police station reporting that I lost my mobile phone, [brand and model], on [date] at [place]. Give my IMEI number [number] and ask for a written acknowledgement." },
  { id: "writing-338", title: "Complaint email to electricity board about frequent voltage fluctuation", category: "writing", text: "Write a complaint email to the electricity board saying voltage in our area [area] keeps going up and down, damaging fans and fridges. Ask them to check the transformer and fix it soon." },
  { id: "writing-339", title: "Complaint email to a gym about a trainer who never turns up", category: "writing", text: "Write a polite complaint email to the gym manager saying my trainer [name] has missed [number] sessions this month without informing me. Ask for a regular trainer or a refund for the missed sessions." },
  { id: "writing-340", title: "Complaint letter to a courier company about a torn parcel", category: "writing", text: "Write a complaint letter to the courier company saying my parcel with tracking number [number] arrived torn on [date], and [item] inside was damaged. Ask for compensation and better packing next time." },
  { id: "writing-341", title: "Request letter to bank for a new cheque book", category: "writing", text: "Write a short request letter to my bank manager asking for a new cheque book of [number] leaves for my savings account [account number]. Mention my name, my address, and ask when I can collect it." },
  { id: "writing-342", title: "Request letter to bank for a demand draft", category: "writing", text: "Write a formal request letter to my bank asking for a demand draft of [amount] in favour of [name] for [purpose, e.g. college fees]. Give my account number and ask about the charges." },
  { id: "writing-343", title: "Request letter to bank for a loan closure certificate", category: "writing", text: "Write a formal request letter to my bank asking for a loan closure certificate for my [type] loan, account number [number], which I fully repaid on [date]. Ask when I can collect the certificate." },
  { id: "writing-344", title: "Request letter to bank for a locker facility", category: "writing", text: "Write a polite request letter to my bank manager asking for a locker in the [branch] branch. Mention my account number, my need to store [items], and ask about the locker size, rent, and waiting list." },
  { id: "writing-345", title: "Request letter to bank to add my spouse as a joint holder", category: "writing", text: "Write a formal request letter to my bank asking to add my spouse [name] as a joint holder of my savings account [account number]. Say we will both sign the form and attach identity proof." },
  { id: "writing-346", title: "Request letter to bank to reactivate my dormant account", category: "writing", text: "Write a formal request letter to my bank asking to reactivate my savings account [account number], which became dormant because I did not use it for [number] years. Ask what documents and visit are needed." },
  { id: "writing-347", title: "Request letter to bank for a duplicate passbook", category: "writing", text: "Write a short request letter to my bank asking for a duplicate passbook for my savings account [account number] because I lost the original. Mention my name and address and ask about the fee." },
  { id: "writing-348", title: "Request letter to post office for a recurring deposit maturity payment", category: "writing", text: "Write a formal request letter to the post office asking for the maturity payment of my recurring deposit, account number [number], which matured on [date]. Ask when the amount will be credited to my account." },
  { id: "writing-349", title: "Request letter to post office to change my address in my savings account", category: "writing", text: "Write a formal request letter to the post office asking to update the address in my post office savings account [account number] from [old address] to [new address]. Say I have attached address proof." },
  { id: "writing-350", title: "Request letter for a birth certificate correction", category: "writing", text: "Write a formal request letter to the municipal office asking to correct the spelling of my child's name on the birth certificate from [wrong spelling] to [correct spelling]. Mention the certificate number and attach proof." },
  { id: "writing-351", title: "Request letter for an income certificate", category: "writing", text: "Write a formal request letter to the tehsildar asking for an income certificate for my father [name], whose yearly income is [amount], for my child's scholarship application. Mention the documents I have attached." },
  { id: "writing-352", title: "Request letter for a caste certificate", category: "writing", text: "Write a formal request letter to the tehsildar asking for a caste certificate for [name] belonging to [community]. Mention the purpose, [purpose], and list the documents I have attached with the application." },
  { id: "writing-353", title: "Request letter for adding my newborn to the ration card", category: "writing", text: "Write a formal request letter to the ration office asking to add my newborn baby [name], born on [date], to our family ration card number [number]. Say I have attached the birth certificate and Aadhaar details." },
  { id: "writing-354", title: "Request letter for a voter ID correction", category: "writing", text: "Write a formal request letter to the election office asking to correct my name on my voter ID from [wrong name] to [correct name]. Give my voter ID number [number] and say I have attached proof." },
  { id: "writing-355", title: "Request letter for a duplicate driving licence", category: "writing", text: "Write a formal request letter to the RTO asking for a duplicate driving licence because I lost the original on [date]. Give my licence number [number] and ask what documents and fee are needed." },
  { id: "writing-356", title: "Request letter for a PAN card correction", category: "writing", text: "Write a formal request letter asking to correct my date of birth on my PAN card from [wrong date] to [correct date]. Give my PAN number [number] and say I have attached my birth certificate as proof." },
  { id: "writing-357", title: "Request letter to college for a migration certificate", category: "writing", text: "Write a formal request letter to my college principal asking for a migration certificate because I am joining [new college] for [course]. Mention my roll number, my course, and the year I passed." },
  { id: "writing-358", title: "Request letter to college for my transcripts", category: "writing", text: "Write a formal request letter to my college office asking for official transcripts of my [course] marks for [purpose, e.g. higher studies abroad]. Mention my roll number and ask about the fee and time needed." },
  { id: "writing-359", title: "Request letter to college for a provisional certificate", category: "writing", text: "Write a formal request letter to my college principal asking for a provisional certificate for my [course], which I completed in [year]. Mention my roll number and say I need it for a job application." },
  { id: "writing-360", title: "Request letter for a fee concession for my child", category: "writing", text: "Write a respectful request letter to the school principal asking for a fee concession for my child [name], class [class], because our family income is low this year. Mention my income and attach proof." },
  { id: "writing-361", title: "Request letter for hostel admission for my daughter", category: "writing", text: "Write a formal request letter to the college warden asking for hostel admission for my daughter [name], who joined [course] this year. Mention her roll number, her home town, and ask about the fees." },
  { id: "writing-362", title: "Request letter for a bus pass for my child", category: "writing", text: "Write a formal request letter to the transport office asking for a student bus pass for my child [name], class [class], travelling from [place] to [school]. Ask about the fee and the documents needed." },
  { id: "writing-363", title: "Request letter for a scholarship renewal", category: "writing", text: "Write a formal request letter asking to renew my scholarship for the next academic year. Mention my name, my course [course], my roll number, my last year marks, and that I have attached the required documents." },
  { id: "writing-364", title: "Request letter to the RTO for a vehicle ownership transfer", category: "writing", text: "Write a formal request letter to the RTO asking to transfer the ownership of my [vehicle, e.g. scooter] with registration number [number] to [buyer name]. Say I have attached the sale papers and insurance." },
  { id: "writing-365", title: "Request letter to the municipality for a trade licence renewal", category: "writing", text: "Write a formal request letter to the municipality asking to renew the trade licence for my shop [shop name] in [area] for the year [year]. Mention the licence number and ask about the renewal fee." },
  { id: "writing-366", title: "Thank-you email to a client after my first order", category: "writing", text: "Write a warm thank-you email to my client [name] after my first order from them for [product or service]. Thank them for trusting my small business and say I hope to work with them again." },
  { id: "writing-367", title: "Thank-you email to my mentor for career guidance", category: "writing", text: "Write a heartfelt thank-you email to my mentor [name] for guiding me on [topic, e.g. choosing a career]. Mention one piece of advice that helped me and say how I used it." },
  { id: "writing-368", title: "Thank-you letter to a bank manager for approving my loan", category: "writing", text: "Write a polite thank-you letter to the bank manager of [branch] for approving my [type] loan of [amount]. Thank the staff for their quick help and say I will repay on time." },
  { id: "writing-369", title: "Thank-you email to a colleague who covered my work", category: "writing", text: "Write a warm thank-you email to my colleague [name] who covered my work on [project] while I was on leave. Mention what they handled and offer to return the favour next time." },
  { id: "writing-370", title: "Thank-you email to HR after my first week at a new job", category: "writing", text: "Write a short thank-you email to HR after my first week in the role of [role] at [company]. Say the team was welcoming, mention what I learned, and ask if there is anything I should do next." },
  { id: "writing-371", title: "Thank-you letter to a professor for a recommendation", category: "writing", text: "Write a polite thank-you letter to my professor [name] for writing a recommendation letter for my [job or course] application. Say the application is submitted and I will share the result." },
  { id: "writing-372", title: "Thank-you letter to a blood donor at a camp", category: "writing", text: "Write a warm thank-you letter to a stranger who donated blood for my [relative] at [hospital] on [date]. Say the operation went well, thank them for their kindness, and wish them good health." },
  { id: "writing-373", title: "Apology email to my manager for missing a meeting", category: "writing", text: "Write a sincere apology email to my manager for missing the meeting on [date] about [topic] because [reason]. Say I have read the notes, ask what I missed, and promise it will not happen again." },
  { id: "writing-374", title: "Apology letter to my teacher for a late assignment", category: "writing", text: "Write a polite apology letter to my teacher saying my assignment on [topic] is late because [reason]. Say I have finished it now, attach it, and ask if I can still submit it." },
  { id: "writing-375", title: "Apology letter to my neighbour for loud music", category: "writing", text: "Write a short apology letter to my neighbour for the loud music from my flat on [date] during [occasion]. Say I did not realise it was disturbing them and promise to keep the volume low." },
  { id: "writing-376", title: "Apology email to my bank for a delayed EMI payment", category: "writing", text: "Write a polite apology email to my bank saying my EMI of [amount] for loan [number] was delayed this month because [reason]. Say I have now paid it and will keep future payments on time." },
  { id: "writing-377", title: "Apology email for sending the wrong attachment", category: "writing", text: "Write a short apology email saying I sent the wrong attachment in my last email about [topic]. Attach the correct file now, name it clearly, and ask the reader to ignore the earlier file." },
  { id: "writing-378", title: "Apology letter to a friend for a misunderstanding", category: "writing", text: "Write a warm apology letter to my friend [name] for a misunderstanding about [topic] last week. Say what I meant, admit my part in it, and ask if we can talk and sort it out." },
  { id: "writing-379", title: "Apology email to a customer for a wrong bill", category: "writing", text: "Write a polite apology email to my customer [name] saying their bill for [product or service] wrongly charged [amount] extra. Say I have corrected it, attach the new bill, and offer a small discount." },
  { id: "writing-380", title: "Invitation letter for my shop opening", category: "writing", text: "Write a warm invitation letter for the opening of my shop [shop name] in [area] on [date] at [time]. Mention what the shop sells, invite the reader with their family, and say light refreshments will be served." },
  { id: "writing-381", title: "Invitation letter for an office inauguration", category: "writing", text: "Write a formal invitation letter for the inauguration of our new office at [address] on [date] at [time]. Invite [guest name], mention the chief guest, and ask them to confirm their attendance." },
  { id: "writing-382", title: "Formal invitation letter for a wedding", category: "writing", text: "Write a formal wedding invitation letter from [family name] inviting [guest name] to the wedding of [bride] and [groom] on [date] at [venue]. Mention the time, the reception, and a warm welcome." },
  { id: "writing-383", title: "Invitation letter for a retirement party", category: "writing", text: "Write a warm invitation letter for the retirement party of [name], who worked at [company] for [number] years, on [date] at [venue]. Invite colleagues and family and mention a small farewell gift." },
  { id: "writing-384", title: "Invitation letter for a college alumni meet", category: "writing", text: "Write a friendly invitation letter to former students of [college], batch of [year], for an alumni meet on [date] at [venue]. Mention old teachers, memories, lunch, and how to confirm attendance." },
  { id: "writing-385", title: "Invitation letter for a baby shower", category: "writing", text: "Write a warm invitation letter for a baby shower for [mother name] on [date] at [time] at [place]. Invite close family and friends, mention games and lunch, and ask guests to confirm by [date]." },
  { id: "writing-386", title: "Invitation letter for a housewarming lunch", category: "writing", text: "Write a warm invitation letter for a housewarming lunch at our new home in [area] on [date] at [time]. Invite [guest name] with family, mention a short prayer, and ask them to bless our new home." },
  { id: "writing-387", title: "Invitation letter to a chief guest for a school annual day", category: "writing", text: "Write a formal invitation letter to [guest name] inviting them as chief guest for our school annual day on [date] at [time]. Mention the programme, the students, and ask them to address the gathering." },
  { id: "writing-388", title: "Invitation letter for a temple festival in our street", category: "writing", text: "Write a warm invitation letter to neighbours for the temple festival in our street on [date] from [time] to [time]. Mention the pooja, prasadam, cultural programme, and invite everyone with family." },
  { id: "writing-389", title: "Letter to my parents about my hostel life", category: "writing", text: "Write a warm letter to my parents telling them about my hostel life in [city]. Describe my room, my food, my friends, and my classes, and say I miss home but I am settling in well." },
  { id: "writing-390", title: "Letter to my friend about my new job in another city", category: "writing", text: "Write a friendly letter to my friend [name] telling them about my new job as [role] in [city]. Describe my office, my new home, the food, and invite them to visit me soon." },
  { id: "writing-391", title: "Letter to my brother asking for career advice", category: "writing", text: "Write a letter to my elder brother asking for career advice because I am confused between [option A] and [option B]. Explain what I like about each and ask what he would do in my place." },
  { id: "writing-392", title: "Letter to my cousin inviting her to a family reunion", category: "writing", text: "Write a warm letter to my cousin [name] inviting her family to a family reunion at [place] on [date]. Mention who is coming, the food, games for children, and ask her to confirm soon." },
  { id: "writing-393", title: "Letter to my grandparents about my exam results", category: "writing", text: "Write a happy letter to my grandparents telling them I scored [marks] in my [exam] and stood [rank] in my class. Thank them for their blessings and say I will visit them in the holidays." },
  { id: "writing-394", title: "Letter to a friend inviting him to visit my hometown", category: "writing", text: "Write a friendly letter to my friend [name] inviting him to visit my hometown [place] during [holiday]. Describe the places we will see, the food we will eat, and the best time to come." },
  { id: "writing-395", title: "Letter to my sister about a recipe she asked for", category: "writing", text: "Write a warm letter to my sister sharing the recipe for [dish] she asked for. List the ingredients, the steps in simple words, and add one tip that makes it taste better." },
  { id: "writing-396", title: "Letter to my father thanking him for paying my fees", category: "writing", text: "Write a heartfelt letter to my father thanking him for paying my college fees of [amount] this year. Say I know it was not easy, promise to study hard, and say I will make him proud." },
  { id: "writing-397", title: "Letter to my childhood friend after ten years", category: "writing", text: "Write a warm letter to my childhood friend [name] after ten years without contact. Recall our school days, our favourite game, and ask what they are doing now and if we can meet." },
  { id: "writing-398", title: "Letter to my mother about my first month at a new job", category: "writing", text: "Write a warm letter to my mother telling her about my first month at my new job as [role] in [city]. Describe my manager, my colleagues, my daily routine, and say I am eating well." },
  { id: "writing-399", title: "Letter to a friend congratulating him on a promotion", category: "writing", text: "Write a happy letter to my friend [name] congratulating him on his promotion to [new role] at [company]. Say I always knew he would do well and suggest we celebrate with dinner soon." },
  { id: "writing-400", title: "Letter to my friend about learning to cook", category: "writing", text: "Write a funny, friendly letter to my friend [name] about my attempts to learn cooking in my new flat. Describe one dish that went wrong, one that turned out well, and ask for a simple recipe." },
  { id: "writing-401", title: "Letter to my teacher ten years after school", category: "writing", text: "Write a warm letter to my old teacher [name] ten years after school, telling them I am now working as [role]. Thank them for teaching me [subject] and say their lessons still help me." },
  { id: "writing-402", title: "Email to a vendor requesting a revised quotation", category: "writing", text: "Write a polite email to my vendor [name] asking for a revised quotation for [items] because our budget is [amount]. Ask for their best price, the delivery time, and the validity of the quotation." },
  { id: "writing-403", title: "Email to a supplier about a delayed raw material delivery", category: "writing", text: "Write a polite email to my supplier [name] saying the raw material [material] ordered on [date] has not arrived yet. Ask for the new delivery date because our production for [product] is waiting." },
  { id: "writing-404", title: "Email to a client requesting payment for an overdue invoice", category: "writing", text: "Write a polite but firm email to my client [name] reminding them that invoice [number] for [amount], due on [date], is still unpaid. Ask them to pay this week and share the payment details." },
  { id: "writing-405", title: "Email to a client requesting a testimonial", category: "writing", text: "Write a polite email to my happy client [name] asking for a short testimonial about our work on [project]. Say I will use it on my website, suggest two simple questions, and thank them." },
  { id: "writing-406", title: "Email to a landlord requesting permission to paint the flat", category: "writing", text: "Write a polite email to my landlord asking for permission to repaint my flat in [colour] before [festival or occasion]. Say I will pay for the paint and restore the original colour if needed." },
  { id: "writing-407", title: "Email to a landlord requesting a rent reduction", category: "writing", text: "Write a polite email to my landlord asking for a small rent reduction from [old rent] to [new rent] because [reason, e.g. my salary was cut]. Mention that I have paid on time for [number] years." },
  { id: "writing-408", title: "Email to a housing society requesting a guest parking slot", category: "writing", text: "Write a polite email to my housing society secretary asking for a guest parking slot on [date] because my relatives are visiting from [city]. Give the car number and the expected arrival time." },
  { id: "writing-409", title: "Email to a housing society requesting permission for a small function in the hall", category: "writing", text: "Write a polite email to my housing society secretary asking for permission to use the community hall on [date] from [time] to [time] for [function]. Say I will clean up after and follow society rules." },
  { id: "writing-410", title: "Letter to the editor about a library closing early", category: "writing", text: "Write a letter to the newspaper editor saying our public library in [area] now closes at [time], so students preparing for exams cannot study there. Ask the authorities to keep it open till [time]." },
  { id: "writing-411", title: "Letter to the editor about a bus stop with no shelter", category: "writing", text: "Write a letter to the newspaper editor saying the bus stop at [place] has no shelter, so passengers wait in rain and hot sun. Ask the municipality to build a simple shelter with a seat." },
  { id: "writing-412", title: "Letter to the editor about rising vegetable prices", category: "writing", text: "Write a letter to the newspaper editor saying vegetable prices in [market] have doubled in a month, with tomatoes at [price] per kilo. Ask the government to check hoarding and help common families." },
  { id: "writing-413", title: "Email to my child's teacher about a change in pickup person", category: "writing", text: "Write a short email to my child's teacher saying my [relative, e.g. aunt] will pick up my child [name], class [class], today instead of me. Give her name, her phone number, and ask the teacher to confirm." },
  { id: "writing-414", title: "Email to my child's teacher about a forgotten lunch box", category: "writing", text: "Write a short email to my child's teacher saying my child [name], class [class], forgot their lunch box at home today. Ask if the teacher can share a little food or let my child eat in the canteen." },
  { id: "writing-415", title: "Email to a coaching centre requesting a refund for a cancelled batch", category: "writing", text: "Write a polite email to the coaching centre saying my batch for [course] starting on [date] was cancelled, so I want a refund of my fee [amount]. Give my receipt number and ask when it will be refunded." },
  { id: "writing-416", title: "Email to a hotel requesting an early check-in", category: "writing", text: "Write a polite email to the hotel in [city] asking for an early check-in at [time] on [date] because my flight lands early. Give my booking ID [number] and ask if there is any extra charge." },
  { id: "writing-417", title: "Email to a hotel requesting a late check-out", category: "writing", text: "Write a polite email to the hotel in [city] asking for a late check-out at [time] on [date] because my train leaves in the evening. Give my booking ID [number] and ask if there is any extra charge." },
  { id: "writing-418", title: "Email to an airline requesting a wheelchair for my elderly mother", category: "writing", text: "Write a polite email to the airline asking for wheelchair assistance for my elderly mother [name] on flight [number] on [date] from [city] to [city]. Give the booking reference and her age." },
  { id: "writing-419", title: "Email to a train helpdesk requesting a lower berth for my grandmother", category: "writing", text: "Write a polite email to the train helpdesk asking for a lower berth for my grandmother [name], aged [age], travelling on train [number] on [date]. Give the PNR [number] and ask if it can be arranged." },
  { id: "writing-420", title: "Letter to my friend about my plan to start a small business", category: "writing", text: "Write a friendly letter to my friend [name] telling them about my plan to start a small business selling [product] in [city]. Explain my idea, my budget, and ask for their honest opinion and advice." },
  { id: "writing-421", title: "Short story about a train that stops nowhere", category: "writing", text: "Write a short story of about 400 words about a train that stops at a station nobody can find on any map. Give [the main character] a clear reason to board it, add one surprising fellow passenger, and end with a gentle twist that explains why the train stops nowhere." },
  { id: "writing-422", title: "Story about a grandmother's secret recipe book", category: "writing", text: "Write a warm short story about [a grandchild] who finds a grandmother's old recipe book with one page missing. Show how the family cooks together to guess the missing dish, and end with the grandmother smiling because the real secret was never written down." },
  { id: "writing-423", title: "Children's story about a moonlit kite", category: "writing", text: "Write a simple children's story of about 300 words about a kite that flies only on moonlit nights. Give [the child] a kind friend who helps chase it across rooftops, use easy words and short sentences, and end with the kite landing safely in a friendly garden." },
  { id: "writing-424", title: "Moral story about sharing lunch at school", category: "writing", text: "Write a moral story for children about [a student] who has no lunch one day and a classmate who shares food without being asked. Show the small kindness clearly, keep the language simple, and end with one clear line about why sharing makes everyone happier." },
  { id: "writing-425", title: "Poem for a baby's first birthday", category: "writing", text: "Write a sweet poem of four short stanzas for [the baby's name] on a first birthday. Mention tiny feet, first words, family laughter and a birthday cake, keep the rhymes gentle and easy to read aloud, and end with a blessing for a happy year ahead." },
  { id: "writing-426", title: "Song lyrics for a monsoon wedding dance", category: "writing", text: "Write joyful song lyrics for a wedding dance in the monsoon, with a catchy chorus about rain, henna and happy families. Use simple words that [the dancers] can sing together, keep four verses short, and make the last line a cheerful blessing for the bride and groom." },
  { id: "writing-427", title: "Play script about a lost umbrella at a fair", category: "writing", text: "Write a short play script for four children about a lost umbrella at a village fair. Give each child a few funny lines, add a kind stall owner who helps search, and end with the umbrella found in the most surprising stall of all." },
  { id: "writing-428", title: "Dialogue between a gardener and a talking plant", category: "writing", text: "Write a funny dialogue between [a gardener] and a talking tulsi plant that complains about too much water and too little sunshine. Keep the lines short and lively, let the plant give one wise tip, and end with the gardener promising to listen better." },
  { id: "writing-429", title: "Story starter: a key found in a school bag", category: "writing", text: "Write five different story starters, each two sentences long, beginning with [a student] finding a strange old key inside a school bag. Make each starter point to a different adventure, from a locked classroom to a hidden garden, and keep them exciting for young writers." },
  { id: "writing-430", title: "Character sketch of a cheerful chai seller", category: "writing", text: "Write a character sketch of about 250 words about a cheerful chai seller at [a railway station]. Describe his smile, his quick hands, the steam from his kettle and how he remembers every regular customer, and show why travellers look forward to his stall." },
  { id: "writing-431", title: "Plot idea: a village library that lends memories", category: "writing", text: "Write a plot idea for a short story about a village library that lends memories instead of books. Explain how [the visitor] borrows one memory, what goes wrong when it is returned late, and suggest a warm ending where the village shares its best memory together." },
  { id: "writing-432", title: "Funny story about a goat at a wedding", category: "writing", text: "Write a funny short story about a hungry goat that wanders into a wedding feast in [a village]. Show the chaos it causes among the guests, the clever child who lures it away with a banana, and end with the goat becoming the unexpected guest of honour." },
  { id: "writing-433", title: "Folk tale about a clever potter and a king", category: "writing", text: "Write a folk tale in the old storytelling style about a clever potter who outwits a proud king with a simple clay pot. Use clear, simple language, add a short dialogue between the potter and the king, and end with a moral about wisdom being worth more than wealth." },
  { id: "writing-434", title: "Festival story about Holi colours that vanish", category: "writing", text: "Write a festival story about [a child] whose Holi colours vanish from the skin every time someone tells a lie. Show the fun at first, then the trouble it causes, and end with the child learning that truth keeps the colours bright all day." },
  { id: "writing-435", title: "Short story about a postman who delivers letters from the past", category: "writing", text: "Write a short story about an old postman who delivers letters written fifty years ago to people in [a small town]. Follow one letter to its reader, show the surprise and joy it brings, and end with the postman keeping one letter for himself." },
  { id: "writing-436", title: "Children's story about a sleepy owl who guards the night", category: "writing", text: "Write a gentle bedtime story about a sleepy owl who guards the night over [a village]. Show how he helps a lost firefly, a frightened kitten and a tired farmer, use soft and calm words, and end with the owl finally sleeping as the sun rises." },
  { id: "writing-437", title: "Moral story about telling the truth to a teacher", category: "writing", text: "Write a moral story for children about [a student] who breaks a classroom window by accident and feels afraid to tell the teacher. Show the worry, the honest confession and the teacher's kind response, and end with a clear line about truth making a heavy heart light." },
  { id: "writing-438", title: "Poem about a grandmother's garden", category: "writing", text: "Write a warm poem of four stanzas about a grandmother's garden full of marigolds, tulsi and mango trees. Mention morning watering, buzzing bees and the smell of rain on soil, use simple rhymes, and end with the garden as a place where love grows." },
  { id: "writing-439", title: "Lullaby for a sleepy baby", category: "writing", text: "Write a soft lullaby of four short verses for [a baby] who will not sleep. Mention the moon, a rocking cradle, a mother's hum and quiet stars, keep every line short and soothing, and end with the baby drifting off to sleep." },
  { id: "writing-440", title: "Script for a two-minute mime about a busy market", category: "writing", text: "Write a mime script for two performers showing a busy morning market without any words. Describe each action clearly, from bargaining for vegetables to chasing a runaway hen, and end with both performers bowing as the market closes for the day." },
  { id: "writing-441", title: "Dialogue between two rival cricket fans", category: "writing", text: "Write a friendly dialogue between two cricket fans who support rival teams during a match in [a town]. Let them tease each other about their favourite players, argue about one close decision, and end by sharing snacks and agreeing that a good match matters most." },
  { id: "writing-442", title: "Story starter: a bicycle that rings by itself", category: "writing", text: "Write five story starters, each two sentences long, about a bicycle that rings its bell by itself whenever [the rider] is near something hidden. Make each starter lead to a different mystery, keep the tone playful, and leave every ending open for the writer to finish." },
  { id: "writing-443", title: "Character sketch of a strict but kind librarian", category: "writing", text: "Write a character sketch of about 250 words about a strict but kind librarian in [a school]. Describe her quiet voice, her sharp eyes, the way she knows every book by heart, and the small kindness she shows to a shy student who loves stories." },
  { id: "writing-444", title: "Plot twist idea for a detective story", category: "writing", text: "Write five different plot twist ideas for a simple detective story set in [an Indian town]. Each twist should be two sentences long, turn the reader's guess upside down, and reveal that the least suspected person, place or object held the real clue all along." },
  { id: "writing-445", title: "Joke story about a parrot that mimics the principal", category: "writing", text: "Write a funny story about a parrot in [a school] that mimics the principal's voice perfectly. Show the confusion it causes in the corridors, the clever plan the students make to catch it, and end with the principal laughing and giving the parrot a new perch." },
  { id: "writing-446", title: "Folk tale about the river that changed its course", category: "writing", text: "Write a folk tale about a river that changes its course to help a dry village in [a region]. Tell it in the voice of a grandmother, add a kind fisherman and a grateful village, and end with a moral about nature rewarding those who care for it." },
  { id: "writing-447", title: "Festival story about a lantern that flies to the wrong house", category: "writing", text: "Write a festival story about a paper lantern that flies to the wrong house on a festival night in [a town]. Show the surprise of the family who finds it, the new friendship that follows, and end with both families celebrating together the next year." },
  { id: "writing-448", title: "Short story about a tailor who stitches wishes", category: "writing", text: "Write a short story about a tailor in [a small town] who stitches one secret wish into every garment he makes. Follow [a customer] who wears a stitched kurta to an important day, show the wish quietly coming true, and end with the tailor smiling at his needle." },
  { id: "writing-449", title: "Children's story about a fish who wants to fly", category: "writing", text: "Write a cheerful children's story about a little fish in [a river] who dreams of flying like the birds. Show how a kind kingfisher helps the fish leap high above the water, use simple words, and end with the fish happy to swim and dream both." },
  { id: "writing-450", title: "Moral story about helping a new classmate", category: "writing", text: "Write a moral story for children about [a student] who helps a new classmate who speaks a different language and feels shy. Show small acts of kindness, like sharing lunch and teaching a game, and end with the new child smiling and the class feeling like one family." },
  { id: "writing-451", title: "Poem about a train journey through the hills", category: "writing", text: "Write a poem of four stanzas about a slow train journey through green hills in [a region]. Mention misty valleys, small stations, tea sellers at windows and a tunnel that swallows the light, and end with the train arriving as the evening sun turns gold." },
  { id: "writing-452", title: "Song lyrics for a school farewell party", category: "writing", text: "Write warm song lyrics for a school farewell party, with a chorus about friends, teachers and memories that stay. Keep the verses short and easy to sing together, mention [the school name] once, and end with a hopeful line about meeting again someday." },
  { id: "writing-453", title: "Play script about a magic school bag", category: "writing", text: "Write a short play script for five children about a magic school bag that gives [the owner] exactly what is needed, never what is wanted. Give each child lively lines, add one funny mix-up, and end with the children learning that kindness is the best thing the bag gives." },
  { id: "writing-454", title: "Dialogue between the sun and the moon", category: "writing", text: "Write a gentle dialogue between the sun and the moon as they meet for a few minutes at sunset. Let the sun boast about bright days, let the moon answer with quiet nights and stars, and end with both agreeing that the sky needs them both." },
  { id: "writing-455", title: "Story starter: a door that appears only on Sundays", category: "writing", text: "Write five story starters, each two sentences long, about a small door that appears in [a street] only on Sundays. Make each starter open a different world behind the door, from a sweet shop to a floating garden, and keep the endings open for young writers." },
  { id: "writing-456", title: "Character sketch of a brave young postwoman", category: "writing", text: "Write a character sketch of about 250 words about a brave young postwoman who delivers letters across [a hilly village]. Describe her red bicycle, her raincoat, her cheerful greeting at every door, and how the whole village waits for her smile each morning." },
  { id: "writing-457", title: "Plot idea: a school that floats on a lake", category: "writing", text: "Write a plot idea for a children's story about a school that floats on a lake in [a place]. Explain how the children reach it by boat, what happens when a storm rocks the classroom, and suggest a brave and funny ending where the whole class rows together." },
  { id: "writing-458", title: "Funny poem about a messy room", category: "writing", text: "Write a funny poem of four stanzas about [a child's] messy room where socks hide under the bed and books build small hills. Use playful rhymes and silly images, keep the tone light, and end with the child promising to tidy up tomorrow, maybe." },
  { id: "writing-459", title: "Folk tale about a farmer and a talking peacock", category: "writing", text: "Write a folk tale about a poor farmer who saves a talking peacock in [a village]. Let the peacock repay him with three clever pieces of advice, show how the farmer uses each one wisely, and end with a moral about kindness returning when it is needed most." },
  { id: "writing-460", title: "Festival story about Pongal and a runaway sugarcane cart", category: "writing", text: "Write a festival story about a runaway sugarcane cart during Pongal in [a Tamil village]. Show the laughter as villagers chase it past kolams and pots of boiling pongal, and end with everyone sharing the sweet harvest together under the morning sun." },
  { id: "writing-461", title: "Short story about a photographer who captures dreams", category: "writing", text: "Write a short story about a photographer in [a city] whose camera captures people's dreams instead of their faces. Follow one photograph that shows a child's forgotten dream, and end with the photographer returning the dream to its owner on a quiet morning." },
  { id: "writing-462", title: "Children's story about a cloud that loses its rain", category: "writing", text: "Write a simple children's story about a small cloud that loses its rain over [a dry field]. Show how a bird, a farmer and a little girl help the cloud find its rain again, use easy words, and end with gentle rain falling on happy crops." },
  { id: "writing-463", title: "Moral story about returning a lost wallet", category: "writing", text: "Write a moral story for children about [a student] who finds a wallet full of money on the way to school. Show the temptation, the honest choice to return it, and the owner's grateful surprise, and end with a clear line about honesty bringing its own reward." },
  { id: "writing-464", title: "Poem about a kite festival morning", category: "writing", text: "Write a joyful poem of four stanzas about a kite festival morning in [a city]. Mention colourful kites, tangled strings, rooftop cheers and a sky full of paper birds, use bright and simple rhymes, and end with the last kite dancing alone at sunset." },
  { id: "writing-465", title: "Rhyming poem for a child's first day of school", category: "writing", text: "Write a gentle rhyming poem of four stanzas for [a child] on the first day of school. Mention a new bag, a kind teacher, a best friend waiting at the gate and a lunch box full of surprises, and end with the child running home full of happy stories." },
  { id: "writing-466", title: "Script for a puppet show about a greedy monkey", category: "writing", text: "Write a puppet-show script for children about a greedy monkey who grabs every banana in [a forest]. Give the monkey, a wise elephant and a laughing parrot short funny lines, and end with the monkey learning to share and the animals feasting together." },
  { id: "writing-467", title: "Dialogue between a shopkeeper and a forgetful customer", category: "writing", text: "Write a funny dialogue between a patient shopkeeper and a forgetful customer in [a market] who keeps forgetting why he came. Let the customer ask for five wrong things first, and end with both laughing when he finally remembers he only needed a packet of salt." },
  { id: "writing-468", title: "Story starter: a whisper heard in an old library", category: "writing", text: "Write five story starters, each two sentences long, about a whisper heard in an old library in [a town]. Make each starter hint at a different secret, from a hidden book to a ghost who loves stories, and keep the endings open for the writer to finish." },
  { id: "writing-469", title: "Character sketch of a funny auto driver", category: "writing", text: "Write a character sketch of about 250 words about a funny auto driver in [a city] who tells jokes at every red light. Describe his loud laugh, his decorated auto, his favourite songs, and how even tired passengers step out smiling after his ride." },
  { id: "writing-470", title: "Plot idea: a treasure map hidden in a textbook", category: "writing", text: "Write a plot idea for a children's adventure about a treasure map hidden inside an old textbook in [a school]. Explain who finds it, what three clues lead across the school, and suggest a funny ending where the treasure turns out to be something nobody expected." },
  { id: "writing-471", title: "Joke story about a cat that opens doors", category: "writing", text: "Write a funny story about a clever cat in [a house] that learns to open every door, including the fridge. Show the family's surprise, the chaos at dinner time, and end with the cat proudly sitting on the sofa like the real owner of the house." },
  { id: "writing-472", title: "Folk tale about a wise old banyan tree", category: "writing", text: "Write a folk tale about a wise old banyan tree that settles quarrels in [a village]. Tell how two neighbours bring their dispute to the tree, what the tree teaches them through a falling leaf and a nesting bird, and end with a moral about listening before judging." },
  { id: "writing-473", title: "Festival story about a Dandiya night mix-up", category: "writing", text: "Write a festival story about a Dandiya night in [a city] where two dancers swap partners by mistake. Show the laughter, the tangled steps and the music that will not stop, and end with both pairs dancing happily together till midnight." },
  { id: "writing-474", title: "Short story about a watchmaker who fixes broken time", category: "writing", text: "Write a short story about an old watchmaker in [a town] who can fix broken time, not just broken watches. Follow [a customer] who asks him to repair one lost hour, show what that hour holds, and end with the customer choosing to let it go." },
  { id: "writing-475", title: "Children's story about a tortoise who enters a race again", category: "writing", text: "Write a cheerful children's story about a tortoise who enters a race again after many years in [a village]. Show how the young animals laugh, how the tortoise keeps walking slowly and steadily, and end with everyone cheering when he crosses the line at sunset." },
  { id: "writing-476", title: "Moral story about waiting your turn in a queue", category: "writing", text: "Write a moral story for children about [a child] who jumps a long queue at a temple fair and then feels sorry. Show the grumble of the crowd, the child's apology and the kind old woman who lets him stand beside her, and end with a line about patience." },
  { id: "writing-477", title: "Poem about the first rain after summer", category: "writing", text: "Write a poem of four stanzas about the first rain after a long hot summer in [a town]. Mention dusty roads turning dark, the smell of wet earth, children splashing in puddles and peacocks calling, and end with the whole town breathing easy again." },
  { id: "writing-478", title: "Song lyrics for a village harvest celebration", category: "writing", text: "Write happy song lyrics for a village harvest celebration, with a chorus about golden fields, full baskets and dancing farmers. Keep the verses short and easy to sing in a group, mention [the crop] once, and end with thanks to the rain and the sun." },
  { id: "writing-479", title: "Play script about a classroom that comes alive at night", category: "writing", text: "Write a short play script for six children about a classroom that comes alive at night in [a school]. Let the chalk, the globe and the wall charts argue about who is most important, and end with them agreeing that the children make the classroom real." },
  { id: "writing-480", title: "Dialogue between a river and a mountain", category: "writing", text: "Write a thoughtful dialogue between a river and a mountain in [a region]. Let the river boast about travelling far, let the mountain answer that it has watched a thousand years, and end with both agreeing that flowing and standing both matter." },
  { id: "writing-481", title: "Story starter: a letter with no sender", category: "writing", text: "Write five story starters, each two sentences long, about a letter with no sender that arrives at [a house]. Make each starter point to a different mystery, from a lost friend to a future warning, and keep the endings open for the writer to finish." },
  { id: "writing-482", title: "Character sketch of a dreamy young artist", category: "writing", text: "Write a character sketch of about 250 words about a dreamy young artist in [a town] who paints on walls, notebooks and old doors. Describe her messy hair, her paint-stained hands, her habit of staring at clouds, and the mural that makes her whole street smile." },
  { id: "writing-483", title: "Plot idea: a mirror that shows tomorrow", category: "writing", text: "Write a plot idea for a short story about a mirror that shows tomorrow instead of today in [a house]. Explain how [the owner] uses it at first, what goes wrong when tomorrow looks frightening, and suggest an ending where the owner learns to live one day at a time." },
  { id: "writing-484", title: "Funny story about a school play gone wrong", category: "writing", text: "Write a funny story about a school play in [a school] where everything goes wrong, from a falling crown to a dog on stage. Show the panic backstage, the quick thinking of one student, and end with the audience clapping loudest for the funniest show ever." },
  { id: "writing-485", title: "Folk tale about a brave shepherd girl", category: "writing", text: "Write a folk tale about a brave shepherd girl who saves her flock from a storm in [the hills]. Tell how she leads the sheep through a dark pass with only her flute and her dog, and end with a moral about courage being quiet and steady." },
  { id: "writing-486", title: "Festival story about a Diwali gift mix-up", category: "writing", text: "Write a festival story about a Diwali gift mix-up in [a family] where every parcel reaches the wrong person. Show the laughter as gifts are opened, the surprise of each wrong gift fitting perfectly, and end with the family deciding the mix-up was the best gift of all." },
  { id: "writing-487", title: "Short story about a bus conductor with a secret", category: "writing", text: "Write a short story about a cheerful bus conductor in [a city] who hides a secret talent. Follow [a passenger] who discovers it on a crowded evening bus, show the conductor's shyness, and end with the whole bus clapping for a surprise performance at the last stop." },
  { id: "writing-488", title: "Children's story about a brave little ant", category: "writing", text: "Write a simple children's story about a brave little ant who carries food across a flooded path in [a garden]. Show how the ant asks a leaf, a beetle and a bird for help, use easy words, and end with the whole colony eating together in a dry nest." },
  { id: "writing-489", title: "Moral story about apologising to a friend", category: "writing", text: "Write a moral story for children about [a student] who says something unkind to a best friend and then feels sorry all day. Show the quiet regret, the brave apology at lunch, and the friend's warm forgiveness, and end with a line about sorry healing a hurt heart." },
  { id: "writing-490", title: "Poem about a winter morning in the hills", category: "writing", text: "Write a calm poem of four stanzas about a winter morning in the hills of [a place]. Mention mist over tea gardens, smoke from chimneys, warm shawls and a sun that rises slowly, and end with the hills waking up in soft golden light." },
  { id: "writing-491", title: "Acrostic poem using the word FRIENDSHIP", category: "writing", text: "Write an acrostic poem using the letters of the word FRIENDSHIP, one line for each letter. Make every line about a true friend, keep the language simple and warm, and end with the last line celebrating a friendship that lasts through good and bad days." },
  { id: "writing-492", title: "Street-play script about saving water", category: "writing", text: "Write a short street-play script for six performers about saving water in [a neighbourhood]. Give each performer a clear role, from a leaking tap to a wise grandmother, add a catchy slogan the crowd can repeat, and end with everyone promising to fix one leak at home." },
  { id: "writing-493", title: "Dialogue between a mother and a daughter about a lost kite", category: "writing", text: "Write a warm dialogue between a mother and a daughter about a lost kite in [a town]. Let the daughter feel sad, let the mother share a story of her own lost kite as a child, and end with both deciding to build a new kite together." },
  { id: "writing-494", title: "Story starter: a strange shop that sells lost things", category: "writing", text: "Write five story starters, each two sentences long, about a strange little shop in [a lane] that sells lost things. Make each starter follow a different lost object, from a toy to a memory, and keep the endings open for the writer to finish." },
  { id: "writing-495", title: "Character sketch of a kind village doctor", category: "writing", text: "Write a character sketch of about 250 words about a kind village doctor in [a village] who treats patients at all hours. Describe his old bicycle, his gentle questions, his free medicine for the poor, and why the whole village calls him their family doctor." },
  { id: "writing-496", title: "Plot idea: a school bell that rings backwards", category: "writing", text: "Write a plot idea for a children's story about a school bell that rings backwards in [a school]. Explain how the day runs in reverse, what funny trouble it causes in class, and suggest an ending where one clever student rings the bell the right way round." },
  { id: "writing-497", title: "Joke poem about a hungry elephant", category: "writing", text: "Write a funny poem of four stanzas about a hungry elephant who eats everything at a village feast in [a place]. Mention bananas, laddoos, a whole pot of rice and a surprised cook, use playful rhymes, and end with the elephant asking politely for just one more banana." },
  { id: "writing-498", title: "Folk tale about the moon and a little girl", category: "writing", text: "Write a gentle folk tale about the moon and a little girl in [a village] who cannot sleep. Tell how the moon sends her a silver ladder of light, what she sees from the sky, and end with a moral about dreams being close enough to touch." },
  { id: "writing-499", title: "Festival story about an Onam boat race surprise", category: "writing", text: "Write a festival story about an Onam boat race in [Kerala] where the slowest boat wins by surprise. Show the cheering crowds, the flower carpets on the banks, and the clever trick the rowers use at the last bend, and end with a grand sadya feast for all." },
  { id: "writing-500", title: "Short story about a musician who hears colours", category: "writing", text: "Write a short story about a young musician in [a city] who hears colours whenever she plays her flute. Follow her first concert, show how the audience sees the music in her eyes, and end with her playing a song that paints the whole hall gold." },
  { id: "writing-501", title: "Children's story about a penguin who visits India", category: "writing", text: "Write a playful children's story about a little penguin who visits India and feels very hot in [a town]. Show how children help him with ice, shade and a cool bath, use easy words, and end with the penguin waving goodbye and promising to write letters from the snow." },
  { id: "writing-502", title: "Moral story about not copying in an exam", category: "writing", text: "Write a moral story for children about [a student] who is tempted to copy answers in an exam. Show the worry, the honest choice to write only what is known, and the teacher's quiet praise, and end with a line about real marks coming from real learning." },
  { id: "writing-503", title: "Poem about a busy railway station", category: "writing", text: "Write a lively poem of four stanzas about a busy railway station in [a city]. Mention whistling trains, tea sellers, hurrying feet and tearful goodbyes, use quick and bright rhymes, and end with the station growing quiet under the night stars." },
  { id: "writing-504", title: "Song lyrics for a birthday party for grandmother", category: "writing", text: "Write cheerful song lyrics for a grandmother's birthday party, with a chorus about her stories, her cooking and her warm hugs. Keep the verses short so [the family] can sing together, mention her age with love, and end with a blessing for many more birthdays." },
  { id: "writing-505", title: "Play script about a robot who learns to laugh", category: "writing", text: "Write a short play script for four children about a robot in [a school] who learns to laugh. Give the robot stiff funny lines, let a kind student teach it jokes one by one, and end with the robot laughing so hard that its screws rattle." },
  { id: "writing-506", title: "Dialogue between two birds on a wire", category: "writing", text: "Write a light dialogue between two birds sitting on a wire above [a street]. Let one bird dream of flying far away while the other loves staying home, and end with both agreeing to fly together just once, to the next rooftop and back." },
  { id: "writing-507", title: "Story starter: a footprint that appears every morning", category: "writing", text: "Write five story starters, each two sentences long, about a single footprint that appears outside [a house] every morning. Make each starter suggest a different visitor, from a dancer to a giant, and keep the endings open for the writer to finish." },
  { id: "writing-508", title: "Character sketch of a curious young scientist", category: "writing", text: "Write a character sketch of about 250 words about a curious young scientist in [a school] who asks why about everything. Describe her messy experiments, her notebook full of questions, her failed volcano and her proud teacher, and show why her questions matter." },
  { id: "writing-509", title: "Plot idea: a diary that writes itself", category: "writing", text: "Write a plot idea for a short story about a diary that writes itself every night in [a house]. Explain what [the owner] reads each morning, what happens when the diary writes about tomorrow, and suggest an ending where the owner finally writes one page herself." },
  { id: "writing-510", title: "Funny story about a dog that guards a sweet shop", category: "writing", text: "Write a funny story about a dog that guards a sweet shop in [a town] and secretly loves laddoos. Show how the dog chases away crows but begs the shopkeeper for sweets, and end with the shopkeeper giving the dog one laddoo a day as his honest wage." },
  { id: "writing-511", title: "Folk tale about a clever jackal and a farmer", category: "writing", text: "Write a folk tale about a clever jackal who tries to trick a farmer in [a village]. Show the farmer's three calm answers that turn every trick back, add a short dialogue between them, and end with a moral about a quiet mind beating a clever tongue." },
  { id: "writing-512", title: "Festival story about a Christmas star that falls down", category: "writing", text: "Write a festival story about a Christmas star that falls from a tree in [a town] and lands in a child's hands. Show the child's wonder, the neighbours who gather to see it glow, and end with the star lighting the whole street on Christmas night." },
  { id: "writing-513", title: "Short story about a lighthouse keeper's last night", category: "writing", text: "Write a short story about a lighthouse keeper on his last night before retirement in [a coastal town]. Show his memories of storms and ships, the young keeper who arrives to learn, and end with the old keeper watching the light turn one final time." },
  { id: "writing-514", title: "Children's story about a seed that wants to be a tree", category: "writing", text: "Write a simple children's story about a small seed in [a garden] that wants to be a tall tree. Show how the sun, the rain and a kind gardener help it grow day by day, use easy words, and end with birds nesting in its branches." },
  { id: "writing-515", title: "Moral story about keeping a promise to a friend", category: "writing", text: "Write a moral story for children about [a student] who promises to help a friend with homework and then feels tempted to play instead. Show the choice, the kept promise and the friend's happy smile, and end with a line about promises making friendship strong." },
  { id: "writing-516", title: "Poem about a football match at sunset", category: "writing", text: "Write an exciting poem of four stanzas about a football match at sunset in [a village ground]. Mention dusty feet, cheering friends, a last-minute goal and the ball flying into golden light, and end with both teams shaking hands as the stars come out." },
  { id: "writing-517", title: "Haiku set about the four seasons in India", category: "writing", text: "Write a set of four haikus, one for each season in India, about summer heat, monsoon rain, autumn festivals and winter mornings. Keep each haiku to three short lines, use a clear picture in every one, and end the set with a line about the year turning again." },
  { id: "writing-518", title: "Script for a short film about a lost phone", category: "writing", text: "Write a short-film script of about five scenes about a lost phone in [a city]. Show the owner's panic, the kind stranger who finds it, and the chase through a busy market, and end with the phone returned and a new friendship beginning." },
  { id: "writing-519", title: "Dialogue between a teacher and a new student", category: "writing", text: "Write a warm dialogue between a teacher and a new student on the first day in [a school]. Let the student feel nervous, let the teacher ask gentle questions about home and hobbies, and end with the student smiling and looking forward to tomorrow." },
  { id: "writing-520", title: "Story starter: a cake that smells like rain", category: "writing", text: "Write five story starters, each two sentences long, about a cake that smells like rain in [a bakery]. Make each starter lead to a different magic, from a cake that makes people remember to one that makes them fly, and keep the endings open." },
  { id: "writing-521", title: "Character sketch of an old fisherman with many stories", category: "writing", text: "Write a character sketch of about 250 words about an old fisherman in [a coastal village] who has a story for every wave. Describe his wrinkled hands, his blue boat, his evening tales by the shore, and why children gather around him at sunset." },
  { id: "writing-522", title: "Plot idea: a city where everyone swaps jobs for a day", category: "writing", text: "Write a plot idea for a funny story about a city where everyone swaps jobs for one day in [a place]. Explain how a teacher becomes a bus driver and a cook becomes a doctor, what goes hilariously wrong, and suggest a warm ending where everyone respects each other's work." },
  { id: "writing-523", title: "Joke story about a monkey at a birthday party", category: "writing", text: "Write a funny story about a monkey that crashes a birthday party in [a garden]. Show the monkey stealing the cake, wearing the birthday cap and dancing with the children, and end with everyone laughing and giving the monkey the first slice." },
  { id: "writing-524", title: "Folk tale about a princess who loves to cook", category: "writing", text: "Write a folk tale about a princess who loves to cook in [a kingdom]. Tell how she enters a village cooking contest in disguise, what dish wins the judges' hearts, and end with a moral about skill mattering more than a crown." },
  { id: "writing-525", title: "Festival story about a Rakhi gift that travels far", category: "writing", text: "Write a festival story about a Rakhi gift that travels far across India to reach [a brother]. Show the sister tying the rakhi in her heart, the parcel's long journey by train and post, and end with the brother opening it on Raksha Bandhan morning." },
  { id: "writing-526", title: "Short story about a girl who collects lost buttons", category: "writing", text: "Write a short story about a girl in [a town] who collects lost buttons and keeps each one in a tin box. Follow one special button that leads her to its owner, show the story the owner tells, and end with the girl adding a new button and a new friend." },
  { id: "writing-527", title: "Children's story about a moon that hides behind clouds", category: "writing", text: "Write a gentle children's story about a shy moon that hides behind clouds over [a village]. Show how a little girl sings to the moon each night, use soft and simple words, and end with the moon peeking out and lighting her way home." },
  { id: "writing-528", title: "Moral story about being kind to animals", category: "writing", text: "Write a moral story for children about [a child] who rescues a hurt puppy on the street. Show the gentle care, the food and water shared, and the puppy's happy wagging tail, and end with a clear line about kindness to animals making us better people." },
  { id: "writing-529", title: "Poem about my favourite street food stall", category: "writing", text: "Write a tasty poem of four stanzas about a favourite street food stall in [a town]. Mention sizzling sounds, spicy smells, a long happy queue and the vendor who knows every regular, and end with the stall closing as the last customer licks his fingers." },
  { id: "writing-530", title: "Song lyrics for a farewell to a favourite teacher", category: "writing", text: "Write touching song lyrics for a farewell to a favourite teacher, with a chorus about lessons, laughter and guidance that stays for life. Keep the verses short and easy to sing as a class, mention [the teacher's subject] once, and end with thanks and good wishes." },
  { id: "writing-531", title: "Play script about a haunted classroom, gentle and funny", category: "writing", text: "Write a short play script for five children about a classroom in [a school] that seems haunted but turns out to be funny. Give each child lively lines, add a friendly ghost who only wants to learn, and end with the ghost joining the class for a lesson." },
  { id: "writing-532", title: "Dialogue between a butterfly and a flower", category: "writing", text: "Write a sweet dialogue between a butterfly and a flower in [a garden]. Let the butterfly thank the flower for its nectar, let the flower thank the butterfly for carrying its pollen, and end with both promising to meet again every spring morning." },
  { id: "writing-533", title: "Story starter: a train ticket to a place that does not exist", category: "writing", text: "Write five story starters, each two sentences long, about a train ticket to a place that does not exist, found by [a traveller]. Make each starter open a different impossible journey, keep the tone full of wonder, and leave every ending open for the writer." },
  { id: "writing-534", title: "Character sketch of a brave firefighter in a small town", category: "writing", text: "Write a character sketch of about 250 words about a brave firefighter in [a small town]. Describe his red helmet, his calm voice in an emergency, his habit of checking every hydrant, and the quiet way he helps children feel safe after a fire." },
  { id: "writing-535", title: "Plot idea: a garden where plants whisper secrets", category: "writing", text: "Write a plot idea for a children's story about a garden where plants whisper secrets at night in [a house]. Explain how [a child] hears them, what secret the oldest rose tells, and suggest an ending where the child helps the garden keep its secret safe." },
  { id: "writing-536", title: "Funny poem about a school lunch box", category: "writing", text: "Write a funny poem of four stanzas about [a child's] school lunch box that always holds a surprise. Mention parathas that roll away, a pickle that stains the notebook and a friend who trades tiffins, and end with the lunch box empty and the child still hungry for stories." },
  { id: "writing-537", title: "Folk tale about a sparrow who builds a palace", category: "writing", text: "Write a folk tale about a tiny sparrow who builds a palace from straw and dreams in [a village]. Tell how bigger birds laugh, how the sparrow works day after day, and end with a moral about small hands building great things with patience." },
  { id: "writing-538", title: "Festival story about a Navratri garba competition", category: "writing", text: "Write a festival story about a Navratri garba competition in [a city] where a shy girl dances for the first time. Show the swirling chaniya cholis, the beating dhol and her nervous feet finding the rhythm, and end with the crowd cheering her name at midnight." },
  { id: "writing-539", title: "Short story about a boy who talks to the wind", category: "writing", text: "Write a short story about a boy in [a village] who talks to the wind and hears its answers. Follow him on the day the wind warns of a coming storm, show how he saves the harvest, and end with the wind whispering one last secret in his ear." },
  { id: "writing-540", title: "Children's story about a star that falls into a well", category: "writing", text: "Write a simple children's story about a little star that falls into a well in [a village]. Show how the children try to lift it out with a bucket, a kite and a song, use easy words, and end with the star twinkling back up into the sky." },
  { id: "writing-541", title: "Moral story about sharing toys with a cousin", category: "writing", text: "Write a moral story for children about [a child] who does not want to share toys with a visiting cousin. Show the sulking, the cousin's quiet sadness and the fun that begins once the toys are shared, and end with a line about shared play doubling the joy." },
  { id: "writing-542", title: "Poem about a cricket match in the rain", category: "writing", text: "Write an exciting poem of four stanzas about a cricket match played in the rain in [a town]. Mention wet balls, sliding fielders, a brave batsman and cheering friends under umbrellas, and end with the match ending in a tie and everyone laughing." },
  { id: "writing-543", title: "Limerick about a forgetful postman", category: "writing", text: "Write five limericks about a forgetful postman in [a town] who delivers letters to funny places. Keep each limerick to five lines with a clear rhyme, make every mistake different and harmless, and end the set with the postman finally delivering his own letter." },
  { id: "writing-544", title: "Script for a radio play about a village fair", category: "writing", text: "Write a radio-play script for four voices about a village fair in [a place], using only sound and dialogue. Describe each sound cue in brackets, from temple bells to a Ferris wheel, and end with the fair closing as the voices say goodnight to the listeners." },
  { id: "writing-545", title: "Dialogue between a grandmother and a grandchild about old games", category: "writing", text: "Write a warm dialogue between a grandmother and a grandchild about old games in [a village]. Let the grandmother describe hopscotch, marbles and hide and seek, let the child compare them with phone games, and end with both playing hopscotch together in the courtyard." },
  { id: "writing-546", title: "Story starter: a red balloon that floats against the wind", category: "writing", text: "Write five story starters, each two sentences long, about a red balloon that floats against the wind over [a town]. Make each starter follow the balloon to a different surprise, from a rooftop party to a hidden garden, and keep the endings open." },
  { id: "writing-547", title: "Character sketch of a cheerful bus driver", category: "writing", text: "Write a character sketch of about 250 words about a cheerful bus driver in [a town] who greets every passenger by name. Describe his neat uniform, his favourite songs, his careful driving on narrow roads, and why children fight to sit in the front seat." },
  { id: "writing-548", title: "Plot idea: a bookshop that only opens at midnight", category: "writing", text: "Write a plot idea for a short story about a bookshop that only opens at midnight in [a lane]. Explain who dares to enter, what book calls out to the visitor, and suggest an ending where the visitor leaves with a story that changes one small thing." },
  { id: "writing-549", title: "Joke story about a buffalo that loves music", category: "writing", text: "Write a funny story about a buffalo in [a village] that loves music and dances whenever a drum plays. Show the villagers' surprise, the buffalo's happy swaying at a wedding, and end with the buffalo leading the whole baraat down the road." },
  { id: "writing-550", title: "Folk tale about a king who learns to listen", category: "writing", text: "Write a folk tale about a proud king who learns to listen to his people in [a kingdom]. Tell how a small child's honest words change his mind, add a short dialogue at the palace gate, and end with a moral about a good ruler having open ears." },
  { id: "writing-551", title: "Festival story about a Holi prank that goes too far", category: "writing", text: "Write a festival story about a Holi prank that goes too far in [a town]. Show the laughter turning to worry, the brave apology that follows, and the friends forgiving each other, and end with everyone playing Holi gently together the next morning." },
  { id: "writing-552", title: "Short story about a woman who paints the sky", category: "writing", text: "Write a short story about a woman in [a city] who paints the sky every evening from her rooftop. Follow [a neighbour] who watches her colours change the clouds, and end with the whole street gathering to see her paint one unforgettable sunset." },
  { id: "writing-553", title: "Children's story about a caterpillar who dreams of flying", category: "writing", text: "Write a simple children's story about a caterpillar in [a garden] who dreams of flying. Show how the caterpillar eats, sleeps and waits patiently in a cocoon, use easy words, and end with a beautiful butterfly opening its wings in the morning sun." },
  { id: "writing-554", title: "Moral story about finishing what you start", category: "writing", text: "Write a moral story for children about [a student] who starts a kite, a puzzle and a painting but finishes none of them. Show the mess, the decision to finish just one, and the pride of holding a finished kite, and end with a line about finishing bringing real joy." },
  { id: "writing-555", title: "Poem about a river flowing through my village", category: "writing", text: "Write a flowing poem of four stanzas about a river that runs through [a village]. Mention fishermen at dawn, women washing clothes, children splashing in summer and the river singing at night, and end with the river carrying the village's stories to the sea." },
  { id: "writing-556", title: "Song lyrics for a children's dance on Independence Day", category: "writing", text: "Write proud song lyrics for a children's dance on Independence Day, with a chorus about the flag, freedom and a bright future. Keep the verses short and easy to sing in a group, mention [the school name] once, and end with a cheer for India." },
  { id: "writing-557", title: "Play script about two friends and a magic chalk", category: "writing", text: "Write a short play script for four children about two friends and a magic chalk in [a school]. Let everything they draw come alive for a few minutes, add one funny drawing that causes trouble, and end with the friends drawing a rainbow that stays." },
  { id: "writing-558", title: "Dialogue between the earth and the rain", category: "writing", text: "Write a gentle dialogue between the earth and the rain over [a dry field]. Let the earth ask for water, let the rain promise to come when the clouds are ready, and end with the first drops falling and the earth smiling in relief." },
  { id: "writing-559", title: "Story starter: a photograph that changes every day", category: "writing", text: "Write five story starters, each two sentences long, about a photograph that changes every day in [a house]. Make each starter reveal a different change, from a smiling face to a growing tree, and keep the endings open for the writer to finish." },
  { id: "writing-560", title: "Character sketch of a young chef who cooks with stories", category: "writing", text: "Write a character sketch of about 250 words about a young chef in [a town] who cooks with stories from his grandmother. Describe his busy kitchen, his spice jars, his habit of tasting with closed eyes, and the dish that makes his customers ask for the story behind it." },
  { id: "writing-561", title: "Plot idea: a village where wishes come true once a year", category: "writing", text: "Write a plot idea for a short story about a village where one wish comes true once a year on [a festival night]. Explain how [a child] chooses a wish, what goes wrong when a selfish wish is made, and suggest a kind ending where the village wishes together." },
  { id: "writing-562", title: "Funny story about a classroom pet that escapes", category: "writing", text: "Write a funny story about a classroom pet that escapes in [a school]. Show the rabbit hopping through corridors, the chase through the library and the playground, and end with the rabbit found asleep in the principal's chair, looking very pleased with itself." },
  { id: "writing-563", title: "Folk tale about a clever fox and a mango tree", category: "writing", text: "Write a folk tale about a clever fox who guards a mango tree in [a village]. Tell how the fox outwits greedy travellers with three riddles, add a short dialogue under the tree, and end with a moral about wit protecting what greed would steal." },
  { id: "writing-564", title: "Festival story about a Janmashtami dahi handi team", category: "writing", text: "Write a festival story about a Janmashtami dahi handi team in [a city] that keeps falling short of the pot. Show the practice, the teamwork and the youngest climber's brave final try, and end with the pot breaking and sweet curd raining on cheering friends." },
  { id: "writing-565", title: "Short story about a letter that arrives fifty years late", category: "writing", text: "Write a short story about a letter that arrives fifty years late in [a town]. Follow the old woman who opens it, show the young love and the lost address inside, and end with her smiling because some words stay true even after fifty years." },
  { id: "writing-566", title: "Essay on my school library", category: "writing", text: "Write a 200-word essay on my school library for [Class 7 / Class 8]. Describe the books, the reading room and the librarian, explain how the library helps me study, and end with why every student should visit it often." },
  { id: "writing-567", title: "Essay on the importance of reading books", category: "writing", text: "Write a 200-word essay on the importance of reading books for a school competition. Give three clear benefits for students, add one example from [a book I read recently], and finish with a simple message for young readers." },
  { id: "writing-568", title: "Essay on discipline in student life", category: "writing", text: "Write a 200-word essay on discipline in student life for [Class 8]. Explain what discipline means at home and at school, give two daily examples from my own routine, and end with how discipline helps students succeed." },
  { id: "writing-569", title: "Essay on my favourite subject", category: "writing", text: "Write a 180-word essay on my favourite subject, [mathematics / science / English], for a class test. Say why I like it, name my teacher and one lesson I enjoyed, and explain how I practise it every week." },
  { id: "writing-570", title: "Essay on a visit to a science exhibition", category: "writing", text: "Write a 200-word essay on a visit to a science exhibition at [place] with my class. Describe two exhibits I liked most, explain what I learned from each one, and end with why such visits make science easier to understand." },
  { id: "writing-571", title: "Essay on the value of time for students", category: "writing", text: "Write a 200-word essay on the value of time for students. Explain why wasting time hurts our studies, describe a simple daily timetable I follow, and end with one piece of advice for classmates in [my class] who keep postponing homework." },
  { id: "writing-572", title: "Essay on my best friend at school", category: "writing", text: "Write a 180-word essay on my best friend at school, [name]. Describe how we met, what we like doing together, and one time my friend helped me, and end with what true friendship means to me." },
  { id: "writing-573", title: "Essay on a memorable school function", category: "writing", text: "Write a 200-word essay on a memorable school function, [annual day / sports day / science day]. Describe the preparations, the best performance I saw, and how I felt that day, in simple and clear sentences." },
  { id: "writing-574", title: "Essay on keeping our surroundings clean", category: "writing", text: "Write a 200-word essay on keeping our surroundings clean for [Class 6 / Class 7]. Explain why clean streets and classrooms matter, give three simple habits students can follow, and end with a request to my neighbours to join in." },
  { id: "writing-575", title: "Essay on the importance of sports and games", category: "writing", text: "Write a 200-word essay on the importance of sports and games for students. Explain how playing [cricket / kabaddi / football] keeps us healthy and teaches teamwork, and why games deserve time along with studies." },
  { id: "writing-576", title: "Essay on my hobby of gardening", category: "writing", text: "Write a 180-word essay on my hobby of gardening at home. Describe the plants I grow, what I do for them every morning, and what gardening in [my home garden] has taught me about patience and care for nature." },
  { id: "writing-577", title: "Essay on a visit to a museum", category: "writing", text: "Write a 200-word essay on a visit to a museum in [city] with my school. Describe three things I saw there, explain what I learned about history, and end with why every student should visit a museum once." },
  { id: "writing-578", title: "Essay on the importance of yoga for students", category: "writing", text: "Write a 200-word essay on the importance of yoga for students. Explain how simple yoga and breathing help us stay calm, healthy and focused, and describe the morning routine I follow before school at [home]." },
  { id: "writing-579", title: "Essay on saving water at home and school", category: "writing", text: "Write a 200-word essay on saving water at home and at school. Explain why water must not be wasted, give four practical ways students can save it daily, and end with a promise I will keep at [home and school]." },
  { id: "writing-580", title: "Essay on a day without my mobile phone", category: "writing", text: "Write a 200-word essay on a day without my mobile phone. Describe what I did instead, how I felt without games and videos, and what I learned about using my time better during [a holiday]." },
  { id: "writing-581", title: "Essay on my neighbourhood and its people", category: "writing", text: "Write a 200-word essay on my neighbourhood in [town / city]. Describe the streets, shops and park near my home, the people who help us, and why I feel safe and happy living here." },
  { id: "writing-582", title: "Essay on a historical place I visited", category: "writing", text: "Write a 200-word essay on a historical place I visited, [name of place]. Describe what I saw there, share one interesting fact I learned from my teacher, and explain why we must protect such places." },
  { id: "writing-583", title: "Essay on a book that changed my thinking", category: "writing", text: "Write a 200-word essay on a book that changed my thinking, [book title]. Say what the book is about, which idea stayed with me, and how it changed the way I study or behave." },
  { id: "writing-584", title: "Essay on kindness in everyday life", category: "writing", text: "Write a 200-word essay on kindness in everyday life for a school magazine. Give three small examples of kindness at school and at home, and explain how one kind act at [school] can change someone's whole day." },
  { id: "writing-585", title: "Essay on my school annual sports day", category: "writing", text: "Write a 200-word essay on my school annual sports day. Describe the march past, the race I took part in or watched, and the prize distribution, and end with what I learned about winning and losing at [my school sports day]." },
  { id: "writing-586", title: "Argumentative essay on homework: help or burden", category: "writing", text: "Write a 250-word argumentative essay on whether homework helps students or burdens them. Give two points for homework and two points against it, use examples from [my class], and end with my own balanced opinion." },
  { id: "writing-587", title: "Essay for and against online classes", category: "writing", text: "Write a 250-word essay giving arguments for and against online classes for school students. Cover learning, health and friendship, use simple examples from my own experience in [Class 9], and end with a clear conclusion." },
  { id: "writing-588", title: "Essay on whether school uniforms should continue", category: "writing", text: "Write a 250-word essay on whether school uniforms should continue. Give two reasons in favour of uniforms and two reasons against them, and finish by stating which side I, a student of [Class 8], support and why." },
  { id: "writing-589", title: "Essay on social media and student concentration", category: "writing", text: "Write a 250-word essay on how social media affects student concentration. Explain the distractions, the good uses for learning, and three simple rules I follow to use my phone wisely during [study hours]." },
  { id: "writing-590", title: "Essay on exams: marks or real learning", category: "writing", text: "Write a 250-word essay on whether exams should test marks or real learning. Give examples of what marks cannot show, explain what real learning means, and suggest one change that would make exams in [my school] fairer." },
  { id: "writing-591", title: "Essay on banning junk food near schools", category: "writing", text: "Write a 250-word essay on whether junk food shops near schools should be banned. Give health reasons for a ban, consider why students still buy it, and suggest healthier food options for our canteen at [my school]." },
  { id: "writing-592", title: "Essay on the need for a library period every week", category: "writing", text: "Write a 200-word essay arguing that every school timetable should include a library period every week. Explain how it builds reading habits, give examples from [my school library], and suggest what students should do in that period." },
  { id: "writing-593", title: "Essay on tree planting in every school", category: "writing", text: "Write a 200-word essay on why every school should plant more trees. Explain the benefits for shade, clean air and birds, describe how our class planted [number] saplings, and ask students to care for them." },
  { id: "writing-594", title: "Essay on why every student should learn first aid", category: "writing", text: "Write a 200-word essay on why every student should learn first aid. Explain how basic first aid helps in small accidents at school and at home, and describe what I learned in our school training session on [date]." },
  { id: "writing-595", title: "Essay on reducing plastic in school canteens", category: "writing", text: "Write a 200-word essay on reducing plastic in school canteens. Explain how plastic harms our health and surroundings, suggest steel bottles and plates instead, and propose a simple plan my class, [Class 7], can follow." },
  { id: "writing-596", title: "Essay on morning assembly: a good start to the day", category: "writing", text: "Write a 200-word essay on why morning assembly is a good start to the school day. Describe the prayer, thought of the day and news reading, and explain how assembly at [my school] builds discipline and confidence in students." },
  { id: "writing-597", title: "Essay on co-curricular activities and studies", category: "writing", text: "Write a 250-word essay on how co-curricular activities like [music / dance / drawing / sports] support studies. Give two benefits and one warning about balance, with examples from my own school life." },
  { id: "writing-598", title: "Essay on the importance of learning my mother tongue", category: "writing", text: "Write a 200-word essay on the importance of learning my mother tongue, [Tamil / Hindi / Telugu / another language]. Explain how it connects me to my family and culture, and why it matters along with English." },
  { id: "writing-599", title: "Essay on village schools and city schools", category: "writing", text: "Write a 250-word essay comparing village schools and city schools. Compare classrooms, teachers, transport and play areas fairly, and end with what each type of school in [my district] can learn from the other." },
  { id: "writing-600", title: "Essay on how students can fight exam stress", category: "writing", text: "Write a 250-word essay on how students can fight exam stress. Explain why stress happens before exams, and give five practical tips on sleep, revision, food and talking to parents and teachers before [my board exams]." },
  { id: "writing-601", title: "Short paragraph on the importance of trees", category: "writing", text: "Write one paragraph of about 100 words on the importance of trees for [Class 5 / Class 6]. Mention clean air, shade, fruits and homes for birds, using simple sentences that a young student can read and remember." },
  { id: "writing-602", title: "Paragraph on my daily routine as a student", category: "writing", text: "Write one paragraph of about 120 words on my daily routine as a student. Cover waking up, school, homework, play and sleep, in the order they happen, using simple present-tense sentences about [my school day]." },
  { id: "writing-603", title: "Paragraph on the uses of a computer in studies", category: "writing", text: "Write one paragraph of about 120 words on the uses of a computer in studies. Mention typing notes, watching lessons, practising sums and reading e-books, and add one warning about too much screen time after [school hours]." },
  { id: "writing-604", title: "Paragraph on a rainy morning before school", category: "writing", text: "Write one paragraph of about 120 words describing a rainy morning before school. Describe the rain, the wet road, my umbrella and school bag, and how I reached [my school] on time despite the rain." },
  { id: "writing-605", title: "Paragraph on my favourite festival at school", category: "writing", text: "Write one paragraph of about 120 words on my favourite festival as celebrated at school, [Diwali / Pongal / Christmas / Eid]. Describe the decorations, the programme and what I enjoyed most that day." },
  { id: "writing-606", title: "Paragraph on the duties of a class monitor", category: "writing", text: "Write one paragraph of about 120 words on the duties of a class monitor. Explain how the monitor helps the teacher, keeps the class quiet, collects notebooks and sets an example for other students in [Class 6]." },
  { id: "writing-607", title: "Paragraph on why I like my school", category: "writing", text: "Write one paragraph of about 120 words on why I like my school, [school name]. Mention my teachers, my friends, the playground and the library, and end with one sentence about what makes my school special." },
  { id: "writing-608", title: "Paragraph on a kind act by a classmate", category: "writing", text: "Write one paragraph of about 120 words on a kind act by a classmate, [name]. Describe what happened, how my classmate helped me or someone else, and what I learned from that small act of kindness." },
  { id: "writing-609", title: "Paragraph on the importance of eating breakfast", category: "writing", text: "Write one paragraph of about 120 words on the importance of eating breakfast before school. Explain how breakfast gives energy and helps us concentrate, and name two healthy breakfast foods, like [idli / poha], I eat at home." },
  { id: "writing-610", title: "Paragraph on a visit to my grandparents' village", category: "writing", text: "Write one paragraph of about 120 words on a visit to my grandparents' village during the holidays. Describe the fields, the food, the games I played, and what I enjoyed most about village life in [my grandparents' village]." },
  { id: "writing-611", title: "Short paragraph on the water cycle for Class 6", category: "writing", text: "Write one paragraph of about 100 words on the water cycle for a Class 6 science answer. Explain evaporation, condensation and rain in simple order, and give one everyday example from [rain on my roof / a boiling kettle]." },
  { id: "writing-612", title: "Short paragraph on the seasons in India for Class 5", category: "writing", text: "Write one paragraph of about 100 words on the seasons in India for a Class 5 answer. Name summer, rainy season and winter, describe the weather and clothes in each, and say which season I like best in [my state] and why." },
  { id: "writing-613", title: "Paragraph on how I prepare for an exam the night before", category: "writing", text: "Write one paragraph of about 120 words on how I prepare for an exam the night before. Describe revising notes, packing my bag, sleeping early, and staying calm, in simple steps a classmate in [my class] can follow." },
  { id: "writing-614", title: "Paragraph on my school bus journey every morning", category: "writing", text: "Write one paragraph of about 120 words on my school bus journey every morning. Describe the bus stop, my friends on the bus, the route through [area name], and what I see from the window on the way to school." },
  { id: "writing-615", title: "Paragraph on the person I admire most in my family", category: "writing", text: "Write one paragraph of about 120 words on the person I admire most in my family, [mother / father / grandmother / grandfather]. Describe their daily work, one quality I admire, and what I want to learn from them." },
  { id: "writing-616", title: "Report on our school annual day function", category: "writing", text: "Write a report of about 200 words on our school annual day function held on [date]. Mention the chief guest, the welcome speech, three programmes, and the prize distribution, in the order they happened." },
  { id: "writing-617", title: "Report on a blood donation camp at school", category: "writing", text: "Write a report of about 200 words on a blood donation camp held at our school on [date]. Mention who organised it, how many people donated, what the doctor said, and why donating blood saves lives." },
  { id: "writing-618", title: "Report on a tree-plantation drive in our school", category: "writing", text: "Write a report of about 200 words on a tree-plantation drive in our school. Mention the date, the number of saplings planted, who took part, and how students of [Class 6] promised to water and protect the young trees." },
  { id: "writing-619", title: "Report on a visit to a local post office", category: "writing", text: "Write a report of about 200 words on our class visit to a local post office in [area]. Describe what the postmaster showed us, how letters are sorted, and what I learned about sending a letter and a money order." },
  { id: "writing-620", title: "Report on a science exhibition held in school", category: "writing", text: "Write a report of about 200 words on a science exhibition held in our school on [date]. Describe the best three projects, name the students who made them, and mention which project won the first prize and why." },
  { id: "writing-621", title: "Report on an inter-school cricket match", category: "writing", text: "Write a report of about 200 words on an inter-school cricket match between [our school] and [other school]. Give the scores, name the best batsman and bowler, and describe the exciting final overs." },
  { id: "writing-622", title: "Report on a cleanliness drive in our locality", category: "writing", text: "Write a report of about 200 words on a cleanliness drive in our locality organised by our school. Mention the date, the area cleaned, how many students joined, and what residents of [my locality] said about the work." },
  { id: "writing-623", title: "Report on a book fair visit with my class", category: "writing", text: "Write a report of about 200 words on a book fair visit with my class in [city]. Describe the stalls we visited, the books I bought or liked, and why book fairs make reading fun for students." },
  { id: "writing-624", title: "Report on a workshop on road safety at school", category: "writing", text: "Write a report of about 200 words on a workshop on road safety held at our school. Mention the guest speaker, the traffic rules explained, the demo on wearing a helmet, and what students of [my school] promised to follow." },
  { id: "writing-625", title: "Report on a visit to a fire station", category: "writing", text: "Write a report of about 200 words on our class visit to a fire station in [town]. Describe the fire engine, the equipment shown, the demo of a water hose, and what I learned about fire safety at home." },
  { id: "writing-626", title: "Report on a school health check-up camp", category: "writing", text: "Write a report of about 200 words on a health check-up camp held at our school on [date]. Mention the doctors who came, the eye and height checks, and the health tips they gave students about food and exercise." },
  { id: "writing-627", title: "Report on our class picnic to a nearby park", category: "writing", text: "Write a report of about 200 words on our class picnic to a nearby park in [place]. Describe the journey, the games we played, the lunch we shared, and the happiest moment of the day." },
  { id: "writing-628", title: "Report on a debate competition held in school", category: "writing", text: "Write a report of about 200 words on a debate competition held in our school on [date]. Give the topic, name the winning team and the best speaker, and summarise the strongest point made by each side." },
  { id: "writing-629", title: "Report on a visit to a bank for a school project", category: "writing", text: "Write a report of about 200 words on our visit to a bank in [area] for a school project. Describe what the bank manager explained about saving accounts, and what I learned about saving money regularly." },
  { id: "writing-630", title: "Report on a yoga day celebration at school", category: "writing", text: "Write a report of about 200 words on a yoga day celebration at our school on [date]. Describe the morning assembly, the yoga poses practised, the teacher who guided us, and how students felt afterwards." },
  { id: "writing-631", title: "Speech for morning assembly on honesty", category: "writing", text: "Write a 2-minute speech for morning assembly on honesty for [Class 7 / Class 8]. Start with a short story or example, explain why honesty matters in school life, and end with a promise students can repeat together." },
  { id: "writing-632", title: "Speech for morning assembly on saving electricity", category: "writing", text: "Write a 2-minute speech for morning assembly on saving electricity. Give four simple habits for home and school, explain why saving power helps our country, and end with a clear call to action for students of [my school]." },
  { id: "writing-633", title: "Speech on Teachers' Day by a Class 8 student", category: "writing", text: "Write a 2-minute Teachers' Day speech by a Class 8 student. Thank all teachers, share one memory of my favourite teacher [name], and explain how teachers shape our future with patience and care." },
  { id: "writing-634", title: "Speech on Children's Day for the school stage", category: "writing", text: "Write a 2-minute Children's Day speech for the school stage. Explain why this day is celebrated, what children need most from parents and teachers, and end with a joyful message for all students of [my school]." },
  { id: "writing-635", title: "Speech on Independence Day for a school function", category: "writing", text: "Write a 2-minute Independence Day speech for a school function. Mention the freedom struggle in simple words, name one freedom fighter I admire, and explain my duties as a young citizen of India studying in [Class 8]." },
  { id: "writing-636", title: "Speech on Republic Day for the school assembly", category: "writing", text: "Write a 2-minute Republic Day speech for the school assembly. Explain what the Constitution means for every citizen, mention our rights and duties, and end with a promise to respect our national flag at [my school]." },
  { id: "writing-637", title: "Speech to welcome a new principal on her first day", category: "writing", text: "Write a short welcome speech to greet a new principal on her first day at our school. Introduce our school, mention what students hope to learn from her, and end with warm wishes for her time at [my school]." },
  { id: "writing-638", title: "Speech to thank the chief guest after a school function", category: "writing", text: "Write a short speech to thank the chief guest after a school function. Mention the guest by name, recall one useful point from their speech, and thank the teachers, parents and students of [my school] who helped." },
  { id: "writing-639", title: "Speech for a farewell party for Class 10 students", category: "writing", text: "Write a 2-minute farewell speech for Class 10 students from a Class 9 student. Share happy memories, wish the seniors well for their board exams, and promise to follow their good example in [my school]." },
  { id: "writing-640", title: "Speech on World Environment Day for assembly", category: "writing", text: "Write a 2-minute speech on World Environment Day for morning assembly. Explain why trees, clean water and clean air matter, and give three things students at [my school] can do every day to protect our environment." },
  { id: "writing-641", title: "Speech on the importance of reading for assembly", category: "writing", text: "Write a 2-minute speech on the importance of reading for morning assembly. Explain how books improve our language and imagination, share one book I loved, and invite classmates to join the library at [my school]." },
  { id: "writing-642", title: "Speech by a prize winner thanking teachers and parents", category: "writing", text: "Write a 1-minute speech by a prize winner thanking teachers and parents after receiving [prize name]. Share how I prepared, thank the people who supported me, and encourage classmates to work hard too." },
  { id: "writing-643", title: "Speech on Gandhi Jayanti for morning assembly", category: "writing", text: "Write a 2-minute speech on Gandhi Jayanti for morning assembly. Explain who Mahatma Gandhi was in simple words, recall his message of truth and non-violence, and say how students in [my class] can follow it today." },
  { id: "writing-644", title: "Speech on the importance of punctuality for assembly", category: "writing", text: "Write a 2-minute speech on the importance of punctuality for morning assembly. Explain how being on time helps studies and builds trust, give two examples from school life, and end with a daily promise for students of [Class 7]." },
  { id: "writing-645", title: "Speech for the investiture ceremony of student leaders", category: "writing", text: "Write a 2-minute speech for the investiture ceremony of student leaders. Congratulate the new head boy, head girl and prefects, explain their duties, and ask all students of [my school] to support them with respect." },
  { id: "writing-646", title: "Notice about a school painting competition", category: "writing", text: "Write a school notice about a painting competition on [date] for students of Classes [6 to 8]. Give the topic, venue, time, last date to register, and the name of the teacher to contact." },
  { id: "writing-647", title: "Notice about a lost library book on the school board", category: "writing", text: "Write a school notice about a lost library book titled [book title]. Describe the book, say where it was last seen, and ask the finder to return it to the library or to [teacher name]." },
  { id: "writing-648", title: "Notice about a school timing change for winter", category: "writing", text: "Write a school notice informing students and parents about a winter timing change from [date]. Give the new opening and closing times, the reason for the change, and the name of the issuing authority." },
  { id: "writing-649", title: "Notice about an inter-house quiz competition", category: "writing", text: "Write a school notice about an inter-house quiz competition on [date]. Give the venue, time, classes allowed, team size, and the last date for house captains to submit team names." },
  { id: "writing-650", title: "Notice about a school excursion to a historical place", category: "writing", text: "Write a school notice about an excursion to [historical place] on [date] for Class [8]. Give the fee, departure time, things to carry, and the last date for parents to give written consent." },
  { id: "writing-651", title: "Notice about a fancy-dress competition for primary classes", category: "writing", text: "Write a school notice about a fancy-dress competition for primary classes on [date]. Give the theme, venue, time limit for each child, and the teacher to contact for registration." },
  { id: "writing-652", title: "Notice about a parent-teacher meeting at school", category: "writing", text: "Write a school notice about a parent-teacher meeting on [date] from [time] in [venue]. Tell parents to meet the class teacher, bring the report card, and confirm attendance with the school office." },
  { id: "writing-653", title: "Notice about a book donation drive in school", category: "writing", text: "Write a school notice about a book donation drive from [start date] to [end date]. Ask students to donate old storybooks in good condition, and say where to drop them and who will receive them." },
  { id: "writing-654", title: "Notice about a school sports trial selection", category: "writing", text: "Write a school notice about sports trial selection for [cricket / football / athletics] on [date]. Give the venue, time, classes allowed, dress code, and the coach students must report to." },
  { id: "writing-655", title: "Notice about a change in the school bus route and timings", category: "writing", text: "Write a school notice about a change in the school bus route and timings from [date]. Give the new route, the new pick-up times for [area], and the phone number of the transport in-charge for questions." },
  { id: "writing-656", title: "Notice about a school cultural fest audition", category: "writing", text: "Write a school notice about auditions for the school cultural fest on [date]. List the events, singing, dance and drama, give the venue and time, and say how students can register their names." },
  { id: "writing-657", title: "Notice inviting articles for the school magazine", category: "writing", text: "Write a school notice inviting articles for the school magazine. Give the theme, the word limit, the last date to submit, and the teacher, [teacher name], to whom students should hand in their handwritten or typed articles." },
  { id: "writing-658", title: "Notice about a first-aid training session for students", category: "writing", text: "Write a school notice about a first-aid training session for students of Classes [7 to 9] on [date]. Give the venue, time, trainer name, and what students should bring to the session." },
  { id: "writing-659", title: "Notice about a school charity collection for flood relief", category: "writing", text: "Write a school notice about a charity collection for flood relief in [place]. Ask students to donate clothes, notebooks or money by [date], and say where to hand in the donations at school." },
  { id: "writing-660", title: "Notice about an English handwriting competition", category: "writing", text: "Write a school notice about an English handwriting competition on [date] for Classes [4 to 6]. Give the venue, time, passage details, and the name of the teacher in charge of the competition." },
  { id: "writing-661", title: "Leave application to attend a cousin's wedding", category: "writing", text: "Write a leave application to my school principal for [number] days to attend my cousin's wedding in [place]. Give the dates clearly, say who will look after my studies, and request the principal to grant leave." },
  { id: "writing-662", title: "Leave application for a sports tournament", category: "writing", text: "Write a leave application to my school principal for [number] days to play in a [district / state] level [sport] tournament. Mention the dates and venue, and request leave and permission to represent the school." },
  { id: "writing-663", title: "Leave application for a medical check-up", category: "writing", text: "Write a leave application to my college principal for one day for a medical check-up at [hospital name]. Mention the date, attach the doctor's note if needed, and request the principal to grant leave for that day." },
  { id: "writing-664", title: "Application for a library card in school", category: "writing", text: "Write an application to my school librarian requesting a new library card for [my school library]. Give my name, class, section and roll number, explain that my old card is lost, and request a duplicate card at the earliest." },
  { id: "writing-665", title: "Application for a hostel seat in college", category: "writing", text: "Write an application to my college principal requesting a hostel seat for the new academic year. Give my name, course, year and home town, explain why I need hostel accommodation, and request a seat in [the college hostel]." },
  { id: "writing-666", title: "Application for a fee concession from the principal", category: "writing", text: "Write an application to my school principal requesting a fee concession for [my class] this academic year. Explain my family's financial situation briefly, mention my attendance and marks, and request a partial concession." },
  { id: "writing-667", title: "Application for a scholarship in college", category: "writing", text: "Write an application to my college principal requesting a scholarship for [merit / need-based] support. Give my name, course, marks and family income details, and list the documents I have attached." },
  { id: "writing-668", title: "Application to change my optional subject in Class 11", category: "writing", text: "Write an application to my school principal requesting a change of optional subject in Class 11 from [current subject] to [new subject]. Give the reason for the change and request approval before the last date." },
  { id: "writing-669", title: "Application for re-evaluation of my answer sheet", category: "writing", text: "Write an application to my college principal requesting re-evaluation of my answer sheet for [subject] in the [exam name]. Give my roll number and marks, explain why I seek re-checking, and request the process." },
  { id: "writing-670", title: "Application for a duplicate marksheet from college", category: "writing", text: "Write an application to my college office requesting a duplicate marksheet for [course and semester]. Give my name, roll number and year of passing, explain that the original is lost, and request a duplicate copy." },
  { id: "writing-671", title: "Application for a bus pass for the new school year", category: "writing", text: "Write an application to my school principal requesting a bus pass for the new school year. Give my name, class, home address and bus route, and request the principal to issue the pass for [my bus route] at the earliest." },
  { id: "writing-672", title: "Application for permission to attend a coaching class after school", category: "writing", text: "Write an application to my school principal seeking permission to attend a coaching class after school hours. Give the coaching timings and place, promise it will not affect my homework, and request permission from [the principal]." },
  { id: "writing-673", title: "Application for extra classes before board exams", category: "writing", text: "Write an application to my school principal requesting extra classes before the board exams for [subject]. Explain that many Class 10 students find the subject difficult, and suggest morning or evening timings." },
  { id: "writing-674", title: "Application for a migration certificate after Class 12", category: "writing", text: "Write an application to my school principal requesting a migration certificate after passing Class 12. Give my name, roll number and year of passing, and explain that I need it for college admission in [city]." },
  { id: "writing-675", title: "Application for permission to organise a class farewell", category: "writing", text: "Write an application to my school principal seeking permission to organise a farewell for Class [10 / 12] on [date]. Give the venue, time, programme plan and budget, and request approval and teacher guidance." },
  { id: "writing-676", title: "Application for a school identity card replacement", category: "writing", text: "Write an application to my school office requesting a replacement identity card. Give my name, class, section and roll number, explain that my card is lost, and request a new card for [Class 7] at the earliest." },
  { id: "writing-677", title: "Application to the principal about a leaking classroom roof", category: "writing", text: "Write an application to my school principal about a leaking classroom roof in [class and section]. Describe the problem during rain, explain how it disturbs lessons, and request urgent repair before the monsoon." },
  { id: "writing-678", title: "Application for leave to prepare for a state-level exam", category: "writing", text: "Write an application to my college principal requesting leave for [number] days to prepare for a state-level exam, [exam name]. Give the exam date, explain my preparation plan, and request leave from [start date]." },
  { id: "writing-679", title: "Application for a no-dues certificate before leaving college", category: "writing", text: "Write an application to my college office requesting a no-dues certificate before leaving college. Give my name, course, year and roll number, and confirm I have returned library books to [the college library] and cleared all dues." },
  { id: "writing-680", title: "Application to join the school cricket team", category: "writing", text: "Write an application to my school sports teacher requesting selection for the school cricket team. Give my name, class and age, mention my experience in [local matches / coaching], and request a chance in the trials." },
  { id: "writing-681", title: "Debate points for the motion: homework should be banned", category: "writing", text: "Give me five strong debate points for the motion that homework should be banned, for a school debate in [Class 8]. Each point should be one clear sentence with a short example from student life, in simple English." },
  { id: "writing-682", title: "Debate points against online classes", category: "writing", text: "Give me five strong debate points against the motion that online classes are better than classroom classes. Each point should be one clear sentence with a short example, in simple English for a school debate in [Class 9]." },
  { id: "writing-683", title: "Debate points for the motion: every student should learn a sport", category: "writing", text: "Give me five strong debate points for the motion that every student should learn a sport. Each point should be one clear sentence with a short example about health, discipline or teamwork, in simple English for a debate in [my school]." },
  { id: "writing-684", title: "Debate points for the motion: reading books beats watching videos", category: "writing", text: "Give me five strong debate points for the motion that reading books beats watching videos for students. Each point should be one clear sentence with a short example, in simple English for a school debate in [Class 8]." },
  { id: "writing-685", title: "Elocution piece on my dream India", category: "writing", text: "Write a 2-minute elocution piece on my dream India for a school competition. Describe the India I dream of, clean, kind and educated, with vivid examples from [my town], and end with what I will do to build it." },
  { id: "writing-686", title: "Elocution piece on the power of kindness", category: "writing", text: "Write a 2-minute elocution piece on the power of kindness for a school competition. Start with a small true story, explain how kindness spreads, and end with a line the audience at [my school] will remember." },
  { id: "writing-687", title: "Elocution piece on a leader I admire", category: "writing", text: "Write a 2-minute elocution piece on a leader I admire, [name]. Explain what the leader did, which quality inspires me most, and how I try to follow that example in my school life." },
  { id: "writing-688", title: "Debate points against the motion: examinations should be abolished", category: "writing", text: "Give me five strong debate points against the motion that examinations should be abolished. Each point should be one clear sentence with a short example, in simple English for a school debate in [Class 10]." },
  { id: "writing-689", title: "Elocution piece on the importance of voting when I turn eighteen", category: "writing", text: "Write a 2-minute elocution piece on the importance of voting when I turn eighteen. Explain what voting means in a democracy, why young voters matter, and how I will choose my candidate responsibly in [my constituency]." },
  { id: "writing-690", title: "Debate points for the motion: girls and boys should play sports together", category: "writing", text: "Give me five strong debate points for the motion that girls and boys should play sports together in school. Each point should be one clear sentence with a short example about fairness and teamwork in [my school]." },
  { id: "writing-691", title: "Elocution piece on saving our rivers", category: "writing", text: "Write a 2-minute elocution piece on saving our rivers for a school competition. Explain why rivers matter for drinking water and farming, describe how pollution harms them, and end with a call to action for students of [my school]." },
  { id: "writing-692", title: "Debate points against the motion: private tuitions are necessary for success", category: "writing", text: "Give me five strong debate points against the motion that private tuitions are necessary for success. Each point should be one clear sentence with a short example, in simple English for a school debate in [Class 9]." },
  { id: "writing-693", title: "Elocution piece on my favourite freedom fighter", category: "writing", text: "Write a 2-minute elocution piece on my favourite freedom fighter, [name]. Tell one brave story from their life, explain what I learned from it, and end with a salute to their sacrifice." },
  { id: "writing-694", title: "Debate points for the motion: every school should have a garden", category: "writing", text: "Give me five strong debate points for the motion that every school should have a garden. Each point should be one clear sentence with a short example about nature, food or learning, in simple English for a debate in [my school]." },
  { id: "writing-695", title: "Elocution piece on the value of hard work", category: "writing", text: "Write a 2-minute elocution piece on the value of hard work for a school competition. Start with a story of a hardworking student, explain why effort beats talent, and end with an inspiring closing line for [my classmates]." },
  { id: "writing-696", title: "Summary of a chapter for exam revision", category: "writing", text: "Summarise a chapter from my [subject] textbook, [chapter name], in about 200 words for exam revision. Cover the main ideas, three key points and two important terms, in simple language I can revise quickly." },
  { id: "writing-697", title: "Notes-making from a history chapter", category: "writing", text: "Make clear notes from a history chapter on [topic] for my Class [8 / 9] exam. Give a short heading, five bullet points with dates and names, and a one-line summary I can revise the night before." },
  { id: "writing-698", title: "How to write a 5-mark answer in a board exam", category: "writing", text: "Explain how to write a 5-mark answer in a board exam for [subject], using [a sample question]. Show the opening line, the main points in order, and a closing line, keeping the answer within the time limit." },
  { id: "writing-699", title: "How to write a 3-mark answer in a science exam", category: "writing", text: "Explain how to write a 3-mark answer in a science exam for [Class 9 / Class 10], using [a sample question]. Show the definition, one reason and one example, in short sentences that earn full marks." },
  { id: "writing-700", title: "Model answer for a long question in social science", category: "writing", text: "Write a model answer for a long question in social science on [topic] for a Class 10 exam. Use an introduction, four clear points with examples, and a conclusion, in about 250 words of simple English." },
  { id: "writing-701", title: "Summary of a story from my English textbook", category: "writing", text: "Summarise a story from my English textbook, [story title], in about 150 words. Cover the main characters, the problem they faced, how it was solved, and the moral of the story in simple language." },
  { id: "writing-702", title: "Notes-making from a geography lesson on rivers", category: "writing", text: "Make clear notes from a geography lesson on rivers in India for my Class [7 / 8] exam. List three major rivers, their source and where they flow, with a short heading and bullet points I can revise quickly." },
  { id: "writing-703", title: "How to answer a map question in a geography exam", category: "writing", text: "Explain how to answer a map question in a geography exam for [Class 9 / Class 10]. Show how to read the map, mark [states / rivers / cities] correctly, and label them neatly without losing marks." },
  { id: "writing-704", title: "How to write a precis of a passage for an exam", category: "writing", text: "Explain how to write a precis of a passage for an exam, using [a sample passage]. Show how to find the main idea, cut extra details, and rewrite it in my own words in about one-third of the length." },
  { id: "writing-705", title: "How to attempt a comprehension passage in an English exam", category: "writing", text: "Explain how to attempt a comprehension passage in an English exam for [Class 9 / Class 10]. Show how to read the passage twice, find answers in the text, and write short answers in my own words." },
  { id: "writing-706", title: "How to revise a full chapter in one hour before an exam", category: "writing", text: "Explain how to revise a full chapter in one hour before an exam for [subject]. Give a simple 60-minute plan with reading, recalling and practising questions, and tips to stay calm and focused." },
  { id: "writing-707", title: "Project write-up on the water cycle for Class 7", category: "writing", text: "Write a project write-up on the water cycle for Class 7 science. Cover the aim, materials, steps, a simple diagram description, observations and conclusion, in about 300 words of simple English for [Class 7 science]." },
  { id: "writing-708", title: "Project write-up on types of soil for a school project", category: "writing", text: "Write a project write-up on types of soil for a school science project. Cover the aim, soil samples collected from [place], what I observed, and a conclusion about which soil suits farming best." },
  { id: "writing-709", title: "Project write-up on a survey of trees in my locality", category: "writing", text: "Write a project write-up on a survey of trees in my locality for school. Cover the aim, how I counted [number] trees, the common species found, and a conclusion about planting more trees." },
  { id: "writing-710", title: "Project write-up on the history of my town for school", category: "writing", text: "Write a project write-up on the history of my town, [town name], for school. Cover its old name, famous places, important events and how it has changed, in about 300 words of simple English." },
  { id: "writing-711", title: "Blog post announcing a new product launch", category: "writing", text: "Write a warm blog post announcing my new product [product name] for customers in [city]. Explain what it does, who it is for, the price, and why I made it, in simple words. End with a clear invitation to visit my shop or message me on WhatsApp to order." },
  { id: "writing-712", title: "Blog post that turns one customer question into a full guide", category: "writing", text: "Turn the customer question [question] into a helpful blog post for my business [business name]. Answer it step by step in plain English, give one practical example from India, clear up a common doubt, and end by inviting readers to ask their own questions in the comments." },
  { id: "writing-713", title: "Blog post sharing a behind-the-scenes look at my business", category: "writing", text: "Write a friendly blog post showing how we work behind the scenes at [business name] in [city]. Describe a normal day, who does what, how we check quality, and one small detail customers never see. Keep the tone honest, warm, and simple for first-time readers." },
  { id: "writing-714", title: "Blog post that explains my pricing in simple words", category: "writing", text: "Write a clear blog post explaining why my [product or service] costs [price]. Break down what the customer gets, what is included, what costs extra, and why it is fair value compared with cheaper options. Use simple words and a calm, honest tone throughout." },
  { id: "writing-715", title: "Blog post for first-time buyers of my product", category: "writing", text: "Write a reassuring blog post for someone buying [product] for the first time from my shop in [city]. Explain what to look for, which option suits beginners, common mistakes to avoid, how to use it at home, and how to contact me if they need help after buying." },
  { id: "writing-716", title: "Blog post with a checklist for festival shopping", category: "writing", text: "Write a useful blog post with a simple checklist for festival shopping for [festival] in India. Cover planning a budget, choosing gifts, checking quality, ordering in time, and avoiding last-minute rush. Keep each point short, practical, and easy for a busy family to follow." },
  { id: "writing-717", title: "Blog post that busts a common myth about my product", category: "writing", text: "Write a blog post that gently corrects the myth that [myth about product or service]. Explain where the idea comes from, what is actually true, and give one clear example from everyday life in India. Keep the tone friendly, not argumentative, and end with a helpful tip." },
  { id: "writing-718", title: "Blog post for corporate gifting buyers before Diwali", category: "writing", text: "Write a blog post for companies in India planning Diwali gifts for staff and clients. Suggest gift options from my business [business name] at three budgets, explain bulk ordering and delivery, and give a simple last date to order. Keep the tone professional and practical for busy HR teams." },
  { id: "writing-719", title: "Blog post telling a real customer success story", category: "writing", text: "Write a blog post telling the story of my customer [customer first name] from [city] who used [product or service]. Describe their problem, what we suggested, what changed for them, and what they said afterwards, in their own simple words. Keep it honest and do not exaggerate the result." },
  { id: "writing-720", title: "Blog post introducing my team and how we work", category: "writing", text: "Write a warm blog post introducing the small team behind [business name]. Give each person a short role and one line about what they enjoy at work, explain how we work together, and how customers can reach the right person. Keep it friendly, simple, and human." },
  { id: "writing-721", title: "Blog post that explains how to care for my product at home", category: "writing", text: "Write a clear blog post explaining how to look after [product] at home so it lasts longer. Cover cleaning, storage, what to avoid, and how often to check it, using simple steps an Indian household can follow. Add a short note on when to bring it back to us for help." },
  { id: "writing-722", title: "Blog post for wholesale buyers and bulk orders", category: "writing", text: "Write a professional blog post for shop owners and wholesale buyers interested in [product] from [business name]. Explain minimum order quantity, bulk pricing, delivery time, payment terms, and how to place a first trial order. Keep the language clear and businesslike for new trade customers." },
  { id: "writing-723", title: "Blog post announcing a new branch or shop opening", category: "writing", text: "Write an excited blog post announcing our new branch of [business name] opening in [area, city] on [date]. Share the address, timings, opening offers, what customers will find there, and a warm invitation to visit. Keep the tone celebratory but clear and easy to read." },
  { id: "writing-724", title: "Blog post that answers festive season buying doubts", category: "writing", text: "Write a helpful blog post answering five common doubts customers have before buying [product] during the festive season. Cover price, delivery time, returns, gift packing, and stock availability in plain English. End with a simple line telling readers how to reach us quickly." },
  { id: "writing-725", title: "Blog post series plan in three connected parts", category: "writing", text: "Plan a three-part blog series for my business [business name] on the topic [topic]. Give each part a clear title, a one-line summary, three main points to cover, and how it leads into the next part. Keep the plan simple enough for a beginner to write one part each week." },
  { id: "writing-726", title: "Blog post that repurposes my most asked questions", category: "writing", text: "Turn my five most asked customer questions about [product or service] into one useful blog post. Write each question as a heading, answer it in two or three simple sentences, and add a short introduction and ending. Use the exact words customers use when they ask." },
  { id: "writing-727", title: "Blog post for monsoon season care and use tips", category: "writing", text: "Write a practical blog post with monsoon tips for using and storing [product] safely in India. Cover dampness, drying, storage, daily care, and one mistake to avoid during heavy rain. Keep the advice short, realistic for Indian homes, and easy to follow without special tools." },
  { id: "writing-728", title: "Blog post that explains a new rule or change for customers", category: "writing", text: "Write a polite blog post explaining a change at [business name], such as [change, for example new timings or delivery rule]. Explain why the change is needed, what stays the same, when it starts, and how customers can adjust. Keep the tone calm, clear, and respectful of regular customers." },
  { id: "writing-729", title: "Product description for a gift hamper", category: "writing", text: "Write a warm product description for a gift hamper from [business name] priced at [price]. List what is inside, who it suits, the packing, and the occasion it is best for, in simple words. End with how to order, delivery time in [city], and a note about a personal message card." },
  { id: "writing-730", title: "Product description for a combo pack of two items", category: "writing", text: "Write a clear product description for a combo pack of [item one] and [item two] from my shop. Explain why the two go well together, what the customer saves, who it suits, and how to use both. Keep it short, honest, and easy for a first-time buyer to understand." },
  { id: "writing-731", title: "Product description for a digital download guide", category: "writing", text: "Write a product description for my digital guide [guide title] that customers download after payment. Explain what is inside, how many pages it has, who it helps, how they will receive it, and that it works on a phone. Use simple words and avoid technical terms." },
  { id: "writing-732", title: "Product description for a monthly subscription box", category: "writing", text: "Write an inviting product description for my monthly subscription box from [business name] costing [price] per month. Explain what arrives each month, how customers can pause or cancel, delivery day, and who will enjoy it most. Keep the tone friendly and the terms very clear." },
  { id: "writing-733", title: "Product description for handmade jewellery", category: "writing", text: "Write a lovely product description for a handmade [jewellery item] made by [business name]. Describe the material, colour, size, how it is made, and which outfits it suits, in simple words. Add care tips and a note that each piece may vary slightly because it is handmade." },
  { id: "writing-734", title: "Product description for a cotton kurta", category: "writing", text: "Write a clear product description for a cotton kurta from my shop in [city]. Mention the fabric, fit, sizes available, colours, wash care, and best occasions to wear it. Keep the language simple, honest about the fabric, and helpful for a customer buying online without trying it on." },
  { id: "writing-735", title: "Product description for a spice mix pack", category: "writing", text: "Write a tasty product description for a [spice mix name] pack from [business name]. List the main ingredients, which dishes it suits, how much to use, shelf life, and storage tips. Mention that it has no added colour and is made in small batches in [city]." },
  { id: "writing-736", title: "Product description for a scented candle", category: "writing", text: "Write a calm product description for a scented candle from [business name] with the fragrance [fragrance]. Describe the smell, burn time, jar size, and where to use it at home. Add a simple safety note and a line about gifting it for festivals or housewarming." },
  { id: "writing-737", title: "Product description for a handmade notebook", category: "writing", text: "Write a warm product description for a handmade notebook from my shop. Mention the paper quality, number of pages, size, cover design, and who it suits, such as students, writers, or gift buyers. Add a note about personalising the cover with a name for a small extra charge." },
  { id: "writing-738", title: "Product description for a tiffin service weekly menu", category: "writing", text: "Write a clear product description for my weekly tiffin service in [city] costing [price] per week. List the menu for each day, what is included, delivery time, and that the food is vegetarian and home-style. Add how to start, pause for a holiday, and pay each week." },
  { id: "writing-739", title: "Product description for a beauty service package", category: "writing", text: "Write a clear product description for a beauty service package at [salon name] priced at [price]. List each service included, how long it takes, which skin or hair type it suits, and what to do before the appointment. Keep the tone welcoming and avoid promising results we cannot guarantee." },
  { id: "writing-740", title: "Product description for a workshop ticket", category: "writing", text: "Write a product description for a ticket to my workshop on [topic] on [date] in [city]. Explain what participants will learn, who should attend, what is included, the timing, the fee, and what to bring. End with a simple line on how to book a seat before it fills." },
  { id: "writing-741", title: "Product description for a limited edition festival item", category: "writing", text: "Write an exciting product description for a limited edition [item] made only for [festival]. Explain what makes it special, how many pieces are available, the price, and the last date to order. Keep the tone festive and honest, without pressuring the customer to buy quickly." },
  { id: "writing-742", title: "Product description for a premium product without sounding boastful", category: "writing", text: "Write a calm, confident product description for my premium [product] priced at [price]. Focus on the material, the work that goes into it, how long it lasts, and who it suits, without using boastful words. Let the details speak, and end with a simple invitation to see it in person." },
  { id: "writing-743", title: "Product description for a budget product that still feels trustworthy", category: "writing", text: "Write an honest product description for my budget-friendly [product] priced at [price]. Explain what it does well, what it does not include, who it is best for, and our return or exchange policy. Keep the tone respectful, so a price-conscious buyer feels confident, not talked down to." },
  { id: "writing-744", title: "Product description for an eco-friendly product", category: "writing", text: "Write a clear product description for my eco-friendly [product] from [business name]. Explain the material, how it can be reused or recycled, how to care for it, and why it is a better choice for the home. Avoid vague green claims and stick to facts I can honestly stand by." },
  { id: "writing-745", title: "Product description for a kids learning kit", category: "writing", text: "Write a friendly product description for a kids learning kit on [topic] for children aged [age range]. List what is inside, what the child will learn, how a parent can help, and the safety of the materials. Keep the language simple for parents and avoid promising exam results." },
  { id: "writing-746", title: "Product description for a bulk pack for offices", category: "writing", text: "Write a professional product description for a bulk pack of [product] meant for offices in India. Mention the quantity, per-unit price, packing, delivery time, and payment terms. Add a line about a free sample for first-time corporate buyers and how to request a quotation." },
  { id: "writing-747", title: "Landing page text for a free trial or demo", category: "writing", text: "Write landing page text inviting visitors to try a free demo of [service] from [business name]. Explain what they will see in the demo, how long it takes, that no payment is needed, and what happens after. Keep the headline clear and the call to action simple and friendly." },
  { id: "writing-748", title: "Landing page text for a new service launch", category: "writing", text: "Write landing page text for the launch of my new service [service name] in [city]. Explain the problem it solves, who it is for, what is included, the starting price, and how to book. Keep the page short, clear, and focused on one action for the visitor." },
  { id: "writing-749", title: "Homepage hero headline options for my business", category: "writing", text: "Give me five homepage headline options for my business [business name] in [city], which offers [service]. Each headline should be under ten words, clear about what we do, and warm rather than salesy. After the list, pick your favourite and explain in one line why it works best." },
  { id: "writing-750", title: "Services page introduction for three services", category: "writing", text: "Write a short introduction for the services page of [business name], which offers [service one], [service two], and [service three]. Explain in simple words who we help, how we work, and how to choose the right service. Keep it under 120 words and end with an invitation to contact us." },
  { id: "writing-751", title: "Pricing page introduction that builds trust", category: "writing", text: "Write a warm introduction for the pricing page of [business name]. Explain that prices are fixed and clear, what is included, what costs extra, and that there are no hidden charges. Add a reassuring line for customers who want a custom quotation for a bigger job." },
  { id: "writing-752", title: "Testimonials page introduction for my website", category: "writing", text: "Write a short introduction for the testimonials page of [business name]. Invite visitors to read what real customers from [city] have said, explain that the words are their own, and add a gentle line asking happy customers to share their experience with us too." },
  { id: "writing-753", title: "Contact page text that invites enquiries", category: "writing", text: "Write friendly text for the contact page of [business name] in [city]. Tell visitors the best way to reach us, our working hours, what details to share in their message, and how soon we usually reply. Keep it warm, short, and easy for a first-time visitor to act on." },
  { id: "writing-754", title: "Friendly text for a page that no longer exists", category: "writing", text: "Write friendly text for a page on my website that no longer exists, so visitors are not confused. Apologise briefly, explain in one line that the page has moved or closed, and guide them to the homepage, the shop, or the contact page. Keep the tone light and helpful, not technical." },
  { id: "writing-755", title: "Coming soon page text for a new shop", category: "writing", text: "Write short coming soon text for my new shop [shop name] opening in [area, city] in [month]. Tell visitors what we will sell, when we open, and how they can leave their WhatsApp number for an opening offer. Keep it exciting, simple, and under 80 words for a single page." },
  { id: "writing-756", title: "Thank-you page text after a customer sends an enquiry", category: "writing", text: "Write warm thank-you page text for a customer who has just sent an enquiry to [business name]. Confirm we received it, say when we will reply, suggest what they can look at while waiting, and give our WhatsApp number for urgent questions. Keep it short and reassuring." },
  { id: "writing-757", title: "Booking page introduction for appointments", category: "writing", text: "Write a clear introduction for the booking page of [business name] in [city]. Explain how to pick a date and time, what to bring, our cancellation rule, and how we confirm the booking. Keep the steps simple so even a first-time visitor can book without calling us." },
  { id: "writing-758", title: "Portfolio page introduction for my past work", category: "writing", text: "Write a short introduction for the portfolio page of [business name], showing past work for clients in [city]. Explain what visitors will see, the kinds of projects we take on, and how to ask for work like the examples shown. Keep the tone proud but modest and easy to read." },
  { id: "writing-759", title: "Short team member bios for my website", category: "writing", text: "Write three short team member bios for the website of [business name]. For each person, give their name, role, years of experience, and one line about what they enjoy at work. Keep each bio to two sentences, in plain English, with a warm and professional tone." },
  { id: "writing-760", title: "Careers page introduction for my business", category: "writing", text: "Write a welcoming introduction for the careers page of [business name] in [city]. Describe what it is like to work with us, the values we look for, and how to apply with a resume on WhatsApp or email. Keep it honest, friendly, and clear about the kind of people we want." },
  { id: "writing-761", title: "Franchise enquiry page text for my brand", category: "writing", text: "Write clear text for the franchise enquiry page of [brand name]. Explain who can apply, the investment range, the support we give, the cities we are looking at, and how to send an enquiry. Keep the language simple and businesslike, without promising earnings we cannot guarantee." },
  { id: "writing-762", title: "About the founder story for my website", category: "writing", text: "Write a simple founder story for the about page of [business name]. Tell how [founder name] started the business in [year] in [city], what problem they wanted to solve, one early challenge, and what the business stands for today. Keep it honest, warm, and under 150 words." },
  { id: "writing-763", title: "Mission and values statement for my business", category: "writing", text: "Write a short mission and values statement for [business name] in [city]. State what we do, who we serve, and three values we follow, such as honesty, quality, and on-time delivery. Use plain English that staff and customers can both understand and remember easily." },
  { id: "writing-764", title: "Checkout page reassurance text for nervous buyers", category: "writing", text: "Write short reassurance text for the checkout page of my online shop [shop name]. Tell buyers their payment is safe, what happens after they pay, our return policy in one line, and how to reach us if anything goes wrong. Keep it calm, clear, and under 80 words." },
  { id: "writing-765", title: "Monthly business newsletter for regular customers", category: "writing", text: "Write a friendly monthly newsletter for regular customers of [business name]. Include one piece of news, one useful tip, one product or offer, and a short thank-you note. Keep each section to two or three sentences, in plain English, with a warm tone that suits Indian families." },
  { id: "writing-766", title: "Product update newsletter for existing buyers", category: "writing", text: "Write a short newsletter telling existing buyers of [product] about an update or improvement we have made. Explain what changed, why it helps them, whether they need to do anything, and how to ask questions. Keep the tone helpful, not salesy, and under 150 words." },
  { id: "writing-767", title: "New stock alert newsletter for my shop", category: "writing", text: "Write an exciting newsletter announcing new stock of [product] at my shop [shop name] in [city]. Mention what has arrived, the price range, how long it may last, and the shop timings. End with a simple invitation to visit this week or message us to reserve a piece." },
  { id: "writing-768", title: "Customer story newsletter for the month", category: "writing", text: "Write a warm monthly newsletter sharing one real customer story from [business name]. Tell what the customer needed, how we helped, and what they said afterwards, in simple words. End by inviting readers to share their own story with us on WhatsApp." },
  { id: "writing-769", title: "Practical tips newsletter for my customers", category: "writing", text: "Write a useful newsletter for customers of [business name] with three practical tips about [topic]. Give each tip a short heading and two sentences of advice that works in an Indian home. End with a gentle line about our related product or service, without a hard sell." },
  { id: "writing-770", title: "Business newsletter for wholesale buyers", category: "writing", text: "Write a professional newsletter for wholesale buyers of [product] from [business name]. Share new stock, price updates, a bulk offer, and the last date to order for the month. Keep the language clear and businesslike, with all key details a shop owner needs in one place." },
  { id: "writing-771", title: "Re-engagement newsletter for inactive subscribers", category: "writing", text: "Write a gentle newsletter for subscribers of [business name] who have not opened our emails for a while. Remind them what we offer, share one useful update, and ask if they still want to hear from us. Keep the tone kind, with a simple way to stay or leave." },
  { id: "writing-772", title: "Newsletter announcing a change in shop timings", category: "writing", text: "Write a short newsletter telling customers of [shop name] in [city] about a change in our timings from [old timings] to [new timings] starting [date]. Explain the reason briefly, confirm what stays the same, and thank regular customers for understanding. Keep it polite and easy to read." },
  { id: "writing-773", title: "Event invitation newsletter for my customers", category: "writing", text: "Write a warm newsletter inviting customers of [business name] to our event [event name] on [date] at [place, city]. Explain what will happen, who should come, whether entry is free, and how to confirm a seat. End with a friendly line saying we would love to meet them in person." },
  { id: "writing-774", title: "Newsletter asking customers to take a short survey", category: "writing", text: "Write a short newsletter asking customers of [business name] to take a two-minute survey about [topic]. Explain why their answers matter, what we will do with the feedback, and that no personal details are needed. Add a polite thank-you and a simple link to the survey form." },
  { id: "writing-775", title: "Corporate gifting newsletter before Diwali", category: "writing", text: "Write a professional newsletter for companies planning Diwali gifts, from [business name]. Present three gift options at different budgets, explain bulk packing and delivery across India, and give the last date to order. Keep the tone helpful for busy HR and admin teams." },
  { id: "writing-776", title: "Year in review newsletter for my business", category: "writing", text: "Write a warm year in review newsletter for customers of [business name]. Share three highlights from the year, thank customers and staff, mention one lesson we learned, and give a small hint about what is coming next year. Keep the tone grateful, honest, and simple." },
  { id: "writing-777", title: "Newsletter announcing a new branch opening", category: "writing", text: "Write an exciting newsletter announcing the new branch of [business name] in [area, city] opening on [date]. Share the address, timings, opening offers, and a warm invitation to visit. Add a line asking readers to forward the news to friends and family nearby." },
  { id: "writing-778", title: "Referral programme newsletter for loyal customers", category: "writing", text: "Write a friendly newsletter explaining the referral programme of [business name]. Tell customers how to refer a friend, what both people receive, and any simple rules, in plain English. End with a thank-you to loyal customers and a simple line on how to start today." },
  { id: "writing-779", title: "Newsletter introducing a new team member", category: "writing", text: "Write a warm newsletter introducing a new team member [name] who has joined [business name] as [role]. Share what they will do, a little about their experience, and how customers can reach them. Keep the tone welcoming and end with a line inviting customers to say hello on their next visit." },
  { id: "writing-780", title: "Quotation for a bulk order with payment terms", category: "writing", text: "Write a clear quotation for a bulk order of [product] for [client name], quantity [quantity], at [price] per unit. Include the total, GST if it applies, delivery time, payment terms, and how long the quotation is valid. Use simple, professional language and a neat layout in words." },
  { id: "writing-781", title: "Follow-up message for a quotation I already sent", category: "writing", text: "Write a polite follow-up message to [client name] about the quotation I sent on [date] for [product or service]. Ask if they have any questions, offer to adjust the quantity or timing, and remind them the quotation is valid till [date]. Keep it short, helpful, and not pushy." },
  { id: "writing-782", title: "Revised quotation after a client asks for a lower price", category: "writing", text: "Write a revised quotation for [client name] who asked for a lower price on [product or service]. Show what changed, such as quantity or features, explain what stays the same, and give the new total clearly. Keep the tone respectful and firm, without sounding upset or desperate." },
  { id: "writing-783", title: "Quotation for annual maintenance of a service", category: "writing", text: "Write a quotation for annual maintenance of [service or equipment] for [client name] for one year. List what is covered, how many visits are included, response time, what is not covered, and the yearly fee with payment terms. Use clear, simple words a non-technical client can understand." },
  { id: "writing-784", title: "Proposal for a corporate event booking", category: "writing", text: "Write a professional proposal for a corporate event for [company name] on [date] at [venue, city]. Cover the venue setup, food, timing, number of guests, total cost, and what is included. End with the next step to confirm the booking and the last date to decide." },
  { id: "writing-785", title: "Proposal for wedding catering for a family", category: "writing", text: "Write a warm proposal for wedding catering for the family of [family name] in [city] for [number] guests on [date]. Suggest a vegetarian menu, service style, timings, and total cost with a separate line for any tax. End with an invitation to a tasting and a simple way to confirm." },
  { id: "writing-786", title: "Proposal for supplying uniforms to a school", category: "writing", text: "Write a clear proposal for supplying school uniforms to [school name] in [city] for [number] students. Cover fabric, sizes, sample approval, delivery schedule, per-piece price, and payment terms. Keep the language professional and easy for a school management committee to approve." },
  { id: "writing-787", title: "Proposal for a website design project", category: "writing", text: "Write a simple proposal for designing a website for [client business] in [city]. Explain the pages included, the timeline, the cost, what the client needs to provide, and one round of changes included. Use plain English, without technical jargon, so a non-technical owner can approve it confidently." },
  { id: "writing-788", title: "Proposal for a monthly social media retainer", category: "writing", text: "Write a proposal for managing social media for [client business] for one month at [price]. List the number of posts, what is included, what the client must approve, reporting, and payment terms. Keep the language clear and professional, with no promise of followers or sales we cannot guarantee." },
  { id: "writing-789", title: "Proposal for a franchise partnership", category: "writing", text: "Write a professional proposal inviting [person or company] to become a franchise partner of [brand name] in [city]. Explain the brand, investment range, support and training we give, and the expected steps to start. Keep the tone welcoming and avoid promising any fixed income or profit." },
  { id: "writing-790", title: "Proposal for a distributor partnership", category: "writing", text: "Write a clear proposal inviting [distributor name] to distribute [product] in [area]. Cover the product range, margins, minimum order, delivery support, and marketing help we provide. End with a simple next step, such as a meeting or a trial order, and our contact details." },
  { id: "writing-791", title: "Executive summary for a business proposal", category: "writing", text: "Write a one-page executive summary for my business proposal to [client name] about [project]. Summarise the problem, my solution, the main benefits, the timeline, and the total cost in simple words. Keep it short enough for a busy owner to read in two minutes and decide to read further." },
  { id: "writing-792", title: "Cover note for sending a business proposal", category: "writing", text: "Write a short cover note to send with my business proposal to [client name] for [project]. Thank them for their time, summarise the proposal in two lines, mention the total cost and validity, and invite them to a short call to discuss it. Keep it polite, professional, and under 120 words." },
  { id: "writing-793", title: "Proposal for a sponsorship or collaboration", category: "writing", text: "Write a proposal asking [company name] to sponsor or collaborate on [event or project] by [business name] in [city]. Explain the audience, what the sponsor gets, the cost, and how we will show their name. Keep the tone respectful and clear about what we offer in return." },
  { id: "writing-794", title: "Proposal for a staff training workshop", category: "writing", text: "Write a proposal for a staff training workshop on [topic] for [company name] in [city]. Cover the trainer, duration, number of staff, topics covered, materials given, and total fee. End with the next step to fix a date and a line on how the training will help daily work." },
  { id: "writing-795", title: "Resume for a fresher with no work experience", category: "writing", text: "Write a simple resume for a fresher named [name] from [city] who has just finished [course] and is looking for a first job in [field]. Highlight education, skills, projects, and any internship or volunteer work, in a clean order. Keep the language honest and do not invent any experience." },
  { id: "writing-796", title: "Resume for someone changing careers", category: "writing", text: "Write a resume for [name] from [city] who is changing careers from [old field] to [new field]. Highlight transferable skills, relevant courses, and achievements that suit the new role, and explain the change in one honest line. Keep the tone confident and the format clean and simple." },
  { id: "writing-797", title: "Resume skills section for an experienced worker", category: "writing", text: "Write a strong skills section for the resume of [name], who has [number] years of experience in [field]. List six to eight skills with a short example for each, using simple words that a hiring manager in India can quickly understand. Avoid vague words and keep every skill honest and specific." },
  { id: "writing-798", title: "Resume for a sales job in a shop", category: "writing", text: "Write a simple resume for [name] from [city] applying for a sales job in a shop selling [product]. Highlight customer handling, billing, stock work, and any targets met, with honest numbers where possible. Keep the format clean, the language simple, and the length to one page." },
  { id: "writing-799", title: "Resume for a delivery or driver job", category: "writing", text: "Write a clear resume for [name] from [city] applying for a delivery or driver job in [city]. Include driving licence details, areas known, past delivery or driving work, and phone number. Keep the language simple, honest, and easy for a small business owner to read quickly." },
  { id: "writing-800", title: "Cover letter for an internship application", category: "writing", text: "Write a polite cover letter from [name], a student of [course] at [college, city], applying for an internship at [company] in [field]. Explain why I want to learn there, what I can do, and my available dates. Keep it short, honest, and respectful, under 200 words." },
  { id: "writing-801", title: "Cover letter for a remote job application", category: "writing", text: "Write a cover letter from [name] in [city] applying for a remote job as [role] at [company]. Explain my experience, my home work setup, how I manage time, and why I can work well without an office. Keep the tone professional, confident, and simple for a hiring manager to read quickly." },
  { id: "writing-802", title: "Cover letter after a career break", category: "writing", text: "Write an honest cover letter from [name] returning to work after a career break of [number] years for [reason]. Explain what I did before, what I have learned recently, and why I am ready to work again as [role]. Keep the tone positive, confident, and free of unnecessary personal detail." },
  { id: "writing-803", title: "Cover letter for a part-time job", category: "writing", text: "Write a simple cover letter from [name] in [city] applying for a part-time job as [role] at [company]. Mention my available days and hours, relevant skills, and why the timings suit me. Keep it short, polite, and clear, so the employer can decide quickly without a long read." },
  { id: "writing-804", title: "LinkedIn headline options for my profile", category: "writing", text: "Give me five LinkedIn headline options for my profile as a [role] in [city] who helps [type of customers] with [service]. Each headline should be under 12 words, clear about what I do, and professional without buzzwords. After the list, pick your favourite and explain in one line why it stands out." },
  { id: "writing-805", title: "LinkedIn About section for a freelancer", category: "writing", text: "Write a LinkedIn About section for me, a freelancer in [city] offering [service] to small businesses in India. Explain who I help, what I do, my experience in simple words, and how to contact me for work. Keep it friendly, professional, and under 150 words." },
  { id: "writing-806", title: "LinkedIn About section for a small shop owner", category: "writing", text: "Write a LinkedIn About section for me, the owner of [shop name] in [city] selling [product]. Share what my shop offers, who our customers are, what makes us different, and how to visit or order. Keep it warm, honest, and simple, without sounding like an advertisement." },
  { id: "writing-807", title: "LinkedIn post announcing my new business", category: "writing", text: "Write a LinkedIn post announcing the launch of my new business [business name] in [city], offering [service]. Share why I started it, who it helps, and a warm invitation to visit, share, or send an enquiry. Keep the tone proud but humble, and end with one clear question for readers." },
  { id: "writing-808", title: "LinkedIn post announcing a new job", category: "writing", text: "Write a warm LinkedIn post announcing that I, [name], have joined [company] in [city] as [role]. Thank my previous team briefly, share what I look forward to in the new role, and invite connections to reach out. Keep it short, grateful, and professional, under 150 words." },
  { id: "writing-809", title: "Request for a LinkedIn recommendation from a former manager", category: "writing", text: "Write a polite message asking my former manager [manager name] for a short LinkedIn recommendation about my work as [role] at [company]. Remind them of one project we worked on, say what the recommendation would help me with, and make it easy for them to say yes or no. Keep it respectful and brief." },
  { id: "writing-810", title: "Job post for a shop assistant", category: "writing", text: "Write a clear job post for a shop assistant at [shop name] in [city]. Mention the work, timings, salary range, experience needed, and how to apply on WhatsApp. Use simple words, a friendly tone, and honest details, so the right person can decide quickly without calling for basic information." },
  { id: "writing-811", title: "Job post for a delivery rider", category: "writing", text: "Write a simple job post for a delivery rider for [business name] in [city]. Mention the delivery area, timings, pay, fuel or vehicle support, licence needed, and how to apply. Keep the language clear and honest, with all key details a rider needs before applying." },
  { id: "writing-812", title: "Job post for an accountant for my business", category: "writing", text: "Write a professional job post for an accountant at [business name] in [city]. List the main work, such as billing, GST filing support, and records, plus experience needed, timings, salary range, and how to apply. Keep it clear, respectful, and free of jargon a small business owner would not use." },
  { id: "writing-813", title: "Job post for a beautician in my salon", category: "writing", text: "Write a warm job post for a beautician at [salon name] in [city]. Mention the services needed, experience, timings, salary, and how to apply with a short message. Add a line about a friendly work atmosphere and training support, and keep the whole post simple and welcoming." },
  { id: "writing-814", title: "Job post for a driver for my business", category: "writing", text: "Write a clear job post for a driver for [business name] in [city]. Mention the vehicle type, routes, timings, salary, licence needed, and how to apply. Keep the language simple and honest, with the main details upfront so drivers can decide quickly without extra calls." },
  { id: "writing-815", title: "Job post for an intern in my office", category: "writing", text: "Write a friendly job post for an intern at [business name] in [city] to help with [work]. Mention the duration, stipend if any, timings, skills to learn, and how students can apply. Keep it honest about the work, so a student knows exactly what to expect." },
  { id: "writing-816", title: "Job post for a sales executive", category: "writing", text: "Write a clear job post for a sales executive at [business name] in [city] selling [product]. Mention the target customers, travel if needed, salary and incentive structure, experience needed, and how to apply. Keep the tone professional and honest about targets, without promising unrealistic earnings." },
  { id: "writing-817", title: "Short job ad for a WhatsApp group", category: "writing", text: "Write a short job ad for a WhatsApp group for the role of [role] at [business name] in [city]. Include the work in one line, timings, salary range, location, and a WhatsApp number to apply. Keep it under 80 words, easy to read on a phone, and free of unnecessary detail." },
  { id: "writing-818", title: "Interview invitation message for a candidate", category: "writing", text: "Write a polite interview invitation message to [candidate name] for the role of [role] at [business name] in [city]. Mention the date, time, place or video link, what to bring, and whom to ask for on arrival. Keep it warm, clear, and short, with a line asking them to confirm." },
  { id: "writing-819", title: "Polite rejection message for a job applicant", category: "writing", text: "Write a kind rejection message to [candidate name] who applied for [role] at [business name]. Thank them for their time, say the role is filled, wish them well, and offer to keep their resume for a future opening if they agree. Keep the tone respectful and human, not like a form letter." },
  { id: "writing-820", title: "Offer letter in simple words for a new hire", category: "writing", text: "Write a simple offer letter for [candidate name] joining [business name] in [city] as [role] from [joining date]. Mention salary, timings, probation period, and the last date to accept, in plain English. Keep the tone welcoming and the terms clear, so a first-time employee can understand it easily." },
  { id: "writing-821", title: "Joining instructions for a new employee", category: "writing", text: "Write clear joining instructions for a new employee [name] joining [business name] in [city] on [date]. Tell them the reporting time, whom to meet, what documents to bring, dress code, and lunch timing. Keep the message warm, simple, and complete, so they arrive confident on day one." },
  { id: "writing-822", title: "Job post for a cook in my catering business", category: "writing", text: "Write a clear job post for a cook in my catering business [business name] in [city]. Mention the cuisine, number of people served, timings, salary, experience needed, and how to apply. Keep the language simple and respectful, with all key details a cook needs before applying." },
  { id: "writing-823", title: "Job post for a tailor in my boutique", category: "writing", text: "Write a warm job post for a tailor at my boutique [boutique name] in [city]. Mention the work, such as stitching [garment type], experience needed, timings, salary, and how to apply. Add a line about steady work and a friendly shop, and keep the post simple and welcoming." },
  { id: "writing-824", title: "Job post for a receptionist for my clinic", category: "writing", text: "Write a professional job post for a receptionist at my clinic [clinic name] in [city]. Mention the work, such as greeting patients and managing appointments, timings, salary, and how to apply. Keep the language clear, polite, and honest about the hours and the skills needed." },
  { id: "writing-825", title: "Minutes for a client meeting with clear actions", category: "writing", text: "Turn my rough notes from a client meeting with [client name] on [date] about [topic] into clear minutes. List who attended, what was discussed, decisions taken, and action points with the person responsible and a due date for each. Keep the format neat and easy to share on WhatsApp or email." },
  { id: "writing-826", title: "Minutes for a weekly team meeting", category: "writing", text: "Turn my notes from our weekly team meeting on [date] at [business name] into short minutes. Summarise updates from each person, decisions made, pending work, and action points with owners and dates. Keep it to one page, in simple words, so everyone knows what to do next." },
  { id: "writing-827", title: "Minutes for a supplier meeting", category: "writing", text: "Turn my notes from a meeting with supplier [supplier name] on [date] about [product] into clear minutes. Record prices discussed, quantity, delivery dates, payment terms, and what each side agreed to do next. Keep the language factual and simple, so the record is useful if we need to check it later." },
  { id: "writing-828", title: "Meeting agenda draft for a project discussion", category: "writing", text: "Draft a simple meeting agenda for a project discussion about [project] at [business name] on [date] at [time]. List four or five points to discuss, who will speak on each, and how much time to give it. End with a line for any other business and the next meeting date." },
  { id: "writing-829", title: "Follow-up email after a business meeting", category: "writing", text: "Write a polite follow-up email to [person name] after our meeting on [date] about [topic]. Thank them for their time, summarise the three main points we agreed on, list the next steps with dates, and ask them to confirm. Keep it short, professional, and easy to reply to." },
  { id: "writing-830", title: "Meeting summary for a colleague who was absent", category: "writing", text: "Write a short meeting summary for my colleague [name] who missed our meeting on [date] about [topic]. Explain the main decisions, what changed, and what they need to do before the next meeting on [date]. Keep it clear and friendly, so they can catch up in two minutes." },
  { id: "writing-831", title: "Decision note after a meeting with a partner", category: "writing", text: "Write a clear decision note after my meeting with my business partner [name] on [date] about [topic]. Record what we decided, why we chose it, what we rejected, who will do what, and by when. Keep the note short, factual, and easy to refer back to later." },
  { id: "writing-832", title: "Brainstorming notes summary for my team", category: "writing", text: "Turn my rough brainstorming notes on [topic] for [business name] into a clean summary for the team. Group the ideas into three themes, pick the three most practical ideas, and list a small next step for each. Keep the language simple and encouraging, so the team feels heard." },
  { id: "writing-833", title: "Notes for a project kickoff meeting", category: "writing", text: "Write clear notes for the kickoff meeting of my project [project name] on [date] with [team or client]. Cover the goal, main tasks, who does what, key dates, and how we will share updates. Keep the format simple, so everyone leaves the meeting knowing their first task." },
  { id: "writing-834", title: "Weekly review meeting notes for my business", category: "writing", text: "Turn my notes from our weekly review meeting on [date] at [business name] into a short summary. Cover what went well, what needs fixing, sales or work done this week, and three priorities for next week. Keep it honest, simple, and useful for the whole team to read." },
  { id: "writing-835", title: "Press note for a new shop opening", category: "writing", text: "Write a press note announcing the opening of my new shop [shop name] in [area, city] on [date]. Include what we sell, the opening offer, timings, a short quote from me as the owner, and contact details. Keep it factual, simple, and ready to share with a local newspaper." },
  { id: "writing-836", title: "Press note for winning a local business award", category: "writing", text: "Write a press note announcing that [business name] in [city] has won [award name] for [reason]. Explain what the award is, why we received it, thank our customers and team, and add a short quote from me. Keep the tone proud but modest, and the facts simple and true." },
  { id: "writing-837", title: "Press note for launching a new product", category: "writing", text: "Write a press note announcing the launch of my new product [product name] by [business name] in [city]. Explain what it is, who it helps, the price, where to buy it, and one line about why we made it. Keep it short, factual, and easy for a local reporter to use." },
  { id: "writing-838", title: "Press note for expanding to a new city", category: "writing", text: "Write a press note announcing that [business name] is expanding to [new city] in [month]. Explain what we offer, why we chose this city, when services start, and how customers there can reach us. Add a short quote from me and keep the whole note clear and professional." },
  { id: "writing-839", title: "Press note for a partnership with another business", category: "writing", text: "Write a press note announcing a partnership between [my business] and [partner business] in [city]. Explain what each business does, what customers will gain from working together, and when the partnership starts. Keep it factual, positive, and simple, with contact details for both businesses." },
  { id: "writing-840", title: "Slogan options for my bakery", category: "writing", text: "Give me five slogan options for my bakery [bakery name] in [city], known for [speciality, for example fresh bread or eggless cakes]. Each slogan should be under eight words, warm, and easy to remember. After the list, pick your favourite and explain in one line why customers will remember it." },
  { id: "writing-841", title: "Slogan options for my boutique", category: "writing", text: "Give me five slogan options for my boutique [boutique name] in [city], which sells [garments]. Each slogan should be under eight words, elegant, and easy to remember. After the list, pick your favourite and explain in one line why it suits the shop and its customers." },
  { id: "writing-842", title: "Tagline options for my travel business", category: "writing", text: "Give me five tagline options for my travel business [business name] in [city], which plans [type of trips]. Each tagline should be under eight words, warm, and clear about comfortable, honest travel. After the list, pick your favourite and explain in one line why it builds trust." },
  { id: "writing-843", title: "Slogan options for my fitness studio", category: "writing", text: "Give me five slogan options for my fitness studio [studio name] in [city], which offers [classes]. Each slogan should be under eight words, encouraging, and easy to remember. After the list, pick your favourite and explain in one line why it will motivate beginners to join." },
  { id: "writing-844", title: "Tagline options for a new brand launch", category: "writing", text: "Give me five tagline options for my new brand [brand name], which sells [product] to customers in India. Each tagline should be under eight words, clear about what the brand stands for, and easy to remember. After the list, pick your favourite and explain in one line why it works." },
  { id: "writing-845", title: "WhatsApp message for a festival offer to customers", category: "writing", text: "Write a short WhatsApp message for customers of [business name] about our festival offer for [festival]. Mention the offer, the dates, the shop timings, and how to order or visit. Keep it warm, under 80 words, and easy to read on a phone, with no pressure to buy." },
  { id: "writing-846", title: "Message suggesting an alternative when a product is out of stock", category: "writing", text: "Write a polite message to a customer telling them [product] is out of stock at [business name], and suggesting a similar product [alternative] at [price]. Explain the difference honestly, say when the original may return, and let them choose without pressure. Keep the tone helpful and respectful." },
  { id: "writing-847", title: "Polite payment reminder message for a customer", category: "writing", text: "Write a polite payment reminder message to [customer name] about an unpaid bill of [amount] for [product or service] from [business name], due on [date]. Remind them gently, share the payment details, and thank them in advance. Keep the tone friendly, so a regular customer does not feel embarrassed." },
  { id: "writing-848", title: "Firm but polite message for an overdue payment", category: "writing", text: "Write a firm but polite message to [customer name] about a payment of [amount] for [product or service] that is overdue since [date]. State the amount, ask for payment by [new date], and explain the next step if it is delayed further. Keep the tone respectful and professional, without threats." },
  { id: "writing-849", title: "Subscription renewal reminder for a customer", category: "writing", text: "Write a friendly reminder message to [customer name] that their subscription to [service] from [business name] renews on [date] at [price]. Explain what continues, how to change or cancel, and how to pay. Keep it clear, short, and helpful, so the customer can act in one minute." },
  { id: "writing-850", title: "Loyalty reward message for a repeat customer", category: "writing", text: "Write a warm message thanking [customer name], a repeat customer of [business name], and offering a loyalty reward of [reward] on their next visit before [date]. Explain how to claim it simply, without extra steps. Keep the tone grateful and personal, so the customer feels valued, not sold to." },
  { id: "writing-851", title: "Message acknowledging a customer complaint", category: "writing", text: "Write a calm message acknowledging a complaint from [customer name] about [issue] with [product or service] from [business name]. Apologise briefly, say what we are checking, give a time by which we will reply, and thank them for telling us. Keep the tone sincere and respectful throughout." },
  { id: "writing-852", title: "Message telling a customer their refund has been processed", category: "writing", text: "Write a clear message telling [customer name] that their refund of [amount] for [product or service] from [business name] has been processed on [date]. Explain when it should reach their bank, what to do if it does not, and thank them for their patience. Keep the tone reassuring and simple." },
  { id: "writing-853", title: "Follow-up message for a customer who enquired but did not buy", category: "writing", text: "Write a gentle follow-up message to [customer name] who enquired about [product or service] on [date] but has not bought yet. Ask if they have any questions, offer one helpful detail, and remind them the offer or stock is available till [date]. Keep it short, friendly, and not pushy." },
  { id: "writing-854", title: "Feedback form for a restaurant visit", category: "writing", text: "Write a short feedback form for customers of my restaurant [restaurant name] in [city]. Include questions on food taste, service, cleanliness, value for money, and one open question for suggestions, using simple words. Add a short introduction thanking them and saying the form takes two minutes." },
  { id: "writing-855", title: "Feedback form for a training workshop I conducted", category: "writing", text: "Write a short feedback form for participants of my training workshop on [topic] held on [date] in [city]. Ask about the content, the trainer, the pace, what was most useful, and what to improve, in simple words. Add a thank-you line and a question asking if they want future workshops." },
  { id: "writing-856", title: "Invitation to a housewarming lunch", category: "writing", text: "Write a warm, simple invitation for a housewarming lunch at [your home] on [date] at [time], inviting [names] for lunch, a short house tour and blessings, with a note that Jain food will be served and parking is at [place]." },
  { id: "writing-857", title: "Griha pravesh invitation for close family", category: "writing", text: "Write a respectful griha pravesh invitation for close family, giving the pooja time [time], the address [address], and lunch after the ceremony, asking elders to bless the new home and mentioning that simple vegetarian food will be served." },
  { id: "writing-858", title: "Baby shower invitation for a sister", category: "writing", text: "Write a cheerful baby shower invitation for my sister [name] on [date] at [venue], inviting [guests] for games, gifts, blessings and lunch, with a sweet note asking guests to wear yellow and to bring one blessing for the baby." },
  { id: "writing-859", title: "First birthday invitation for my daughter", category: "writing", text: "Write a cute first birthday invitation for my daughter [name] on [date] at [venue] from [time], inviting family and friends for cake, games and lunch, and asking guests to come in bright colours for photos with the birthday girl." },
  { id: "writing-860", title: "Thread ceremony invitation for my son", category: "writing", text: "Write a traditional thread ceremony invitation for my son [name] on [date] at [venue], explaining the morning ceremony time [time], lunch afterwards, and a kind request for elders to bless him as he begins this new stage." },
  { id: "writing-861", title: "Haldi ceremony invitation for cousins", category: "writing", text: "Write a fun haldi ceremony invitation for cousins on [date] at [home] from [time], inviting everyone to wear yellow, join the turmeric ritual, sing songs, and stay for snacks, with a note to bring an old towel." },
  { id: "writing-862", title: "Mehndi evening invitation for neighbours", category: "writing", text: "Write a warm mehndi evening invitation for neighbours on [date] at [venue] from [time], inviting ladies to get henna applied, enjoy music and snacks, and celebrate [bride name] before her wedding with simple, joyful words." },
  { id: "writing-863", title: "Sangeet night invitation for family friends", category: "writing", text: "Write a lively sangeet night invitation for family friends on [date] at [venue] from [time], inviting everyone to sing, dance and cheer for [couple names], with dinner after the performances and a request to wear festive clothes." },
  { id: "writing-864", title: "Retirement party invitation for my father", category: "writing", text: "Write a heartfelt retirement party invitation for my father [name] on [date] at [venue] from [time], inviting relatives and friends to honour his [number] years of work, share memories, enjoy dinner, and bless him for a happy retired life." },
  { id: "writing-865", title: "Farewell lunch invitation for our society secretary", category: "writing", text: "Write a polite farewell lunch invitation for our housing society secretary [name] on [date] at [venue] from [time], thanking him for his service, inviting all flat owners to join lunch, and asking everyone to share one short memory." },
  { id: "writing-866", title: "School reunion invitation after ten years", category: "writing", text: "Write a warm school reunion invitation for our batch of [year] on [date] at [venue] from [time], inviting old classmates to meet teachers, share memories, enjoy lunch, and confirm attendance by [date] on [phone number]." },
  { id: "writing-867", title: "Kitty party invitation for a festive lunch", category: "writing", text: "Write a cheerful kitty party invitation for a festive lunch on [date] at [host name] home from [time], with the theme [theme], a small game, lunch, and a request to bring [item] and confirm by [date]." },
  { id: "writing-868", title: "Terrace potluck invitation for flat owners", category: "writing", text: "Write a friendly terrace potluck invitation for flat owners on [date] at [time] on the terrace, asking each family to bring one vegetarian dish, listing the dishes already planned, and promising music, games and a shared dinner under the stars." },
  { id: "writing-869", title: "Satyanarayan katha invitation for neighbours", category: "writing", text: "Write a devotional Satyanarayan katha invitation for neighbours on [date] at [home] from [time], giving the katha and aarti timings, inviting families for prasad and dinner, and asking guests to arrive ten minutes early." },
  { id: "writing-870", title: "Ganpati visarjan procession invitation", category: "writing", text: "Write a joyful Ganpati visarjan procession invitation for [date] at [time], starting from [address], inviting neighbours to join the walk to [place], sing together, and return for prasad, with a note to wear comfortable shoes." },
  { id: "writing-871", title: "Birthday wishes for twin sisters", category: "writing", text: "Write a sweet birthday message for twin sisters [names] turning [age], celebrating how different and yet close they are, wishing them health, laughter and success, and ending with love from [your name] and family." },
  { id: "writing-872", title: "Sixtieth birthday wishes for my uncle", category: "writing", text: "Write a respectful sixtieth birthday message for my uncle [name], thanking him for his guidance and kindness, wishing him good health and many happy years with family, and mentioning one fond memory from [occasion]." },
  { id: "writing-873", title: "Fiftieth birthday wishes for my mother-in-law", category: "writing", text: "Write a warm fiftieth birthday message for my mother-in-law [name], thanking her for her love, cooking and care for our family, wishing her health and happiness, and promising a small celebration at [place]." },
  { id: "writing-874", title: "First birthday wishes for a baby boy", category: "writing", text: "Write a loving first birthday message for a baby boy [name], wishing him a healthy, happy life, praising his first steps and smile, and sending blessings and love to his parents [names] on this special day." },
  { id: "writing-875", title: "Birthday wishes for a childhood friend abroad", category: "writing", text: "Write a warm birthday message for my childhood friend [name] who now lives in [country], recalling our school days in [town], wishing him health and success far from home, and saying I miss our evening chats." },
  { id: "writing-876", title: "Onam wishes for a Malayali neighbour", category: "writing", text: "Write a cheerful Onam message for my Malayali neighbour [name], wishing her family a happy Onam, mentioning the pookkalam, sadya and new clothes, and thanking her for sharing payasam with us last year." },
  { id: "writing-877", title: "Navratri wishes for a fasting friend", category: "writing", text: "Write a kind Navratri message for my friend [name] who is fasting, wishing her strength and peace during the nine days, praising her devotion, and inviting her for a simple fruit prasad after the evening aarti." },
  { id: "writing-878", title: "Karva Chauth wishes for my sister-in-law", category: "writing", text: "Write a loving Karva Chauth message for my sister-in-law [name], wishing her a happy fast, good health for her husband, and a beautiful evening with mehndi, moon sighting and a family dinner together." },
  { id: "writing-879", title: "Bhai Dooj wishes for my younger brother", category: "writing", text: "Write a sweet Bhai Dooj message for my younger brother [name], thanking him for always protecting me, wishing him success in his studies, and promising his favourite sweets and a small gift this year." },
  { id: "writing-880", title: "Lohri wishes for a Punjabi family", category: "writing", text: "Write a warm Lohri message for a Punjabi family [family name], wishing them joy around the bonfire, mentioning popcorn, peanuts and rewari, and thanking them for inviting us to their celebration last year." },
  { id: "writing-881", title: "Makar Sankranti wishes for my grandfather", category: "writing", text: "Write a respectful Makar Sankranti message for my grandfather [name], wishing him health and happiness, recalling how he taught me to fly kites, and promising to visit him with til ladoo this year." },
  { id: "writing-882", title: "Holi wishes for a college friend", category: "writing", text: "Write a colourful Holi message for my college friend [name], wishing her a safe and joyful Holi, recalling our hostel celebrations, and asking her to play with natural colours and enjoy gujiya with family." },
  { id: "writing-883", title: "Janmashtami wishes for a Krishna devotee friend", category: "writing", text: "Write a devotional Janmashtami message for my friend [name], wishing her a blessed Krishna Janmashtami, mentioning midnight prayers, butter and flute, and inviting her family for prasad at our home." },
  { id: "writing-884", title: "Ganesh Chaturthi wishes for my building", category: "writing", text: "Write a joyful Ganesh Chaturthi message for all families in my building, wishing everyone blessings from Lord Ganesha, inviting them to the evening aarti at [time], and asking each flat to bring one modak for prasad." },
  { id: "writing-885", title: "Durga Puja wishes for a Bengali neighbour", category: "writing", text: "Write a warm Durga Puja message for my Bengali neighbour [name], wishing her family a happy Puja, mentioning the pandal, dhak drums and new saree, and asking about the best day to visit the pandal together." },
  { id: "writing-886", title: "Ram Navami wishes for my temple group", category: "writing", text: "Write a devotional Ram Navami message for my temple group, wishing everyone blessings from Lord Rama, giving the morning bhajan time [time] at [temple], and inviting families for prasad after the prayers." },
  { id: "writing-887", title: "Guru Nanak Jayanti wishes for a Sikh friend", category: "writing", text: "Write a respectful Guru Nanak Jayanti message for my Sikh friend [name], wishing his family peace and blessings, recalling Guru Nanak teachings on kindness and honest work, and thanking him for langar last year." },
  { id: "writing-888", title: "Mahavir Jayanti wishes for a Jain relative", category: "writing", text: "Write a peaceful Mahavir Jayanti message for my Jain relative [name], wishing her family blessings, recalling Lord Mahavir teachings on ahimsa and compassion, and inviting her to the temple programme at [time]." },
  { id: "writing-889", title: "Buddha Purnima wishes for a meditation friend", category: "writing", text: "Write a calm Buddha Purnima message for my meditation friend [name], wishing her peace and clarity, recalling the Buddha teachings on kindness and patience, and inviting her for a quiet morning walk and tea." },
  { id: "writing-890", title: "Diary entry about a monsoon evening at home", category: "writing", text: "Write a diary entry about a monsoon evening at home, describing the rain on the window, hot chai, the smell of wet earth, a phone call from [person], and how this quiet evening made me feel calm and grateful." },
  { id: "writing-891", title: "Diary entry about my first train journey alone", category: "writing", text: "Write a diary entry about my first train journey alone from [place] to [place], describing the window view, the food I carried, a kind co-passenger, my nervousness at first, and the confidence I felt on reaching home." },
  { id: "writing-892", title: "Diary entry about learning to cook dal", category: "writing", text: "Write a diary entry about learning to cook dal with my mother, describing the tadka, my mistakes, her patient guidance, the taste of the first bowl, and what this small lesson taught me about home and care." },
  { id: "writing-893", title: "Diary entry about a walk in my grandmother's garden", category: "writing", text: "Write a diary entry about a walk in my grandmother's garden, describing the tulsi plant, jasmine flowers, her stories about each plant, the birdsong, and why this garden feels like the safest place in the world." },
  { id: "writing-894", title: "Diary entry about moving into a new flat", category: "writing", text: "Write a diary entry about moving into a new flat in [area], describing the empty rooms, unpacking boxes, the first meal cooked there, the neighbours who helped, and my hopes for this new chapter of life." },
  { id: "writing-895", title: "Diary entry about my first salary day", category: "writing", text: "Write a diary entry about my first salary day, describing how I checked my bank message, bought sweets for my parents, saved [amount] for the future, and felt proud, grateful and a little nervous about adult life." },
  { id: "writing-896", title: "Diary entry about a festival morning with family", category: "writing", text: "Write a diary entry about a festival morning with family on [festival], describing the early bath, new clothes, rangoli at the door, prayers together, festive breakfast, and the joy of everyone being under one roof." },
  { id: "writing-897", title: "Diary entry about a quiet Sunday with a book", category: "writing", text: "Write a diary entry about a quiet Sunday spent with the book [title], describing my favourite corner at home, the tea I made, one line that stayed with me, and why I want more slow Sundays like this." },
  { id: "writing-898", title: "Diary entry about meeting an old friend by chance", category: "writing", text: "Write a diary entry about meeting my old friend [name] by chance at [place], describing our surprise, the memories we recalled, the chai we shared, and how the meeting reminded me to stay in touch more often." },
  { id: "writing-899", title: "Diary entry about my child's first bicycle ride", category: "writing", text: "Write a diary entry about my child [name] first bicycle ride in our lane, describing the wobble, my running behind, the fall and the laughter, and the proud moment when she finally rode alone for ten metres." },
  { id: "writing-900", title: "Journal entry about three things I am grateful for today", category: "writing", text: "Write a journal entry listing three things I am grateful for today: [thing one], [thing two] and [thing three], explaining in one or two lines why each one mattered, and ending with a hopeful thought for tomorrow." },
  { id: "writing-901", title: "Journal entry about a small kindness I received", category: "writing", text: "Write a journal entry about a small kindness I received from [person] today, describing what they did, how it changed my mood, why I will remember it, and one kind thing I want to do for someone else this week." },
  { id: "writing-902", title: "Journal entry about a habit I want to build", category: "writing", text: "Write a journal entry about the habit I want to build, [habit], explaining why it matters to me, the small daily step I will take, the time [time] I will do it, and how I will track it for thirty days." },
  { id: "writing-903", title: "Journal entry about a worry I want to let go", category: "writing", text: "Write a gentle journal entry about a worry I want to let go, [worry], describing how it feels, what is in my control and what is not, and one small, practical step I can take tomorrow to feel lighter." },
  { id: "writing-904", title: "Journal entry about a place that feels like home", category: "writing", text: "Write a journal entry about a place that feels like home, [place], describing its sounds, smells and people, one memory that happened there, and why I feel calm and safe whenever I return to it." },
  { id: "writing-905", title: "Condolence message for a neighbour who lost her mother", category: "writing", text: "Write a gentle condolence message for my neighbour [name] who lost her mother, expressing sorrow, recalling her mother kindness, offering help with food and daily chores, and saying I am just a door away." },
  { id: "writing-906", title: "Condolence message for a friend who lost his father", category: "writing", text: "Write a sincere condolence message for my friend [name] who lost his father, sharing my sadness, praising his father guidance and values, and offering to help his family in any way during this difficult time." },
  { id: "writing-907", title: "Condolence message for the loss of a pet dog", category: "writing", text: "Write a kind condolence message for my friend [name] who lost her pet dog [dog name], recalling the dog loyalty and playful nature, acknowledging how deep this loss feels, and offering comfort and a listening ear." },
  { id: "writing-908", title: "Condolence note for a teacher who lost her husband", category: "writing", text: "Write a respectful condolence note for my teacher [name] who lost her husband, expressing sorrow, thanking her for her guidance to students, and offering prayers and support for her family in the coming weeks." },
  { id: "writing-909", title: "Condolence message for a shopkeeper's family", category: "writing", text: "Write a respectful condolence message for the family of our local shopkeeper [name], remembering his honest service and friendly smile, expressing sorrow at his passing, and offering help to his family and shop." },
  { id: "writing-910", title: "Congratulations for a cousin who cleared CA exams", category: "writing", text: "Write a proud congratulations message for my cousin [name] who cleared the CA exams, praising her hard work and late-night study, wishing her a bright career, and promising a family celebration at [place] soon." },
  { id: "writing-911", title: "Congratulations for a friend who bought a new home", category: "writing", text: "Write a happy congratulations message for my friend [name] who bought a new home in [area], wishing her family comfort and joy in the new house, and promising to visit soon with a small housewarming gift." },
  { id: "writing-912", title: "Congratulations for a sister who got her driving licence", category: "writing", text: "Write a cheerful congratulations message for my sister [name] who got her driving licence, praising her practice and patience, wishing her safe drives, and joking gently that I will be her first passenger." },
  { id: "writing-913", title: "Congratulations for a nephew who won a cricket trophy", category: "writing", text: "Write an excited congratulations message for my nephew [name] who won a cricket trophy, praising his batting and teamwork, recalling his early practice in our lane, and wishing him many more wins ahead." },
  { id: "writing-914", title: "Congratulations for parents on their silver anniversary", category: "writing", text: "Write a loving silver anniversary message for my parents, thanking them for twenty-five years of love, patience and sacrifice, recalling one family memory, and wishing them health and many more happy years together." },
  { id: "writing-915", title: "Congratulations for a friend on twins", category: "writing", text: "Write a joyful congratulations message for my friend [name] on the birth of twins [names], wishing the babies health and happiness, praising the new parents, and offering help with meals and visits in the first month." },
  { id: "writing-916", title: "Congratulations for a brother on his first job", category: "writing", text: "Write a proud congratulations message for my brother [name] on his first job at [company], praising his hard work and honesty, wishing him success and good colleagues, and asking him to treat the family to sweets." },
  { id: "writing-917", title: "Congratulations for a niece on her dance performance", category: "writing", text: "Write a sweet congratulations message for my niece [name] on her dance performance at [event], praising her grace, practice and confidence on stage, and telling her how proud the whole family felt watching her." },
  { id: "writing-918", title: "Congratulations for a neighbour on opening a small shop", category: "writing", text: "Write a warm congratulations message for my neighbour [name] on opening a small shop at [place], wishing him honest customers and steady growth, and promising to visit on the opening day with my family." },
  { id: "writing-919", title: "Housing society notice about lift repair timings", category: "writing", text: "Write a clear housing society notice saying the lift in [block] will be under repair on [date] from [time] to [time], asking residents to use the stairs, avoid heavy loads, and contact [name] on [phone] for urgent help." },
  { id: "writing-920", title: "Housing society notice about water tank cleaning", category: "writing", text: "Write a clear housing society notice about water tank cleaning on [date] from [time], saying water supply will stop for [hours], asking residents to store water in advance, and thanking them for their cooperation." },
  { id: "writing-921", title: "Housing society notice about Diwali decoration rules", category: "writing", text: "Write a polite housing society notice about Diwali decoration rules, asking residents to keep corridors clear, use safe lights, avoid firecrackers near cars, and remove decorations by [date] after the festival." },
  { id: "writing-922", title: "Housing society notice about guest parking for a wedding", category: "writing", text: "Write a helpful housing society notice about guest parking for a wedding in flat [number] on [date], giving the guest parking area [place], the timings [time], and a request to inform the watchman in advance." },
  { id: "writing-923", title: "Housing society notice about pet rules in the garden", category: "writing", text: "Write a polite housing society notice about pet rules in the garden, asking owners to keep dogs on a leash, clean up after them, avoid the children play area, and use the garden only between [time] and [time]." },
  { id: "writing-924", title: "Housing society notice about garbage segregation", category: "writing", text: "Write a firm but polite housing society notice about garbage segregation, explaining wet, dry and reject waste, the collection timings, and asking every flat to use separate bins from [date] to keep our building clean." },
  { id: "writing-925", title: "Housing society notice about CCTV installation", category: "writing", text: "Write an informative housing society notice about new CCTV cameras at the gate, lift and parking area from [date], explaining they are for safety only, and giving the secretary contact [phone] for any questions." },
  { id: "writing-926", title: "Housing society notice about annual maintenance collection", category: "writing", text: "Write a polite housing society notice about annual maintenance collection of [amount] per flat, due by [date], giving the payment options [options], and thanking residents who have already paid on time." },
  { id: "writing-927", title: "Housing society notice about pest control visit", category: "writing", text: "Write a clear housing society notice about a pest control visit on [date] from [time], asking residents to keep food covered, keep children and pets away during spraying, and inform [name] if they need their flat treated." },
  { id: "writing-928", title: "Housing society notice about terrace use on weekends", category: "writing", text: "Write a polite housing society notice about terrace use on weekends, giving the timings [time] to [time], asking residents to book the terrace in advance, keep it clean, and avoid loud music after 9 pm." },
  { id: "writing-929", title: "Housing society notice about a cultural programme fund", category: "writing", text: "Write a cheerful housing society notice about a cultural programme fund, asking each flat to contribute [amount] by [date] for the annual day, listing the planned events, and inviting volunteers to help organise." },
  { id: "writing-930", title: "Housing society notice about a fire safety drill", category: "writing", text: "Write a clear housing society notice about a fire safety drill on [date] at [time], explaining the assembly point [place], asking all residents to join, and reminding families to keep the staircase and exit clear." },
  { id: "writing-931", title: "Housing society notice about a new watchman joining", category: "writing", text: "Write a welcoming housing society notice introducing our new watchman [name], who joins from [date], giving his duty timings, asking residents to greet him kindly, and sharing the secretary number for any concern." },
  { id: "writing-932", title: "Housing society notice about a borewell repair", category: "writing", text: "Write a clear housing society notice about a borewell repair on [date], saying water supply may be low for [hours], asking residents to use water carefully, and promising an update from the secretary by evening." },
  { id: "writing-933", title: "Housing society notice about a children's play area timing", category: "writing", text: "Write a polite housing society notice about children play area timings from [time] to [time], asking parents to supervise young children, avoid cycles inside the play area, and report any broken equipment to [name]." },
  { id: "writing-934", title: "Community announcement for a blood donation camp", category: "writing", text: "Write a warm community announcement for a blood donation camp on [date] at [venue] from [time], inviting healthy adults to donate, explaining who can donate, and thanking donors in advance for saving lives in our area." },
  { id: "writing-935", title: "Community announcement for a free eye check-up camp", category: "writing", text: "Write a helpful community announcement for a free eye check-up camp on [date] at [venue] from [time], inviting senior citizens and children, mentioning free spectacles for those who need them, and asking people to bring an ID card." },
  { id: "writing-936", title: "Community announcement for a tree plantation morning", category: "writing", text: "Write a cheerful community announcement for a tree plantation morning on [date] at [place] from [time], inviting families to plant saplings, bring a water bottle and gloves, and promising a small breakfast after planting." },
  { id: "writing-937", title: "Community announcement for a cleanliness drive in our lane", category: "writing", text: "Write a motivating community announcement for a cleanliness drive in our lane on [date] from [time], inviting residents to bring brooms and bags, clean the street together, and enjoy tea and snacks after the work." },
  { id: "writing-938", title: "Community announcement for a free yoga session in the park", category: "writing", text: "Write a welcoming community announcement for a free yoga session in the park every [day] at [time], inviting beginners of all ages, asking them to bring a mat and water bottle, and mentioning the trainer [name]." },
  { id: "writing-939", title: "Community announcement for a cricket match between streets", category: "writing", text: "Write an exciting community announcement for a friendly cricket match between [street one] and [street two] on [date] at [ground] from [time], inviting players and families to cheer, and promising prizes for the winning team." },
  { id: "writing-940", title: "Community announcement for a book donation collection", category: "writing", text: "Write a kind community announcement for a book donation collection from [date] to [date] at [place], asking residents to donate school books and storybooks in good condition for children in nearby villages." },
  { id: "writing-941", title: "Community announcement for a food donation for festival week", category: "writing", text: "Write a generous community announcement for a food donation during festival week, asking families to donate rice, dal and oil at [place] by [date], so volunteers can pack food kits for needy families nearby." },
  { id: "writing-942", title: "Community announcement for a free tuition class for children", category: "writing", text: "Write a helpful community announcement for a free tuition class for children from class [class] to [class], held at [place] on [days] at [time], inviting parents to enrol their children by calling [phone]." },
  { id: "writing-943", title: "Community announcement for a senior citizens' tea meet", category: "writing", text: "Write a warm community announcement for a senior citizens tea meet on [date] at [venue] from [time], inviting elders for tea, snacks, bhajans and friendly talks, and asking families to bring their parents and grandparents along." },
  { id: "writing-944", title: "Community announcement for a rainwater harvesting workshop", category: "writing", text: "Write an informative community announcement for a rainwater harvesting workshop on [date] at [venue] from [time], inviting flat owners to learn simple, low-cost ways to save rainwater, with a question session at the end." },
  { id: "writing-945", title: "Community announcement for a neighbourhood safety meeting", category: "writing", text: "Write a clear community announcement for a neighbourhood safety meeting on [date] at [venue] from [time], inviting residents to discuss street lights, CCTV and night patrol, and to share suggestions with the local police officer." },
  { id: "writing-946", title: "Message to support a local food bank", category: "writing", text: "Write a heartfelt message asking neighbours to support our local food bank, explaining that many families nearby need rice and dal, giving the drop point [place] and timings, and thanking everyone who donates even one packet." },
  { id: "writing-947", title: "Message asking neighbours to save water this summer", category: "writing", text: "Write a polite message asking neighbours to save water this summer, suggesting short showers, fixing leaks, reusing RO water for plants, and reminding everyone that our borewell level is falling and every litre counts." },
  { id: "writing-948", title: "Message for a plastic-free festival celebration", category: "writing", text: "Write a cheerful message asking our building to celebrate [festival] without plastic, suggesting cloth bags, steel plates and paper decorations, and explaining how this small change keeps our streets and drains clean." },
  { id: "writing-949", title: "Message to donate old clothes after Diwali cleaning", category: "writing", text: "Write a kind message asking families to donate old clothes after Diwali cleaning, giving the collection point [place] and last date [date], and explaining that clean, usable clothes will go to children in nearby villages." },
  { id: "writing-950", title: "Message to help an elderly neighbour with groceries", category: "writing", text: "Write a caring message asking young neighbours to help elderly neighbour [name] with groceries, offering to pick up milk, medicines and vegetables on their weekly market trip, and giving her phone number [phone] for requests." },
  { id: "writing-951", title: "Message to feed street dogs responsibly", category: "writing", text: "Write a balanced message about feeding street dogs responsibly in our lane, suggesting a fixed feeding spot away from homes, clean bowls, and leftover rice, while asking feeders to keep the area clean afterwards." },
  { id: "writing-952", title: "Message to plant a tree on a birthday", category: "writing", text: "Write a joyful message inviting friends to plant a tree on [name] birthday instead of buying a gift, explaining the planting spot [place], the time [time], and how the tree will grow as a living memory." },
  { id: "writing-953", title: "Message to share leftover food instead of wasting it", category: "writing", text: "Write a practical message asking families to share leftover food instead of wasting it, suggesting packing extra rotis and sabzi for the watchman or a needy neighbour, and reminding everyone that small sharing makes a big difference." },
  { id: "writing-954", title: "Message to keep our park clean after evening play", category: "writing", text: "Write a polite message asking children and parents to keep our park clean after evening play, reminding them to use the dustbins, take snack wrappers home, and leave the swings and benches tidy for the next morning." },
  { id: "writing-955", title: "Message inviting my cousin to stay for Diwali", category: "writing", text: "Write a warm message inviting my cousin [name] to stay with us for Diwali from [date] to [date], describing our plans for rangoli, sweets and fireworks, and saying our home and guest room are ready for her family." },
  { id: "writing-956", title: "Thank-you note to our milkman", category: "writing", text: "Write a simple thank-you note to our milkman [name], thanking him for delivering fresh milk every morning without fail, even in rain, and wishing him and his family good health and happiness for the year ahead." },
  { id: "writing-957", title: "Thank-you note to our building watchman", category: "writing", text: "Write a warm thank-you note to our building watchman [name], thanking him for keeping our building safe at night, helping with parcels and parking, and wishing him a happy festival with a small gift from our family." },
  { id: "writing-958", title: "Thank-you note to our housemaid", category: "writing", text: "Write a heartfelt thank-you note to our housemaid [name], thanking her for her honest work, care for our home and children, and kindness over [number] years, and wishing her family health and happiness always." },
  { id: "writing-959", title: "Thank-you note to my tailor", category: "writing", text: "Write a polite thank-you note to my tailor [name], thanking him for stitching my [garment] so neatly and on time for [occasion], praising the perfect fitting, and saying I will recommend his shop to my friends." },
  { id: "writing-960", title: "Thank-you note to an auto driver who helped me", category: "writing", text: "Write a grateful thank-you note to an auto driver [name] who helped me when [incident], thanking him for his honesty and kindness, and saying his help restored my faith in strangers in our city." },
  { id: "writing-961", title: "Thank-you note to a plumber who fixed a leak at night", category: "writing", text: "Write a grateful thank-you note to a plumber [name] who fixed a leak at our home late at night, thanking him for coming quickly, working patiently, and charging a fair price, and promising to call him first next time." },
  { id: "writing-962", title: "Thank-you note to a vegetable vendor", category: "writing", text: "Write a friendly thank-you note to a vegetable vendor [name], thanking him for fresh vegetables, fair prices and honest weighing for [number] years, and wishing his small shop steady customers and good health." },
  { id: "writing-963", title: "Thank-you note to a librarian who saved a book for me", category: "writing", text: "Write a polite thank-you note to a librarian [name] who saved the book [title] for me, thanking her for remembering my request, and saying her kindness made my reading week and my visit to the library special." },
  { id: "writing-964", title: "Thank-you note to a bus conductor who returned my bag", category: "writing", text: "Write a grateful thank-you note to a bus conductor [name] who returned my bag on bus [number], thanking him for his honesty, describing the relief I felt, and wishing him and his family all the best." },
  { id: "writing-965", title: "Thank-you note to a pharmacist who explained my medicine", category: "writing", text: "Write a polite thank-you note to a pharmacist [name] who explained my medicine patiently, thanking him for telling me the dosage, timing and precautions in simple words, and saying his guidance helped me recover with confidence." },
  { id: "writing-966", title: "Thank-you note to a friend who cooked for me when I was ill", category: "writing", text: "Write a heartfelt thank-you note to my friend [name] who cooked for me when I was ill, thanking her for the hot khichdi, daily calls and care, and promising to cook her favourite meal once I feel better." },
  { id: "writing-967", title: "Thank-you note to my aunt for a handmade sweater", category: "writing", text: "Write a loving thank-you note to my aunt [name] for a handmade sweater, describing its warm colour and soft wool, saying I wear it every cold morning, and thanking her for the love stitched into every row." },
  { id: "writing-968", title: "Caption for a family picnic photo in the park", category: "writing", text: "Write three short, warm captions for a family picnic photo in the park, mentioning homemade food, games under the trees, and laughter, in simple English that works on WhatsApp and Instagram without any hashtags." },
  { id: "writing-969", title: "Caption for a monsoon chai photo at home", category: "writing", text: "Write three short, cosy captions for a monsoon chai photo at home, mentioning rain outside, hot chai, a favourite cup, and a quiet moment, in simple English that feels personal and warm." },
  { id: "writing-970", title: "Caption for a temple visit photo with my parents", category: "writing", text: "Write three short, respectful captions for a temple visit photo with my parents, mentioning blessings, morning prayers and family togetherness, in simple English that feels devotional without sounding formal." },
  { id: "writing-971", title: "Caption for a childhood photo with my siblings", category: "writing", text: "Write three short, nostalgic captions for a childhood photo with my siblings, mentioning old clothes, shared fights and laughter, and how those days still feel close, in simple, heartfelt English." },
  { id: "writing-972", title: "Caption for a sunset photo from my balcony", category: "writing", text: "Write three short, peaceful captions for a sunset photo from my balcony, mentioning orange skies, evening tea and the end of a long day, in simple English that feels calm and hopeful." },
  { id: "writing-973", title: "Caption for a birthday cake photo with my grandmother", category: "writing", text: "Write three short, loving captions for a birthday cake photo with my grandmother, mentioning her smile, blessings and the cake she cut, in simple English that celebrates family across generations." },
  { id: "writing-974", title: "Caption for a train window photo on a hill journey", category: "writing", text: "Write three short, dreamy captions for a train window photo on a hill journey, mentioning green valleys, clouds, slow travel and a window seat, in simple English that captures the joy of the journey." },
  { id: "writing-975", title: "Caption for a street food photo in my city", category: "writing", text: "Write three short, tasty captions for a street food photo in my city, mentioning [dish], the busy stall, the first bite, and the crowd around it, in simple English that makes readers hungry." },
  { id: "writing-976", title: "Caption for a rangoli photo outside my door", category: "writing", text: "Write three short, festive captions for a rangoli photo outside my door, mentioning bright colours, morning flowers and festival joy, in simple English that celebrates a beautiful Indian tradition at home." },
  { id: "writing-977", title: "Caption for a first day of school photo", category: "writing", text: "Write three short, sweet captions for a first day of school photo, mentioning a new bag, a nervous smile and a proud parent, in simple English that captures this small but big milestone." },
  { id: "writing-978", title: "Caption for a reunion photo with college friends", category: "writing", text: "Write three short, joyful captions for a reunion photo with college friends, mentioning old jokes, canteen memories and meeting after years, in simple English that feels warm and full of laughter." },
  { id: "writing-979", title: "Message to my child's teacher asking for extra help", category: "writing", text: "Write a polite message to my child teacher [name], asking for extra help in [subject], explaining that my child [name] finds [topic] difficult, and requesting a short meeting or simple practice work for home." },
  { id: "writing-980", title: "Travel note about a morning in a temple town", category: "writing", text: "Write a travel note about a morning in the temple town [town], describing the early bells, flower sellers, clean streets, a simple breakfast, and the peaceful feeling of starting the day with prayers." },
  { id: "writing-981", title: "Travel note about a train journey through green fields", category: "writing", text: "Write a travel note about a train journey through green fields from [place] to [place], describing paddy fields, small stations, chai sellers, and the slow, happy feeling of watching India pass by the window." },
  { id: "writing-982", title: "Travel note about a beach evening with my family", category: "writing", text: "Write a travel note about a beach evening with my family at [beach], describing the sea breeze, children playing in the sand, coconut water, sunset colours, and why this simple evening felt perfect." },
  { id: "writing-983", title: "Travel note about a hill station stay in winter", category: "writing", text: "Write a travel note about a hill station stay in winter at [place], describing cold mornings, woollen shawls, hot soup, mist over the valley, and a quiet walk that made the whole trip feel special." },
  { id: "writing-984", title: "Travel note about a food walk in an old city lane", category: "writing", text: "Write a travel note about a food walk in an old city lane in [city], describing the smells of frying snacks, tiny shops, a kind shopkeeper, the dishes I tasted, and the stories behind each stall." },
  { id: "writing-985", title: "Travel note about a river boat ride at sunrise", category: "writing", text: "Write a travel note about a river boat ride at sunrise in [place], describing the calm water, fishermen, temple bells from the bank, golden light, and the quiet joy of floating slowly with my family." },
  { id: "writing-986", title: "Travel note about a village fair I visited", category: "writing", text: "Write a travel note about a village fair I visited in [village], describing colourful stalls, folk music, sugarcane juice, children on the giant wheel, and the warm welcome I received from local families." },
  { id: "writing-987", title: "Travel note about a night stay in a mountain homestay", category: "writing", text: "Write a travel note about a night stay in a mountain homestay in [place], describing the wooden room, home-cooked dinner, stars above the hills, morning birdsong, and the kindness of the host family." },
  { id: "writing-988", title: "Travel note about a bus ride to my native place", category: "writing", text: "Write a travel note about a bus ride to my native place [village], describing the early morning start, familiar fields, old songs on the radio, and the excitement of reaching home after a long time." },
  { id: "writing-989", title: "Travel note about a heritage walk in my town", category: "writing", text: "Write a travel note about a heritage walk in my town [town], describing an old temple, a historic house, narrow lanes, a local guide stories, and what this walk taught me about my own town." },
  { id: "writing-990", title: "Travel note about a monsoon trek with friends", category: "writing", text: "Write a travel note about a monsoon trek with friends to [place], describing wet paths, green hills, raincoats, shared snacks, laughter on the climb, and the view from the top that made it worthwhile." },
  { id: "writing-991", title: "Travel note about a quiet lake morning", category: "writing", text: "Write a travel note about a quiet lake morning at [lake], describing still water, morning mist, birds, a slow walk around the lake, and the calm feeling that stayed with me for the whole day." },
  { id: "writing-992", title: "Food note about my grandmother's pickle recipe", category: "writing", text: "Write a food note about my grandmother pickle recipe for [pickle], describing the sun-dried chillies, mustard oil, her careful hands, the smell in the kitchen, and why no shop pickle ever tastes the same." },
  { id: "writing-993", title: "Food note about a tiffin my mother packed", category: "writing", text: "Write a food note about a tiffin my mother packed for [occasion], describing the rotis, sabzi and pickle, the cloth wrapping, the love in every bite, and how that tiffin still tastes like home." },
  { id: "writing-994", title: "Food note about festival sweets made at home", category: "writing", text: "Write a food note about festival sweets made at home for [festival], describing the ghee, sugar and nuts, the whole family helping in the kitchen, and the joy of sharing the first plate with neighbours." },
  { id: "writing-995", title: "Food note about a street chaat I love", category: "writing", text: "Write a food note about a street chaat I love at [stall] in [city], describing the tangy chutneys, crunchy base, the vendor skill, the crowd waiting, and why I return to this stall every time I visit." },
  { id: "writing-996", title: "Food note about a simple khichdi on a rainy day", category: "writing", text: "Write a food note about a simple khichdi on a rainy day, describing hot rice and dal, ghee on top, papad and pickle beside it, and why this humble meal feels like comfort on a wet, grey evening." },
  { id: "writing-997", title: "Food note about a Jain thali at a family lunch", category: "writing", text: "Write a food note about a Jain thali at a family lunch, describing the rotis, dal, sabzi without onion and garlic, rice, salad and sweet, and how the meal brought three generations together at one table." },
  { id: "writing-998", title: "Food note about a filter coffee morning in Chennai", category: "writing", text: "Write a food note about a filter coffee morning in Chennai, describing the strong decoction, frothy milk, steel tumbler, the sound of pouring, and a slow breakfast of idli with sambar beside it." },
  { id: "writing-999", title: "Food note about a mango season memory", category: "writing", text: "Write a food note about a mango season memory, describing the first Alphonso of the year, sticky hands, sharing slices with siblings, the smell of summer, and why mangoes always remind me of childhood holidays." },
  { id: "writing-1000", title: "Message to my tailor about stitching a blouse", category: "writing", text: "Write a polite message to my tailor [name] about stitching a blouse, giving the cloth details, the design [design], the fitting date [date], and asking him to confirm the stitching charge and delivery date." },
  { id: "writing-1001", title: "Cover letter for a volunteer role at a local NGO", category: "writing", text: "Write a cover letter for a volunteer role at [NGO name] where I want to help with [work, e.g. teaching children]. Mention one skill I can offer, why this cause matters to me, and how many hours a week I can give. Keep it warm, honest, and under 150 words." },
  { id: "writing-1002", title: "Letter to my bank asking to update my mobile number", category: "writing", text: "Write a letter to my bank asking them to update my mobile number from [old number] to [new number] for my account [account number]. Ask them to confirm once it is done, and mention I have attached my ID proof. Keep it formal, short, and polite." },
  { id: "writing-1003", title: "Thank-you note to a neighbour who watered my plants while I was away", category: "writing", text: "Write a warm thank-you note to my neighbour [name] who watered my plants while I was away for [number] days. Mention one plant that is doing especially well, and offer a small homemade gift in return. Keep it under 80 words and friendly, like a note left at their door." },
  { id: "writing-1004", title: "Speech for a housewarming party as the host", category: "writing", text: "Write a short speech for me as the host of my housewarming party. Welcome my guests, thank the people who helped me move in, share one happy memory of finding this home, and invite everyone to enjoy the food. Keep it under 200 words and warm." },
  { id: "writing-1005", title: "Story about a postman who delivers a letter to the wrong house", category: "writing", text: "Write a funny short story about a postman who delivers a letter to the wrong house in [town], and what the two neighbours discover when they open it together. Keep it under 300 words, gentle and warm, with a happy ending for both families." },
  { id: "writing-1006", title: "Poem about a streetlight that never turns off", category: "writing", text: "Write a short poem about a streetlight in [my street] that never turns off, even in the morning. Give it a gentle, wondering tone, mention the people who pass under it, and end with one hopeful line. Keep it under 12 lines and simple enough for a school child." },
  { id: "writing-1007", title: "Essay on whether children should get pocket money", category: "writing", text: "Write a school essay on whether children should get pocket money. Give 3 reasons for and 3 reasons against, with one small real-life example for each side, then end with my own balanced opinion. Keep it around 250 words and in simple, clear English." },
  { id: "writing-1008", title: "Blog post explaining why I chose handmade over machine-made", category: "writing", text: "Write a blog post explaining why I chose handmade over machine-made for my [product]. Share one honest reason about quality, one about the makers, and one about what customers notice first. End with a question asking readers what handmade means to them. Keep it under 250 words." },
  { id: "writing-1009", title: "Message to a supplier asking for a small trial order first", category: "writing", text: "Write a polite message to a supplier asking if I can place a small trial order of [quantity] before committing to a bulk order. Explain I am a new shop, ask about the trial price and delivery time, and thank them for understanding. Keep it under 80 words and professional." },
  { id: "writing-1010", title: "Invitation for a farewell lunch for a retiring watchman", category: "writing", text: "Write a warm invitation for a farewell lunch for our building's watchman [name], who is retiring after [number] years. Mention his morning greetings and his care for our children, and invite all flat owners to join. Keep it under 100 words and heartfelt." },
  { id: "writing-1011", title: "Application for a street vendor licence", category: "writing", text: "Write an application to the municipal office asking for a street vendor licence for my [stall, e.g. fruit cart] at [location]. Mention how long I have sold there, promise to keep the spot clean, and list the papers I have attached. Keep it formal, respectful, and under 120 words." },
  { id: "writing-1012", title: "Email to an online course provider asking for a course completion certificate", category: "writing", text: "Write an email to [course provider] asking for my completion certificate for the course [course name], which I finished on [date]. Mention my registered email and order ID, and ask how many days it will take. Keep it polite, clear, and under 80 words." },
  { id: "writing-1013", title: "Dialogue between a mosquito and a ceiling fan", category: "writing", text: "Write a funny dialogue between a mosquito and a ceiling fan in a bedroom at midnight. The mosquito complains about the wind, the fan answers proudly, and they end up making a deal. Keep it under 200 words, with short lines and simple words a school child can enjoy." },
  { id: "writing-1014", title: "Diary entry about a power cut that turned into a family evening", category: "writing", text: "Write a diary entry about a power cut at home that turned into a lovely family evening. Describe the candles, the stories my [grandmother/father] told, and one game we played without any screens. Keep it under 200 words, warm, and in the first person." },
  { id: "writing-1015", title: "Children's story about a kite that gets stuck on a temple tower", category: "writing", text: "Write a children's story about a kite that gets stuck on a temple tower in [town], and how a kind [priest/child] helps bring it down before the festival. Keep it under 300 words, gentle, with one small lesson about asking for help." },
  { id: "writing-1016", title: "Folk tale about a tailor who sews a coat for the wind", category: "writing", text: "Write a folk tale about a tailor in [village] who tries to sew a coat for the wind. Show three funny attempts that fail, then a clever ending where the wind finally gets what it needs. Keep it under 300 words and in simple, storybook language." },
  { id: "writing-1017", title: "Limerick about a teacher who forgets her own homework", category: "writing", text: "Write a funny limerick about a teacher who forgets her own homework on the way to school. Keep the classic five-line rhythm, make the last line a cheerful surprise, and use simple words a child can read aloud and enjoy." },
  { id: "writing-1018", title: "Haiku about a rainy bus ride", category: "writing", text: "Write a set of 3 haikus about a rainy bus ride through [city/town]. Each haiku should follow the 5-7-5 syllable pattern, capture one small moment like wet windows or shared umbrellas, and use simple, clear images. Keep the whole set gentle and calm." },
  { id: "writing-1019", title: "Plot idea a library book that returns itself every night", category: "writing", text: "Give me a plot idea for a story about a library book that returns itself to the shelf every night. Include the main character, why the book keeps coming back, and one twist that changes everything. Keep it under 150 words and full of mystery." },
  { id: "writing-1020", title: "Short story about a woman who sells umbrellas only on sunny days", category: "writing", text: "Write a short story about a woman in [town] who sells umbrellas only on sunny days, and the surprising reason her customers love her shop. Keep it under 300 words, warm and a little mysterious, with a happy ending." },
  { id: "writing-1021", title: "Character sketch of a night watchman who knows every street dog by name", category: "writing", text: "Write a character sketch of a night watchman in [area] who knows every street dog by name. Describe his walk, his torch, one small habit, and why the whole street trusts him. Keep it under 200 words, warm, and full of small, true-feeling details." },
  { id: "writing-1022", title: "Travel note about a night train halt at a small station", category: "writing", text: "Write a travel note about a night train halt at a small station in [place]. Describe the tea seller's call, the cool air, and one stranger I spoke to for two minutes. Keep it under 200 words, calm, and in the first person, like a page from a diary." },
  { id: "writing-1023", title: "Food note about the first mango of the season", category: "writing", text: "Write a food note about the first mango of the season at my home in [town]. Describe its smell, who cut it, and who got the first slice, then end with one line about what summer means to my family. Keep it under 150 words and full of warmth." },
  { id: "writing-1024", title: "Job post for a night watchman for my shop", category: "writing", text: "Write a job post for a night watchman for my shop in [area]. Mention the working hours, one month's salary range, and two qualities I need, like honesty and alertness. Add how to apply by phone or in person. Keep it clear, respectful, and under 100 words." },
  { id: "writing-1025", title: "Product description for a hand-painted diya set", category: "writing", text: "Write a product description for a hand-painted diya set of [number] pieces for Diwali. Mention the colours, the painter's handwork, and how to care for them after use. Keep it warm, honest, and under 120 words, without promising anything the product cannot do." },
];
